PRESENTACIÓN
La am plitud del Derecho impide que en un solo texto pueda resumirse toda la teoría necesaria
para considerarque se conocen los conceptos, institucionesy figuras jurídicas que conforman
todasy cada una de las ramas de la ciencia jurídica. Ni siquiera la clásica y reconocida Enciclo
pedia Jurídica Omeba ha podido lograr ese propósito, puesto que el Derecho avanza al ritm o
que avanza la humanidad, en lo social, tecnológico y comercial, y antiguas teorías quedan
atrás en muy poco tiempo.
Para conocer el Derecho, para ser Abogado en particular, decía el maestro Couture es necesa
rio estudiar, so pena de ser menos abogado cada día. En consecuencia, la abogacía exige un
compromiso de disciplina académica constante y permanente, a fin de atender los cambios
cotidianos que sufren las relaciones humanas,y por consiguiente las relaciones jurídicas.
El propósito del presente trabajo no es, entonces, colmar la exigencia de conocimientos que
permitirán que un abogado llegue a ser magistrado en el sistema de justicia peruano; tam po
co lo podría ser, puesto que su estrechez no lo permitiría. Sin embargo, buscamos que sirva de
una herramienta útil y práctica, destinada a esclarecer las dudas conceptuales que siempre se
presentan a quien se dedica, en su ejercicio profesional, a un área determinada del quehacer
jurídico.
El propio magistrado que se halla desempeñando la función en una especialización concreta,
con seguridad, requiere de un apoyo práctico a fin de hacer una reminiscencia de la teoría
que ha dejado atrás, en las aulas universitarias inclusive, respecto de áreas ya no consultadas
diariamente; he ahí nuestro objetivo, ayudarlo a repasar esos conceptos con los que no se en
cuentran todos los días.
Esperamos colmar la expectativa de quienes han confiado en adquirir un texto resumen que
sirva de guía en su formación académicay en su propósito de afianzarsus conocimientos a fin
de acceder a la magistratura. Hemos desarrollado la tarea con mucho ahínco, y con bastante
empeño, por lo que el saber que estas líneas están siendo leídas, nos hace confiar en que he
mos llegado a contribuir en algo a su formación.
Los editores.
