1. LA NORMA JURIDICA
Definición: La norma jurídica es un precepto de naturaleza imperativa elaborado e instituido
por la respectiva autoridad competente con la final idad de regular la conducta social del hom
bre. El vocablo "imperativo” implica específicamente una orden de carácter obligatorio que lle
va consigo una sanción estatal en caso de que fuese inobservada.
La norma jurídica es completamente distinta de la norma moral debido a que es heterónoma
lo que quiere decir que no requiere, para su validez, de la adhesión íntima del sujeto, sino
que impera sobre él. Además, por lo general, una norma jurídica impone deberes y confiere
derechos, aunque es frecuente que ciertas normas determinen sólo deberes o sólo derechos,
en cuyo caso son integradas por otras normas del mismo ordenamiento jurídico al cual per
tenecen.
Las normas jurídicas constituyen enunciados que correlacionan una conducta con una deter
minada consecuencia normativa,ya sea como: i) una obligación; ii) una autorización o permi
so; iii) una prohibición.
No es necesario que un sistema normativo esté constituido sólo por normas. Puede estar
constituido por normasy otros enunciados, sin que por ello deje de ser un sistema normativo.
Pero se debe tener en claro que no se debe confundir “norma jurídica” con “texto normativo”.
El texto normativo, como tal, es una expresión lingüística. Todo ordenamiento jurídico está
compuesto en su mayor parte por textos normativos. La norma jurídica en un precepto, es el
sentido que el jurista desprende del texto normativo.
Mario Alzamora Valdez, manifiesta que la Norma Jurídica, pertenece a la categoría de los ob
jetos culturales, constituye una estructura lógica que expresa el “debe ser” de una conducta di
rigida hacia determinado valor o valores. Formalmente la norma es un juicio a que se traduce
mediante una proposición, su contenido está formado por ios objetos que menciona.
1.1. Elementos de la norma jurídica:
Los elementos de la norma jurídica, desde el punto de vista lógico-jurídico son tres:
i. El supuesto o presupuesto de hecho
El supuesto es la hipótesis que formula el autor de la norma jurídica para que, de veri
ficarse u ocurrir en la realidad, se desencadene lógico jurídicamente la necesidad de la
consecuencia.
