íi. La consecuencia o efecto Jurídico
La consecuencia es el efecto que el autor de la norma jurídica atribuye, lógico jurídica
mente, a la verificación del supuesto en la realidad.
iii. El nexo jurídico
El nexo elemento vinculante entre supuesto y consecuencia, con un carácter de “debe ser”
que lo ubica en al ámbito de la necesidad lógico-jurídica.
La estructura lógica que conforman los elementos de una norma jurídica es la siguiente:
