2. ORDENAMIENTO JURÍDICO
El ordenamiento jurídico es el conjunto de normas jurídicas que rigen en un lugar determina
do en una época concreta. En el caso de los estados democráticos, el ordenamiento jurídico
está formado por la Constitución del Estado, que se erige como la norma suprema, por las
leyes del poder ejecutivo, tales como los reglamentos, y otras regulaciones tales como los tra
tados, convenciones, contratos y disposiciones particulares.
No se debe confundir el ordenamiento jurídico con el “orden jurídico”, que se traduce en el
conjunto de normas que rigen una determinada área del ordenamiento jurídico. La relación
entre estos dos conceptos es de género a especie.
2.1. Características
El ordenamiento jurídico tiene algunos caracteres que lo configuran como,tal.
Es complejo, porque está compuesto por una cantidad de normas que nadie sabe cuántas
son. La complejidad se debe a que la necesidad que tiene cualquier sociedad de regular
las conductas de sus asociados es tan grande, que no hay ningún poder capaz de satisfa
cerla por sí misma.
Es coherente, porque el ordenamiento jurídico es una totalidad armónica ordenada, o sea,
que las normas que lo componen tienen una relación de compatibilidad que im posibilita
toda contradicción entre ellas. A las contradicciones normativas también se las llama an
tinomias.
Es autónomo, porque existen diferentes ordenamientos jurídicos entre los países, cada
uno con su propia organicidady lógica de interacción con su sociedad.
Es unitario, porque todas sus normas convergen en una norma fundamental única que es la
Constitución, de la cual se derivan directa o indirectamente en sucesivos grados o escalones
hasta llegara las normas más concretas: leyes generales, decretos, reglamentos, etc.
Es pleno, porque supuestamente contiene normas para regular todos y cada uno de los
hechos de la vida de relación social que reclaman su regulación por el Derecho. La píeni-
