Tema 1: Sistema Norm ativo Nacional
tud del ordenamiento jurídico es una exigencia, no una realidad; es más un ideal que una
realidad, por consiguiente, no hay Derecho positivo que esté libre de lagunas.
Es sistemático, porque el ordenamiento jurídico es el conjunto sistemático de normas ju-
rídico-positivas ordenadas en un todo coherente (el Derecho positivo de un país), bajo
el criterio de unidad que es la Constitución. La doctrina más autorizada concluye que el
ordenamiento jurídico es sistemático. Así, por ejemplo, Kelsen, concibe al ordenamiento
jurídico como sistema normativo, lo caracteriza como la unión de reglas primarias que
imponen deberesy secundarias que confieren potestades públicas o privadas.
2.2. Jerarquía normativa
El ordenamiento jurídico está integrado solamente por normas jurídicas válidas; las normas
inválidas están fuera del Derecho. Para establecer si una norma pertenece o no al ordena
miento jurídico hay que pasar de grado en grado, de poder en poder, hasta llegar a la norma
fundamental. De este modo todas las normas están vinculadas directa o indirectamente con
la norma fundamental que es la que da validez y unidad al complejo y enmarañado ordena
miento jurídico. Poreso, la norma fundamental se coloca, al estilo kelseniano, en el vértice del
sistema, porque con ella se relacionan todas las otras normas. En este sentido es acertado el
razonamiento de Bobbio, cuando expresa: "La norma fundamental es el criterio supremo que
permite establecer la pertinencia de una norma a un ordenamiento, en otras palabras, es el
fundamento de validez de todas las normas del sistema. Por lo tanto, no sólo la exigencia de
la unidad del ordenamiento sino también la exigencia de fundar la validez del ordenamiento
nos llevan a exigir la norma fundamental, la cual es, asimismo, el fundamento de validezy el
principio unificador de las normas de un ordenamiento. Y como un ordenamiento presupone
la existencia de un criterio para establecer la pertinencia de las partes al todo y un principio
que las unifique, no podrá existir ordenamiento sin norma fundam ental”.
En el Perú tenemos un sistema m últiple de control de la constitucionalidad de las leyes. El
control político está consagrado por el artículo 102o inc. z de la Constitución Política, que dice:
"Son atribuciones del Congreso... 2. Velar por el respeto de la Constitución y de las leyes, y disponer lo
conveniente para hacer efectiva la responsabilidad de los infractores”. El control difuso está estableci
do en el segundo párrafo del artículo 138° de la Constitución Política que expresa: "En todo pro
ceso, de existir incompatibilidad entre una norma constitucional y una norma legal, los jueces prefieren
la primera. Igualmente, prefieren la norma legal sobre toda otra norma de rango inferior”; y el control
concentrado está a cargo del Tribunal Constitucional (artículo 201o al 205o de la Constitución
Política).
Los requisitos para que una norma pueda condicionar la validez de otra son:
