2.3. Estructura jerárquica deS ©rdenamient© jurídico peruano
El artículo 51o de la actual norma fundamental dice: “La Constitución prevalece sobre toda norma
legal, sobre las normas de in ferior jerarquía, y así sucesivamente”. Aunque no menciona la forma
específica de establecer la jerarquía normativa de nuestro sistema de fuentes, puesto que ésta
cuenta con diversos criterios para determinarla (el rango de las normas, la costumbre, etc.),
puede clasificarse dicha jerarquía normativa en cinco categorías, según el siguiente esquema:
1. PRIMERA CATEGORÍA: Normas constitucionales y normas con rango constitucional.
1.1. 1er grado-1=»Constitución. - Es la norma primaria del ordenamiento legal, constituye
el marco dentro del cual deben ubicarse las normas jurídicas. Contiene entre otros,
los principios básicos que permiten asegurar los derechos y deberes de las personas,
así como la organización, funcionamiento y responsabilidad del Estado. Prima sobre
cualquier otra norma jurídicay es expedida por el Congreso Constituyente.
La Constitución es, pues, norma jurídicay, como tal, vincula. De ahí que, con acierto,
pueda hacerse referencia a ella aludiendo al “Derecho de la Constitución", esto es, al
conjunto de valores, derechos y principios que, por pertenecer a ella, limitan y deli
mitan jurídicamente los actos de los poderes públicos1.
La supremacía normativa de la''.Constitución''de 1993 se encuentra recogida en sus dos vertientes:
tanto aquella objetiva, conforme a la cual la Constitución preside: el ordenamiento jurídico (artículo
51 °3), como aquella subjetiva, en cuyo mérito ningún acto de los poderes públicos .(artículo 45° 4) o
de la colectividad en general (artículo 38° 5) puede vulnerarla válidamente2, v X.
1.2. 2do grado:
• Leyes constitucionales.- Son aquellas que materializan una reforma constitu
cional. Mediante un procedimiento especial de aprobación, previsto en el artí
culo 206o de nuestra actual Constitución, interpreta, modifica, sustituye, deroga
o abroga una norma constitucional.
9 Tratados de derechos humanos.- Son aquellas expresiones de voluntad que
adopta el Estado con organismos extranacionales, que están dirigidos a salva
guardas y promocionar los derechos inherentes a la persona.
• Tratados con habilitación legislativa.- Son convenios que contienen estipu
laciones que afectan normas constitucionales, pero que, por intervención del
Congreso de la República, mediante un procedimiento especial previsto en el
artículo 57 de la Constitución,, el mismo que señala: Cuando el tratado afecte dis
posiciones constitucionales debe ser aprobado por el mismo procedimiento que rige la
reforma de la Constitución, antes de ser ratificado por el Presidente de la República.
