Tema 1: Sistema Norm ativo Nacional
2. SEGUNDA CATEGORÍA: Leyes y normas con rango de ley.
Las Leyes son instrumentos jurídicos de rango legal, sancionado por el Congreso Consti
tuyente, de conformidad con la facultad de legislar que le consagra el artículo 102 inciso
1) de la Constitución cuya aprobación corresponde a su Comisión Permanente, con ex
clusión de las materias relativas a reforma constitucional, aprobación de tratados, leyes
orgánicas, ley del Presupuesto y ley de la Cuenta General de la República.
La denominación de la ley es una facultad discrecional del Congreso (Ley N° 26889- Ley
Marco para la Producción y Sistematización Legislativa), así tenemos:
- Leyes generales.- Establecen principios comunes e integrados en una materia am
plia, compleja y polivalente, su implementación se hace mediante reglamentos y
actos ejecutivos, por ejemplo: Ley General de Educación.
- Leyes de Bases.- Es la ley de orden más general, establece los lineamientos normativos
sobre un aspecto o materia, pero sin entrar a detalle: en este sentido las especificacio
nes serán consignadas en otras leyes especiales, por ejemplo, la antigua Ley de Bases
de la Reforma Agraria.
- Leyes de Desarrollo.- Establecen los planes de orientación y planificación territorial.
Desarrollan el contenido de las leyes de Bases.
- Leyes Ordinarias.- Leyes q ue emanan de laelaboración, discusión y aprobación den
tro de las comisionesy del pleno del Congreso de la República como expresión de su
razón de ser, de acuerdo al procedimiento que fija la Constitución. Requiere mayoría
simple para su aprobación. Es de materia universal.
- Leyes Orgánicas.- Leyes que delinean la estructura y funcionamiento de las entida
des del Estado previstas en la Constitución, así como las materias que ésta expresa
mente contempla que se regulen por tales leyes. Requiere mayoría absoluta para
su aprobación. Es de materia reservada, por ejemplo, la Ley Orgánica del Tribunal
Constitucional.
- Tratados.- La Constitución les otorga rango legislativo a los tratados internacionales
que no versen sobre asuntos constitucionales ni traten específicamente asuntos re
ferentes a los derechos humanos, y siempre que hayan sido aprobados y ratificados
de acuerdo a derecho; sin embargo, en caso de conflicto normativo entre un trata-
d o y una ley, prevalecerá el primero. Asimismo, las normas de la Asamblea Regional
dictadas al amparo de la delegación de facultades legislativas, tienen también rango
legislativo. Una vez promulgadas por el Poder, en caso de conflicto normativo entre
una ley y una norma regional dictada en virtud de la delegación legislativa, debería
prevalecer esta última.
- Reglamento del Congreso.- Conforme al artículo 94 de la Constitución se reconoce
su existencia y se le asigna la característica de fuerza de ley, por lo tanto, surte los
mismos efectos y tiene igual alcance {erga omnes)3.
3 Artículo 94 modificado por la Ley N ° 31988, Ley de Reforma Constitucional que restablece la Bicameralidad
en el Congreso de la República del Perú, publicada el 15/03/2024, vigente a partir de las próximas elecciones
generales (abril del 2026).
