UBILEX
Es uns fuente primaria del derecho y, como tal, solo sometida a la Constitución (STC Exp. W 00006-
2003-AI/TC). ;
- Decretos Legislativos.- Es una norma jurídica con rango de ley que emana del Poder
Ejecutivo en virtud de delegación expresa efectuada por el Poder Legislativo. Su apro
bación corre por cuenta del Consejo de Ministros y debe ser refrendado por el propio
Presidente de dicho ente.
Tiene la misma jerarquía que una ley ordinaria.
- Resoluciones Legislativas.- Chirinos Soto las define como "ley del caso particular”; por
tanto, representan una excepción a las características de la generalidad y abstractividad
de la ley. El Congreso Constituyente las utiliza para asignar atribuciones, deberes o san
ciones a determinadas personas; o para otorgar validez a hechos concretos y específicos.
Tienen por objeto aprobartratados internacionales, prorrogar el estado de sitio, autorizar
al Presidente de la República ausentarse del país y permitir el ingreso de tropas extranje
ras en el territorio de la República sin afectar la soberanía nacional, entre otros.
Tienen rango de ley porque tácitamente la Constitución las equipara con la Ley (art. 102 inc. 1 :
Constitución).
El Reglamento del Congreso establece explícitamente que su jerarquía es homologa con la ley
(art. 4).
- Decretos de Urgencia.- Normasjurídicas de carácterextraordinario destinadas a regular
circunstancias graves y súbitas de carácter económico y financiero, así como también la
efectivización de una actividad legislativa durante el periodo que transcurre entre la diso-
lución del Congresoy la instauración de otro surgido de elecciones parlamentarias.
Respecto de los requisitos formales y materiales para la expedición de los decretos
de urgencia el Tribunal Constitucional (STC Exp. N.°00004-20ii-PI/TC) refiere: i) Ex
ante, requisito constituido por el refrendo del Presidente del Consejo de Ministros
(art. 123 inc. 3 Constitución), i i) Ex post, lo constituye laobligación del Ejecutivo de dar
cuenta al Congreso de la República (art. 118 inc. 19 Constitución concordado con art.
91 Reglamento del Congreso).
Asimismo, el Tribunal Constitucional ha establecido los criterios para corroborar la
validez de las circunstancias fácticas que sirvieron de justificación para la expedición
de los decretos de urgencia, estos son: a) Excepcionalidad: La norma debe estar orienta
da a revertir situaciones extraordinarias e imprevisibles, condiciones que deben ser evaluadas
en atención al caso concreto y cuya existencia, desde luego, no depende de la “voluntad”de la
norma misma, sino de datos tácticos previos a su promulgacióny objetivamente identifica bles,
b) Necesidad: Las circunstancias, además, deberán ser de naturaleza tal que el tiempo que
