demande la aplicación del procedimiento parlamentario para la expedición de leyes (iniciativa,
debate, aprobación y sanción), no pudiera impedirla prevención de dañoso, en su caso, que los
mismos devengan en irreparables, c) Tmnsitoriedad: Las medidas extraordinarias aplicadas
