-Los decretos de urgencia no pueden contener normas sobre materia tributaria (art. 74 Constitución).
- Ordenanzas Regionales.- Los Gobiernos Regionales, a través del Consejo Regional
pueden emitirordenanzas regionalesy acuerdos del Consejo Regional, porotro lado,
a través de la Presidencia Regional puede em itir decretos regionales y resoluciones
regionales. Siendo la norma jurídica con mayor jerarquía las ordenanzas regionales.
La ordenanza regional es una norma con rango de ley emitida por el Consejo Regio
nal, a través de éstas se regulan los asuntos de carácter regional, la organización y
la administración del propio Gobierno Regional; así como la reglamentación de las
materias de su competencia.
"Dado que las ordenanzas regionales son normas con rango de ley (artículo 200° 4 Constitu
ción); no se encuentran jerárquicamente subordinadas a las leyes nacionales del Estado, por
lo que para explicar su relación con éstas no hay que acudir al principio de jerarquía, sino al
principio de competencia, pues tienen un ámbito normativo competencia! distinto." STC Exp, Ñ°
0020-2005-AI/TCy Exp. N° 0021-2005-AI/TC (acumulados) FJ. 61. Sentencia de Observancia Obligatoria.
- Ordenanzas Municipales.- Son normas generales que regulan la organización, ad
ministración o prestación de los servicios públicos locales, el cumplim iento de las
funciones generales o específicas de las Municipalidades o establecen las limitacio-
nesy modalidades a la propiedad privada; así como la determinación de los tributos
municipales. Estas solo se encuentran supraordinadas por la Constitución, la Ley de
Bases de la Descentralización y la Ley Orgánica de Municipalidades.
Las Ordenanzas Municipales, son las normas de mayor jerarquía municipal, y gozan
del principio de la reserva de Ley-, por lo que sólo y únicamente pueden ser modificadas
o derogadas por otra ordenanza municipal o ser declaradas inconstitucionales, en
consecuencia, también pueden ser objeto de derogación erga omnes por Sentencia
del Tribunal Constitucional.
- Sentencias del Tribunal Constitucional que declaran la inconstitucionalidad de
una ley o norma con dicho rango.- Son las decisiones jurisdiccionales que adopta
el Tribunal Constitucional en el marco de un proceso de inconstitucionalidad, y en
las cuales se dispone la expulsión de una ley o norma con fuerza de ley, en razón
de haber sido declarada vigente con infracción al procedimiento establecido en la
