3. TERCERA CATEGORÍA: Decretos y normas reglamentarias
- Decreto Supremo.- Es una norma jurídica de carácter general que proviene de la más
alta instancia del Poder Ejecutivo, el Presidente de la República. Es aprobado por el
Poder Ejecutivo, lleva la rúbrica o firm a del Presidente de la Repúblicay debe ser re
frendado por uno o más ministros. Tiene por finalidad regular la actividad de un de
terminado sector o varios sectores a nivel nacional (multisectorial). Estas normas por
su naturaleza deben limitarse a interpretary aplicar la legislación sin transgredirla,
modificarla o desnaturalizarla. Se clasifican en.-
a) Reglamentos administrativos. - Aquellos preceptos generales que tienen obli
gatoriedad interna y tienen conexión explícita con una ley orgánica u ordinaria
de creación o implementación de una institución estatal.
b) Reglamentos ejecutivos. - Aquellos preceptos generales que tienen por finali
dad principal la especificación de detalles y aspecto accesorios de una ley. Son
los más importantes dentro del género.
c) Reglamentos autónomos. - Aquellos preceptos generales que no se fundan di
rectamente en una ley, sin embargo, contribuyen al cumplim iento de las tareas,
atribuciones o funciones encomendadas por ella.
