3. N O R IA S iNFRALEGALES
Son aquellas de rango inferior a la ley en sentido estricto. Su manifestación más clara es el
reglamento administrativo que puede ser definido como una norma escrita procedente del
poder ejecutivo y por lo mismo subordinada a la ley.
El control abstracto de constitucionalidady legalidad de las normas de jerarquía infralegal se
realiza a través del proceso de acción popular (Constitución. Art. 200.5). Dicho proceso es de
competencia del Poder Judicial (CPconst. Art. 85). En este contexto, el Tribunal Constitucional
está prohibido del control abstracto de constitucionalidad de las normas de jerarquía infrale
gal debido a que el proceso constitucional establecido para tal efecto está reservado al Poder
Judicial.
Sin embargo:
¿Puede el Tribunal Constitucional pronunciarse sobre la constitucionalidad de una norma
de jerarquía infralegal?
El Tribunal Constitucional ha respondido afirmativamente y distingue los supuestos siguientes:
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 19 of 1506 --

Tema 1: Sistema Norm ativo Nacional
i) El primero es el de la norma ¡nfralegal conexa o consecuente (CPcons.Art.78) con la norma
con rango de ley declarada inconstitucional. En este supuesto la respuesta es la siguiente:
"el Tribunal Constitucional sí puede efectuar el control abstracto de constitucionalidad de una nor
ma de jerarquía ¡nfralegal y, así, pronunciarse sobre su validez constitucional, cuando ella es tam
bién inconstitucional ‘por conexión o consecuencia con la norma de jerarquía legal que el Tribunal
Constitucional ha declarado inconstitucional”. (STC. Exp. N° 045-2004-PI/TC. Fj.74).
ii) El segundo es la norma que no siendo conexa ni consecuente es una norma que reitera
o reproduce el contenido de la ley declarada inconstitucional. Así, “[ejxiste empero un su
puesto distinto consistente de relación entre normas en las que una redunda, reitera o reproduce la
enunciada por otra que es la declarada inconstitucional. En tal supuesto, resulta lógico que aquella,
al reproducir el contenido inconstitucional de la norma impugnada, es también inconstitucional y,
por tanto, debe declararse su inconstitucionalidad. En sentido exacto, (...), se trata de dos "disposi
ciones”que expresan la misma norma. Desde esta perspectiva, en cuanto la declaración de inconsti
tucionalidad es respecto de la norma, todas las disposiciones que la enuncien o reproduzcan deben
ser también declaradas inconstitucionales”. (STC. Exp. N° 045-2004-PI/TC. Fj.78).
4. EL VALOR Y ALCANCES DE LOS PRECEDENTES JUDICIALES Y CONSTITUCIONALES
VINCULANTES
4.1. Precedente Judicial Vinculante
El precedente es una técnica de argumentación que consiste en extraer un fundamento juríd i
co de un caso decidido a fin de aplicarlo a un caso idéntico o similarque surja posteriormente.
Ello implica que un órgano jurisdiccional tome una decisión en determinado caso (supuesto
de hecho), el cual vincula al órgano que decidió tomar dicha postura así como aquellos de je
rarquía inferior, de modo tal que ante casos o situaciones fácticas futuras, similares o iguales,
debe seguirse la misma decisión a partir de los hechos (ratio decidendi) de dicho caso. Nuestro
ordenamiento jurídico establece los casos en que los tribunales encargados de administrar
justicia crean precedentes o doctrina jurisprudencial vinculatoria, como se verá a continua
ción.
El Nuevo Código Procesal Constitucional, art. VI, dispone.- Tas sentencias del Tribunal Cons
titucional que adquieren la autoridad de cosa juzgada constituyen precedente vinculante
cuando así lo exprese la sentencia, precisando el extremo de su efecto normativo, formulando
la regla jurídica en la que consiste el precedente. Cuando el Tribunal Constitucional resuel
va apartándose del precedente, debe expresar los fundamentos de hecho y de derecho que
sustentan la sentencia y las razones por las cuales se aparta del precedente.”. Conforme a este
texto, las sentencias del Tribunal Constitucional pueden o no ser vinculantes para el propio
Tribunal y demás órganos del Estado. Constituirán precedente vinculante, cuando así lo ex
prese el propio texto de la sentencia, caso contrario, cuando no contengan esta declaración,
no tendrán la calidad de precedente normativo obligatorio.
Sobre el tema el profesor López Viera5 señala que el "artículo 22o de la Ley Orgánica del Poder
Judicial (LOPJ) señala que todas las Salas Especializadas de la Corte Suprema pueden dictar
