"principios jurisprudenciales de obligatorio cumplimiento”6 Por otro lado, tenemos al artículo 301-A
del Código de Procedimientos Penales, incorporado mediante el artículo 2o del Decreto Legis
lativo N °959. El incisoi) de dicho artículo establece que: "Las sentencias de laSala Plena de la Corte
