precedente vinculante cuando así lo expresen las mismas, precisando el extremo de su efecto normati
vo. Cuando la Sala Penal de la Corte Suprema resuelva apartándose del precedente, debe expresar los
fundamentos de hecho y de derecho que sustentan la sentencias y la razones por las cuales se aparta del
precedente En este caso, también asistimos a un precedente de “observancia relativa", pues
esto se deduce de una simple concordancia con el artículo 22o de la LOP], tal y como señala el
referido dispositivo.
Asimismo, el artículo 400o del Código Procesal Civil, establece que la decisión adoptada por
la mayoría absoluta de los votos de los vocales supremos reunidos en Sala Plena de la Corte
Suprema, “constituye doctrina jurisprudencial y vincula a los órganos jurisdiccionales del Estado, hasta
quesea modificada por otro pleno casatorio”. De la redacción de este artículo pareciera que en este
caso, estamos frente a una doctrina jurisprudencial con vinculancia “absoluta” pues a diferen
cia del apartado anterior en materia penal, este dispositivo no hace alusión a ninguna clase de
excepción para poderse apartar. Sin embargo, creemos que pese a que no se hace referencia
expresa a lo señalado en líneas anteriores, los jueces si se podrían apartar acudiendo a una in
terpretación sistemática del ordenamiento jurídico (LOP],CPCivily CProced. Penales), pues de
la interpretación concordante de las normas citadas-algo que por cierto es totalmente válido,
justificado y hasta determinado punto obligatorio- se deriva que también estamos frente a
una vinculancia “relativay no absoluta” como pareciera entenderse.67
A su turno, el artículo 34° de la Ley N° 27584-Ley que regula el Proceso Contencioso Adm i
nistrativo-, dispone que las decisiones de la Sala Constitucional y Social de la Corte Suprema
constituyen doctrina jurisprudencial en materia contencioso administrativa, y que, por tanto,
los jueces y tribunales no podrán apartarse de ella, a menos “quese presenten circunstancias par
ticulares en el caso que conocen y que motiven debidamente las razones por las cuales se apartan de la
doctrina jurisprudencial”. Es decir, estamos frente a un apartamiento para “casos distintos”, en
consecuencia, el apartamiento aquí radica no en cualquier situación, sino sólo en aquellas
donde el caso que está resolviendo el magistrado no sea idéntico en cuestiones fácticas, al
caso que dio origen al precedente, para ello el requisito es motivar el apartamiento basándose
en la situación específica que establece el precepto.
Por su parte, en el procedimiento administrativo en algunos de los distintos Tribunales se ha
instaurado la potestad de que puedan em itir precedentes de observancia obligatoria, tal es el
caso del Instituto Nacional de Defensa de la Competencia y Protección de la Propiedad Inte
lectual (INDECOPI), que bajo la facultad prevista en el artículo 43° del Decreto Legislativo N°
6 A pesar de que este artículo señala que estos criterios son de “observancia obligatoria”, en un párrafo posterior
