Tema 1: Sistema Norm ativo Nacional
807, sus Comisiones, Oficinas y Tribunales al resolver casos particulares en donde interpreten
la legislación “constituirán precedente de observancia obligatoria, mientras dicha interpretación no sea
modificada por resolución debidamente motivada de la propia Comisión u Oficina según fuera el caso, o
