4.2. Precedente C onstitucional Vinculante
El Tribunal Constitucional ha señalado en la STC Exp. 0024-2003-AI/TC, que "el precedente
constitucional vinculante es aquella regla jurídica expuesta en un caso particular y concreto
que el Tribunal Constitucional decide establecer como regla general; y, que por ende, devie
ne en parámetro normativo para la resolución de futuros procesos de naturaleza homologa”.
Seguidamente añade que: “El precedente constitucional tiene por su condición de tal, efectos
similares a una ley. Es decir, la regla general externalizada como precedente a partir de un
caso concreto se convierte en una regla preceptiva común que alcanza a todos los justiciables
y que es oponible frente a los poderes públicos”.
La competencia del Tribunal Constitucional para determinar un precedente vinculante se en
cuentra sustentada en el Artículo VI del Título Preliminar del Nuevo Código Procesal Constitu
cional, el cual preceptúa que “Las sentencias del Tribunal Constitucional que adquieren la au
toridad de cosa juzgada constituyen precedente vinculante cuando así lo exprese la sentencia,
precisando el extremo de su efecto normativo, formulando la regla jurídica en la que consiste
el precedente. Cuando el Tribunal Constitucional resuelva apartándose del precedente, debe
expresar los fundamentos de hecho y de derecho que sustentan la sentenciay las razones por
las cuales se aparta del precedente."
4.2.1. Naturaleza
Tiene una connotación binaria. Por un lado, aparece como una herramienta técnica que facilita
la ordenación y coherencia de la jurisprudencia; y, por otro, expone el poder normativo del
Tribunal Constitucional dentro del marco de la Constitución, el Nuevo Código Procesal Cons
titucional y la Ley Orgánica del Tribunal Constitucional.
Presupuestos básicos para el establecimiento de un precedente vinculante-.
El TC señala los siguientes (STC Exp. 0024-2003-AI/TC):
a) Cuando se evidencia que los operadores jurisdiccionales o administrativos vienen resol
viendo con distintas concepciones o interpretaciones sobre una determinada figura jurí
dica o frente a una modalidad o tipo de casos; es decir, cuando se acredita la existencia de
precedentes conflictivos o contradictorios.
b) Cuando se evidencia que los operadores jurisdiccionales o administrativos vienen resolvien
do en base a una interpretación errónea de una norma del bloque de constitucionalidad; lo
cual, a su vez, genera una indebida aplicación de la misma.
c) Cuando se evidencia la existencia de un vacío normativo.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 22 of 1506 --

UBILEX
d) Cuando se evidencia la existencia de una norma carente de interpretación jurisdiccional
en sentido lato aplicable a un caso concreto, y en donde caben varias posibilidades inter
pretativas.
e) Cuando se evidencia la necesidad de cambiar de precedente vinculante.
En este supuesto, de conformidad con lo establecido en el Art. VI del T.R del Nuevo Código
Procesal Constitucional, el TC debe obligatoriamente expresar los fundamentos de hecho y
de derecho que sustentan la sentenciay las razones por las cuales se aparta del precedente.
Apartamiento y sustitución de un precedente vinculante:
Está sujeta a los tres elementos siguientes:
a) Expresión de los fundamentos de hecho y derecho que sustentan dicha decisión.
b) Expresión de la razón declarativa-teológica, razón suficiente e invocación preceptiva en
que se sustenta dicha decisión.
c) Determinación de sus efectos en el tiempo.
Distinción entre precedente judicial y precedente constitucional vinculante:
a) El efecto vinculante del precedente judicial se establece básicamente respecto de los
jueces. Cualquiera que invoque un precedente, para que éste logre sus efectos, deberá
acudir ante un juez, quien deberá aplicarlo en un caso concreto (STC Exp. 3741-2004-AA/
TC.Fj.48).
De la normativa nacional sobre la regulación del precedente judicial y comparándolo con
el precedente constitucional vinculante su diferencia radica en su vinculancia “obligato-
ria-absoluta” del segundo y no “persuasiva u obligatoria-relativa” como la del primero,
que deja en casi todos los casos la posibilidad de que los jueces puedan apartarse del
mismo sustentando las razones de hecho y derecho de tal situación. Caso distinto ocurri
ría, con el precedente administrativo, que pareciera tener la misma fuerza vinculante que
el precedente constitucional, cuando señala que sólo el órgano que emitió el precedente
- Comisión u Oficina o del Tribunal- puede modificarlo, tal y como sucede con el precedente
constitucional vinculante según el artículo VI del Título Preliminar del Nuevo Código Pro
cesal Constitucional, que señala que sólo el Tribunal Constitucional podría apartarse de
su precedente.
b) El precedente constitucional emitido por un Tribunal Constitucional tiene, prim a facie, los
mismos efectos de una ley. Es decir, que la regla que el Tribunal externaliza como prece
dente a partir de un caso concreto, es una regla para todos y frente a todos los poderes
públicos; cualquierciudadano puede invocarla ante cualquier autoridad o funcionario sin
tenerque recurrir previamente ante los tribunales, puesto que las sentencias del Tribunal
Constitucional, en cualquier proceso, tienen efectos vinculantes frente a todos los pode
res públicos y también frente a los particulares. (STC Exp. 3741-2004-AA/TC. Fj.49). El
hecho de que sólo lo pueda em itir el Tribunal Constitucional, hace que este precedente
vinculante sólo pueda versar sobre “materia estrictamente constitucional”.
2 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 23 of 1506 --

Tema 1: Sistema Norm ativo Nacional
4.3. Jurisprudencia Constitucional Vinculante
El Tribunal Constitucional en laSTC N °0024-2003 AI/TC, Caso: Municipalidad de Lurín, señaló
con respecto a la jurisprudencia constitucional que.- “La noción jurisprudencia constitucional se
refere al conjunto de decisiones o fallos constitucionales emanados del Tribunal Constitucional, expe
didos a efectos de defender la superlegalidad, jerarquía, contenidoy cabal cumplimiento de las normas
pertenecientes al bloque de constitucionalidad".
Agrega, refiriéndose a su vinculación que; “Las sentencias del Tribunal Constitucional, dado que
constituyen la interpretación de la Constitución del máximo tribunal jurisdiccional del país, se estatu
yen como fuente de derecho y vinculan a todos los poderes del Estado (...) La jurisprudencia constituye,
por tanto, la doctrina que desarrolla el Tribunal en los distintos ámbitos del derecho, a consecuencia de
su labor frente a cada caso que va resolviendo”. STC Exp. 3741-2004-AA/TC (Fj.42)
4.3.1. Distinción entre el precedente y la jurisprudencia constitucional vinculante
Si bien tanto la jurisprudencia como el precedente constitucional tienen en común la carac
terística de su efecto vinculante, en el sentido de que ninguna autoridad, funcionario o parti
cular puede resistirse a su cumplim iento obligatorio, también tienen diferencias, entre ellas
tenemos:
a) El Tribunal, a través del precedente constitucional, ejerce un poder normativo general,
extrayendo una norma a partir de un caso concreto.
b) El precedente constitucional vinculante solo puede emitirse a través de una sentencia del
Tribunal; por su parte la jurisprudencia se puede em itir en cualquier tipo de resolución
jurisdiccional del mismo.
c) El precedente solo se puede em itir en una sentencia que tiene la calidad de cosa juzgada;
en cambio lajurisprudenciase puede em itiren cualquiertipode resolución aunque no se
haya resuelto sobre el fondo.
d) El precedente tiene que estar expresamente señalado por el Tribunal Constitucional en
su sentencia, es decir, él determina en qué parte de su sentencia o en que fundamentos
se encuentra contenido su precedente; por su parte en el caso de la jurisprudencia no es
necesario que el Tribunal señale donde se encuentra la jurisprudencia.
e) Según se desprende literalmente del artículo VI del T.R del Nuevo Código Procesal Cons
titucional, sólo el Tribunal podría apartarse de su precedente, en vista de ello está posibi
lidad estaría vetada para los jueces; en el caso de la jurisprudencia no sólo el Tribunal po
dría apartarse sino también lo podrían hacer los jueces, claro en uno uotro caso, siempre
sustentando las razones de hecho y derecho de tal apartamiento.
f) El precedente emanado del Tribunal es una regla jurídica que nace a partir de un caso en
concreto y que sirve para resolver casos futuros de naturaleza homologa; por su parte la
jurisprudencia son los criterios reiterativos del Tribunal en casos similares.
g) El precedente en principio sólo podría estar contenido en la ratio decidendi de la senten
cia; en cambio la jurisprudencia puede estar contenida tanto en ¡a. ratio decidendi como en
la obiter dicta, determinándose que si estamos en el primer caso tendría una vinculancia
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 24 of 1506 --

UBILEX
obligatoria mayor y si estamos frente al segundo solo una vinculancia persuasiva o me
nor.
h) El precedente constitucional vinculante tiene “efectos similares a una ley”; por el contra
rio, la jurisprudencia vinculante carece de estos efectos.
i) El único que puede cambiar o dejar sin efecto el precedente constitucional vinculante es
el órgano que lo emitió, es decir, el Tribunal Constitucional; por su parte, quien podría
apartarse del precedente no solo sería el Tribunal Constitucional, sino también los jueces,
siem pre y cuando su caso no sea idéntico u homólogo al que dio origen al precedente.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 25 of 1506 --

SISTEMA NORMATI
1. PROBLEMAS DE INDETERMINACIÓN DEL DERECHO
La indeterminación del Derecho, que podríamos definir como la falta de calificación deóntica
para una determinada conducta o la ausencia de respuesta jurídica correcta, es un fenómeno
complejo que suele inquietar mucho a los juristas, es objeto de inquietud, por una parte, por
que se percibe como una muestra de la imperfección del Derecho en tanto instrumento para
guiar la conducta.
La indeterminación del Derecho no solamente se produce como consecuencia del contenido
abierto de las disposiciones jurídicas, sino que es posible hablar de otras causas que afectan a
la estructura de los sistemas jurídicos. En este sentido nos encontramos con la indetermina
ción lingüística, por un lado, y con la indeterminación que producen los defectos del sistema,
por otro.
2. PROBLEMAS CON LA VALIDEZ Y VIGENCIA
El Tribunal Constitucional (STC Exp. N° 00i7-2005-PI/TC) ha sostenido que el concepto de
validez alude a la relación de compatibilidad entre dos normas de distinto rango. Así, una
norma es válida siempre que haya sido creada conforme al iter procedí mental que regula el
proceso de su producción jurídica, es decir, observando las pautas previstas de competencia
y procedimiento que dicho ordenamiento establece (validez formal), y siempre que no sea
incompatible con las materias, principios y valores expresados en normas jerárquicamente
superiores (validez material).
El ordenamiento jurídico está integrado solamente por normas jurídicas válidas; las normas
inválidas no están dentro del derecho. Para establecer si una norma pertenece o no al ordena
miento jurídico hay que pasar de grado en grado, de poder en poder, hasta llegara la forma fun
damental que es la que, le da validez y unidad al complejo y enredado ordenamiento jurídico.
Por este motivo, la norma fundamental se coloca al estilo Kelseniano, en el vértice del sistema,
porque con ella se relacionan todas las otras normas. Norma suprema que no es otra más que
nuestra Constitución Política del Perú.
La vigencia de una norma jurídica depende, prima facie, de que haya sido aprobada y pro
mulgada por los órganos competentes, y además de que haya sido publicada conforme lo
establece el último extremo del a rtícu lo s!0de la Constitución. Cumplido este procedimien
to, se podrá considerar que la norma es eficaz. De este modo, el efecto práctico de la vigencia
de una norma es su eficacia.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 25

-- 26 of 1506 --

Para determinar que una norma está vigente no es necesario analizarla desde un punto de
vista de su contenido y de su compatibilidad con las normas de rango superior. La vigencia
ocurre entre el momento de entrada en vigory el momento de terminación de la existencia de
la disposición jurídica.
3. EFECTOS DE LAS LEYES EN EL TIEMPO
3 .1. Aplicación de la norma en el tiempo
Marcial Rubio Correa distingue la siguiente terminología de acuerdo a cómo debe procederse
en la aplicación de la norma en el tiempo:
1. - Aplicación inmediata de la norma. Es aquella que se hace a hechos, situaciones o relacio
nes jurídica que ocurren durante la entrada en vigencia de la norma hasta el momento de
quiebre, modificación o derogatoria.
Esta aplicación inmediata o necesaria de la norma se debe a lo que nosotros llamamos y
vemos con frecuencia en los dictados de sentencia por los jueces o sanciones que corres
ponden a consecuencias jurídicas que tienen lugar o son consumados durante el periodo,
desde que entra en vigencia la norma.
Entonces podemos decir que, José Reyes ha consumado un hecho con la vigencia de un
ordenamiento jurídico, pues se le aplicara la norma que estuvo vigente en el momento de
comisión del hecho.
2. - Aplicación ultractiva de la norma. Es aquella que se hace a los hechos, situaciones y rela
ciones que ocurren luego que ha sido derogada o modificada se manera expresa o tácita,
es decir, luego que termine su aplicación inmediata.
En el ordenamiento jurídico, nuestras normas se van modificando o derogando de mane
ra expresa (por pronunciamiento de la misma norma) y tácita (por incompatibilidad de
la norma), pero muchas veces en ese proceso hay situaciones o relaciones que han sido
constituidas antes de que ésta haya sido sometida a este proceso de modificación o dero
gación y que posteriormente después de la derogatoria se produzcan las consecuencias,
pero que las consecuencias primarias ya habían tenido en su totalidad lugar en la legisla
ción anterior.
Entonces, si José Reyes deja un testamento con el ordenamiento jurídico de 1936, pero el
testador fallece después que entra en vigencia el Código Civil de 1984 derogando al ante
rior. Si bien usamos las reglas de la lógicay los principios que este artículo establece, nos
encontramos frente a un análisis ultractivo de la norma.
3. - Aplicación retroactiva de la norma. Es aquella que se hace para regir hechos, situaciones
o relaciones jurídicas que tuvieron lugar antes del momento en que entra en vigencia la
norma, es decir, antes de su aplicación inmediata.
Esta aplicación retroactiva conoce dos modalidades.-
i) Aplicación retroactiva restitutiva-. Es aquel caso en que la aplicación retroactiva es ab
soluta de acuerdo con las consecuencias jurídicas que derivan de sus supuestos. Es
decir, modifica en su totalidad los hechos, relaciones o situaciones jurídicas.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 27 of 1506 --

Tema 2: Problemas en el Sistema Norm ativo
Nos referimos en su totalidad y su absolutismo ya que puede modificar las senten
cias judiciales que hayan pasado a cosa juzgada. Este modelo de aplicación retroac
tivo de la norma es prácticamente inexistente en nuestro derecho actual.
ii) Aplicación retroactiva ordinaria: es aquel caso en el que la aplicación de la norma se
hace de manera relativa. Esto quiere decir que modifica de manera parcial los he
chos, relaciones o situaciones lo que significa que puede modificar actuaciones
anteriores al momento del punto de quiebre de la norma, pero salvo las sentencias
judiciales que hayan pasado en calidad de cosa juzgada.
4„- Aplicación diferida de la norma. Es aquella en que la norma, de manera expresa, ha se
ñalado que deberá aplicarse en un momento futuro.
Entonces, aquí nos encontramos ante un modelo de norma especial, porque esta misma,
expresamente, señala cuando debe aplicarse. Esto no significa que cuando no señala su
aplicabilidad está derogada temporalmente, sino que esta norma establece una vacatio
legis que es característica de esta norma.
3.2. La teoría general del derecho frente a la aplicación de la norma en el tiempo
A) Teoría de derechos adquiridos
Los antecedentes de los derechos adquiridos se encuentran en el Derecho Romano, la
primera afirmación de los derechos adquiridos y las simples expectativas se atribuyen a
B iondeaueni926.
Los derechos adquiridos son los que han entrado en nuestro patrimonio, hacen parte de
él y nadie no los pude arrebatar, eso es hablando en un sentido patrimonial.
Analizando la teoría de los derechos adquiridos en función de los esquemas temporales,
podremos fácilmente comprobar que lo que en verdad propugna es que la norma bajo la
cual nació el derecho, continúe rigiéndolo mientras tal derecho surta efectos, aunque en
el trayecto exista un momento de quiebre en el que dicha norma sea derogada o sustitui
da. En otras palabras, lo que formalmente plantea la teoría de los derechos adquiridos
es la ultractividad de la normatividad bajo cuya aplicación inmediata se originó el de
recho adquirido.
Los espectadores de la teoría, sin embargo, han planteado los casos de manera distinta sos
tienen que el derecho adquirido no puede ser modificado por normas posteriores porque,
en ese caso, se estaría haciendo aplicación retroactiva de ellos.
En otras palabras, la teoría de los derechos adquiridos no hace sino crear una ficción, lla
mando aplicación retroactiva a lo que en verdad es aplicación inmediata en afán de dar
estabilidad normativa al llamado derecho adquirido.
En esta teoría encontramos a cada paso de nuestro estudio las expectativas y facultades
que se diferencia en los derechos adquiridos según la misma teoría.
Como ya hemos visto la teoría de los derechos adquiridos se puede definir como expecta
tiva, según MARCIAL RUBIO CORREA, a la aspiración de la persona de obtener una im pu
tación jurídica pero en potencia, pues no se ha verificado el hecho o acto que permita ser
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 28 of 1506 --

UBILEX
la actual. Por facultad debe entenderse la atribución jurídicamente otorgada a una perso
na para actuar válidamente de acuerdo al derecho o en cierta rama de la actividad.
Las insuficiencias de la teoría de los derechos adquiridos, han llevado a otros autores a
plantear diversas variantes:
Bonnecase expone que una ley es retroactiva cuando modifica o extingue una situación
jurídica concreta; no lo es, en cambio, cuando simplemente lim ita o extingue una situa
ción abstracta, creada por la ley precedente.
La situación jurídica será abstracta cuando se refiere a la manera de ser eventual o teórica
en relación con una ley determinada. Por ejemplo-, nuestra legislación actual fija la mayoría
de edad en 18 años. Si se emitiera una nueva ley que la fijara en 21, los menores de 18 años
se encontrarían en una situación jurídica abstracta, es decir teórica o eventual respecto de
dicha ley, y por lo tanto no existiría retroactividad cuando se les aplicara la nueva ley. Aho
ra, los mayores de 18 pero menores de 21 años ya se encuentran en una situación concreta
respecto de la ley actual, la cual les ha conferido las ventajas y obligaciones inherentes a
la mayoría de edad y si la nueva ley les restringiera o suprimiera la calidad de mayores,
estaríamos en presencia de una aplicación retroactiva de la ley, pues se modificaría una
situación jurídica concreta.
La situación jurídica abstracta es el marco (por ejemplo el parentesco de cierto grado en
la sucesión hereditaria) dentro del cual puede producirse la situación jurídica concreta
(calidad de heredero) en virtud de un hecho (muerte del causante).
Para determinar si una persona se encuentra en situación jurídica abstracta o concreta
respecto de cierta ley, habrá que establecersi se ha producido el supuesto que condiciona
el nacimiento de la consecuencia.
Josserand defiende la fórmula de los derechos adquiridos pero admite que no es posible
formar una lista invariable de los derechos adquiridos o de las simples expectativas, sino
que trata también de una cuestión de tacto, de sentimiento, de oportunidad.
En el Código Civil derogado de 1936 se adoptó en forma expresa la doctrina de los de
rechos adquiridos como medio de solución de conflictos surgidos a consecuencia de la
aplicación de las leyes en el tiempo.
B) Teoría de los hechos cumplidos.
Esta teoría significa que la nueva ley alcanza a los hechos futuros, pues los ya verificados
(cumplidos) se rigen con la ley antigua entonces lo que hay que investigar, no es si un
derecho se adquirió bajo el régimen de ley antigua, sino, si un hecho jurídico se cumplió
totalmente estando vigente la norma derogada.
Según Mario Alzamora Valdez expresa que la teoría del hecho cumplido, afirma que los
hechos cumplidos durante la vigencia de la antigua ley se rige por ésta; los cumplidos
después de su promulgación por la nueva.
En ese sentido, el Tribunal Constitucional ha pronunciado en reiterada jurisprudencia
que "(■■■) nuestro ordenamiento adopta la teoría de los hechos cumplidos (excepto en materia penal
cuando favorece al reo), de modo que la norma se aplica a las consecuenciasy situaciones jurídicas
