Tema 2: Problemas en el Sistema Norm ativo
existentes” (STC 0606-2004-AA/TC» F) 2). Por tanto, para aplicar una norma en el tiempo
debe considerarse lateoría de los hechos cumplidos y, consecuentemente, el principio de
aplicación inmediata de las normas.
Se colige de ello que toda norm a jurídica desde su entrada en vigencia es de aplicación a las
situaciones jurídicas existentes, y que la teoría de los derechos adquiridos tiene una aplicación
excepcionaly restringida en nuestro ordenam iento jurídico, pues únicam ente se u tiliz a para los
casos que de m anera expresa señala la Constitución, tal como ya lo ha establecido el Tri bu-
nal Constitucional cuando determinó que "(...) la aplicación ultractlva o retroactiva de una
norma sólo es posible si el ordenamiento lo reconoce expresamente-a un grupo determinado de
personas-que mantendrán los derechos nacidos al amparo de la ley anterior porque así lo dispuso
el Constituyente-permitiendo que la norma bajo la cual nació el derecho surta efectos, aunque en
el trayecto la norma sea derogada o sustituida-■ no significando, en modo alguno, que se desconozca
que por mandato constitucional las leyes son obligatorias desde el día siguiente de su publicación en
el Diario oficial (FJ 69-74) STC Exp. N° 00008-2008-PI/TC.
4. SILENCIO E INSUFICIENCIA EN LA LABOR LEGISLATIVA
4.1. Laguna de la ley
Es la ausencia de la norma legal en el ordenamiento jurídico que permita resolver un conflicto
o una incertidumbre con relevancia jurídica, precisamente, porque la ley no ha sido creada,
porque no existe ley aplicable al caso concreto que se debate o, porque existiendo ley por su
estructura y finalidad no es aplicable al caso concreto del debate por lo tanto resulta con un
concepto restringido o tal vez porque la ley por el transcurso del tiempo ha envejecido, es decir
no se ajusta a la realidad de la sociedad vigente del momento que se juzga la vulneración del
acto humano social que puede o no estar codificado, es decir legislado.
Las lagunas de la ley no deben confundirse con las lagunas del derecho, porque las lagunas
de la ley son los supuestos no regulados por la ley, pero que pueden ser regulados por otras
fuentes del derecho como la jurisprudencia o la doctrina, mientras que los vacíos del derecho
son los supuestos no regulados por la ley y por otras fuentes del derecho.
Ejem plo: es una laguna de la ley en el derecho positivo peruano la escisión de empresas indi
viduales de responsabilidad limitada.
Las lagunas, existen y existirán por siempre pero suscitándose a nivel legal. Es decir, la ley al no
poder abarcar todos los supuestos de la realidad cae en un vacío para regular determinados casos
pero el Ordenamiento jurídico como un todo abarca leyes, normas, principios, costumbres, etc.
no da cabida a fisuras para lo cual utiliza procedimientos los cuales deben eliminar sus vacíos.
Clases:
- Laguna normativa.- Se presenta cuando un caso no está correlacionado por solución
maximal alguna de un determinado sistema.
Soluciones maximales: i) Prohibido; ii) Facultado; iii) Obligado.
- Laguna de conocimiento.- Se presenta cuando existen en el sistema una norma que solu
cione el caso genérico pero por falta de pruebas, es decir, por ausencia de información se
desconoce si un caso individual se subsume o no en uno genérico.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN I
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 30 of 1506 --

UBILEX
Ejemplo: A Juan se le acusa de parricidio, sin embargo no se puede determinar si efectiva
mente Juan es parricida dado que falta la prueba ADN.
Por tanto, no se puede determinar la subsunción de su caso en parricidio.
- Laguna de reconocimiento.- Se presenta por la vaguedad del supuesto de hecho de la
norma que regula el caso; es decir, existe una solución para el caso genérico pero no se
puede determinar si el caso individual se subsume o no en el caso genérico, puesto que
los conceptos del caso genérico son indeterminados.
Ejem plo: El caso individual de Juan respecto a la transferencia de propiedad de su vehícu
lo consiste en que el precio pagado es menor al precio del mercado, y no se puede deter
minar por tanto si dicha venta se subsume en simulación de acto jurídico o no. (Por tanto,
no se puede determinarsi es una donación encubierta).
- Lagunas axiológicas.- Son aquellas en las que, no obstante existir una norma jurídica que
regule el caso, el juzgador considera que la decisión lógica, que se inclina por pensar que
el legislador, al hacer la previsión general, no ha comprendido ese caso concreto, puesto
que de haberlo tenido en cuenta hubiera adoptado una decisión diferente de la que re
sulta de la aplicación del derecho según la fórmula legal existente.
Ejemplo:
Ni = Obligatorio pagar impuesto predial.
Caso genérico que se subsume en Ni, es el de los ancianos indigentes propietarios de
inmuebles.
El juez inaplica Ni al caso individual de la anciana Julia Silva Mendez porque consi
dera que la anciana indigente es una propietaria relevante para ser excepcionada.
4.2. El Precedente Vinculante como forma de cubrir una Laguna Normativa
La función integradoradel Tribunal Constitucional1permite que, a través de la constitución de
un precedente vinculante, se resuelvan las situaciones derivadas de un vacío normativo. En ese
orden de ideas, dicha función verificable mediante la expedición de un precedente vinculante
se hace patente cuando, se acredita la ausencia absoluta de norma; cuando, a pesar de la exis
tencia de prescripción jurídica, se entiende que esta se ha circunscrito a señalar conceptos o
criterios no determinados en sus particularidades; cuando existe la regulación jurídica de una
materia, pero sin que la norma establezca una regla específica para solucionar un área con
conflicto coexistencial; cuando una norma deviniese en inaplicable por haber abarcado casos
o acarrear consecuencias que el legislador histórico no habría establecido de haber conocido
aquellas o sospechado estas; cuando dos normas sin referencia mutua entre sí -es decir en
situación de antinom ia indirecta- se contradicen en sus consecuencias jurídicas, haciéndose
mutuamente ineficaces; cuando, debido a nuevas circunstancias, surgiesen cuestiones que
el legislador histórico no tuvo oportunidad de prever en la norma, por lo que literalmente no
están comprendidas en ella, aunque por su finalidad pudieran estarlo de haberse conocido
