Tema 2: Problemas en el Sistema Norm ativo 1
anteladamente; y cuando los alcances de una norma perteneciente al bloque de constitucio-
nalidad no producen en la realidad efectos jurídicos por razones de ocio legislativo.
Partiendo de la existencia de una unidad normativa y la coherencia que la rige, se puede se
ñalar que ésta puede verse afectada por la aparición de ciertas antinomias, las mismas que
son generadas por la existencia de dos normas que simultáneamente plantean consecuencias
jurídicas distintas para un mismo hecho, suceso o acontecimiento, como puede ser en el caso
concreto las normas generales sobre descentralización y la ley materia de la inconstituciona-
Para el Tribunal Constitucional (Fj. 88. SCT Exp. N.° 002-2005-PI/TC-Lima), la antinom ia ca
racterizada por un "síndrome de incompatibilidad”, se acredita en los diversos presupuestos:
Que las normas afectadas porel “síndrome de incompatibilidad" pertenezcan a un mismo
orden jurídico; o que encontrándose adscritas a órdenes distintos, empero, estén sujetas
a relaciones de coordinación o subordinación (tal el caso de una norma nacional y un pre
cepto emanado del derecho internacional público).
Que las normas afectadas porel "síndrome de incompatibilidad” tengan el mismo ám bi
to de validez (temporal, espacial, personal o material). El ámbito temporal se refiere al
lapso dentro del cual se encuentran vigentes las normas. El ámbito espacial se refiere al
territorio dentro del cual rigen las normas (local, regional, nacional o supranacional). El
ámbito personal se refiere a los status, roles y situaciones jurídicas que las normas asig
nan a los individuos. Tales los casos de nacionales o extranjeros; ciudadanos y pobladores
del Estado; civiles y militares, funcionarios, servidores, usuarios, consumidores, vecinos;
etc. El ámbito material se refiere a la conducta descrita com oexigibleal destinatario de la
norma.
Que las normas afectadas por el “síndrome de incompatibilidad” pertenezcan, en princi
pio, a la misma categoría normativa; es decir, que tengan homologa equivalencia jerár
quica.
Clases de antinomia2:
a) Porel tipo de conflicto que generan: En esta hipótesis pueden ser observadas como:
a.7.) Conflictosbilaterales-unilaterales:
Son bilaterales cuando el cumplimiento de cualquiera de las normas en conflicto
