a.z.) Conflictos totales-parciales
Son totales cuando el cumplimiento de una de las normas supone la violación inte
gral y entera de la otra.
Son parciales cuando la aplicación de una de las normas implica la violación seg
mentada de la otra.
a. 3.) Conflictos necesariosy posibles
Son necesarios cuando el cumplimiento de una de las normas implica irreversible
mente la violación de la otra.
Son posibles cuando el cumplimiento de una implica solo la eventualidad de la vio
lación de la otra.
De acuerdo a esta clasificación se pueden plantear las siguientes combinaciones:
Conflictos bilaterales, necesarios y totales.
Conflictos bilaterales, necesariosy parciales.
Conflictos bilaterales, parcialesy necesarios respecto a una de las normas en conflic
to y posibles respecto a la otra.
Conflictos bilaterales, parcialesy solo posibles respecto a las dos normas en conflic
to.
Conflictos unilaterales, parcialesy posibles.
En cambio, no caben los conflictos bilaterales, totales y posibles; ni tampoco los con
flictos unilaterales, parciales y necesarios.
