En esta hipótesis pueden ser observadas como-,
b. i.) Las antinomias directas
Que aluden a dos normas que expresa, inequívocay claramente se contradicen.
b.2.) Las antinomias indirectas
Se produce ante la coexistencia de dos normas incompatibles, que tienen la mis
ma validez jerárquica en el tiempo y en el espacio, pero que inspiran consecuencias
jurídicas en fines o criterios ideológicos contrapuestos (interés público y seguridad
