5.2. Criterios de solución de antinomias
La diversidad de criterios para la solución de antinomias permite su solución sobre la base de
los siguientes principios (STC Exp. N° 047-2004-AI/TC):
a) Principio de plazo de validez (art. 103 Constitución, art. 1 Código Civil): Esta regla señala que la
norma tiene vigencia permanente hasta que otro precepto de su mismo o mayor nivel la
modifique o derogue, salvo que el propio texto hubiere establecido un plazo fijo de vali-
