dez. Excepcionalmente, puede presentarse el caso que una norma quede sin valor legal
alguno, como consecuencia de una sentencia que declara su inconstitucionalidad.
b) Principio de posterioridad (art. 103 Constitución, art. 1 T.P. Código Civil): Esta regla dispone que
una norma anterior en el tiempo queda derogada por la expedición de otra con fecha
posterior. Ello presume que cuando dos normas del mismo nivel tienen mandatos con
tradictorios o alternativos, primará la de ulterior vigencia en el tiempo.
c) Principio de especificidad (art. 139 ''me. 8 Constitución, art. 8 T.P. Código Civil): Esta regla dispone
que un precepto de contenido especial prima sobre el de mero criterio general. Ello im pli
ca que cuando dos normas de similar jerarquía establecen disposiciones contradictorias
o alternativas, pero una es aplicable a un aspecto más general de situación y la otra a un
aspecto restringido, prima esta en su campo específico.
En suma, se aplica la regla de lexposterior''!genera/is non derogatpriori especialis (la ley poste
rior general no deroga a la anterior especial).
d) Principio de favorabilidad (art. 103 Constitución): Es una regla solo aplicable a materias de
carácter penal,y supone aplicar la norma que más favorezca al reo.
e) Principio de envío: Esta regla es aplicable en los casos de ausencia de regulación de un he
cho, por parte de una norma que debió contemplarlo. Ante ello, se permite o faculta ac
cionar a otro precepto que sí lo prevé. Debe advertirse que este principio solo se cumple
cuando una normase remite expresamente a otra, para cubrir su falta de regulación. Es el
caso de las normas del Título Preliminar del Código Civil.
f) Principio de subsidiariedad: Esta es una regla por la cual un hecho se encuentra transitoria
o provisionalmente regulado por una norma, hasta que se dicte o entre en vigencia otra
que tendrá un plazo de vida indeterminado.
g) Principio de complementariedad: Esta regla es aplicable cuando un hecho se encuentra regi
do parcialmente por una norma que requiere completarse con otra, para cubrir o llenar
la regulación de manera integral. Es el caso de la relación existente entre una ley y su
reglamento.
h) Principio de suplementariedad: Esta regla es aplicable cuando un hecho se encuentra re
gulado por una norma base, que otra posteriormente am plíay consolida. En puridad, el
segundo precepto abarcará al primero sin suprimirlo. Tal el caso de lo establecido en el
artículo 25o de la Constitución que señala que la jornada ordinaria de trabajo lijada en
ocho horas diarias o de cuarentay ocho horas semanales, puede ser reducida por conve
nio colectivo o por ley.
i) Principio de ultractividad expresa: Esta regla es aplicable cuando el legislador determina de
manera expresa que recobra vigencia una norma que anteriormente hubiere quedado
sin efecto.
En este sentido, la parte in fine del artículo i° del Título Preliminar del Código Civil la ha
recogido con suma claridad.
