1. LOS JUICIOS DE SUBSUNCION
1.1. Teoría de la Subsunción Normativa
Llamado también silogismo jurídico, sosteniendo Iturralde1 que, éste se compone de dos pre
misas y una conclusión derivada de aquéllas. Se dice que la conclusión es válida si las pre
misas lo son, pero desde un punto de vista formal. No importa aquí la corrección o verdad
material de las premisas, sino solamente que la conclusión se derive de ellas.
La subsunción se desarrolla por vía de un raciocinio silogístico, en el cual la premisa m a yo r-la
n o rm a - incide sobre la premisa m e n o r- los hechos-, produciendo un resultado, fruto de la
aplicación de la norma al caso concreto.
Ejem plo:
1. El que mata a otro será reprimido con pena privativa de libertad no menor de seis ni ma
yor de veinte años (Art. 106 C.R).
2. Es el caso que Juan mata a Pedro. (Caso especial)
3. En consecuencia Juan es responsable de la muerte de Pedro por tanto será condenado.
Estructura de Premisa mayor: dado un supuesto de hecho cualquiera (H), se seguirá una con
secuencia (C). SUPUESTO-CONSECUENCIA.
Estructura de la Premisa menor: se constata un supuesto de hecho concreto (Hi). CASO ESPE
CIAL DELSUPUESTO DE HECHO CENERALCONTENIDO EN LA PREMISA MAYOR.
En consecuencia, al supuesto de hecho concreto (Hi) le sigue la consecuencia(C). SI se form a
liza este razonamiento, tendríamos lo siguiente:
Premisa mayor Si H entonces C
Premisa menor Ocurre un caso H(H1)
Conclusión ->• Dado H1 corresponde C
Esta operación lógica fue considerada por un largo tiempo por los defensores del silogismo
como único modelo correcto de razonar para los jueces. Actualmente, este tipo de raciocinio
i ITURRALDE, Victoria. “Sobre el Silogismo Judicial”. En Anuario de Filosofía del Derecho. VIII. 1991. p. 239-272.
