raciocinio será completo, seguro y plenamente motivado.
2. LA INTERPRETACIÓN JURÍDICA
Interpretar consiste en desentrañar el significado últim o del contenido de las normas jurídicas
cuando su sentido normativo no queda claro, es oscuro o ambiguo.
2.1. Tipos
Se puede distinguir una interpretación legislativa, judicial y doctrinaria, la legislativa es la de
nom inada auténtica porque proviene del propio legislador, la ju d ic ia l se denomina jurisprudencial y
la doctrinal es realizada por los ju rista s de renombre.
Si se considera la extensión y el alcance de la interpretación cabe distinguir la denominada
declarativa o estricta, la extensiva y la restrictiva. En el p rim e r caso el intérprete adecúa el espíritu
de la ley a la que expresa el texto, en el segundo extiende el texto a supuestos no comprendidos ex
p re sa m e n te ^ en el tercero lim ita su fórm ula a determ inadas circunstancias entre las mencionadas
en ella.
2 .2 . Métodos
Las diversas escuelas de interpretación propician métodos diferentes, así:
M étodo g ra m a tica l (tam bién denominado lite ra l), consiste en asignar a los dispositivos legales,
el significado que resulte de la lectura atenta de sus palabras, prestando atención a la semán
tica, la gramática y la sintaxis, prestando atención a lo que diga u omita el dispositivo legal
interpretado, independientemente del contexto en que se encuentre y de la finalidad de su
creación.
M étodo exegético o histórico, consiste en asignar a los dispositivos legales, el significado que
resulte de averiguar la intención que tuvo el legislador al momento de crear el texto legal ana
lizado, a través del análisis de documentos, informes, exposición de motivos, actas, etc., que
dieron origen al texto interpretado.
La escuela histórica, bajo la inspiración de Savigni considera que la interpretación consiste en
ponerse en lugar del legislador reproducir artificialmente sus operaciones y recompensar la
ley en su inteligencia.
Método sociológico, este método interpreta la norma a partir de la realidad social en la que se
aplicará se aplicará la norma, adaptando los conceptos e ¡deas del legislador a los tiempos
modernos.
