Tema 3: Conocim iento y aplicación de instrum entos del m étodo jurídico
M étodo de la ra tio legis, busca lo que quiere decir la norma y se desentraña su razón de ser
intrínseca, la que puede extraerse de su propio texto, basándonos en el texto del dispositivo
interpretado o en el de los dispositivos vinculados a éste, con ocasión del caso concretamente
analizado.
Método sistemático, consiste en asignar a los textos legales, el significado que resulte de aplicar
los principios o conceptos expresados en otros dispositivos legales, con los cuales el texto ana-
Iizado comparte la misma ratio, los mismos principios y los mismos conceptos (sistemático
por comparación); o el significado que resulte de aplicarle los principios, contenidos y reglas
que rigen en la rama del Derecho en la cual se encuentra ubicado el dispositivo analizado
(sistemático por ubicación).
“El buen intérprete es el que utiliza todos los métodos que cabe utilizar y elige como L
interpretación ''válidaiaquélla enda; qde iondúyén ia mayoría de ios, métodos j ;
aplicados. Desde luego, si bien el trabajo de interpretación comienza con el método literal,
no hay una prelación de importancia entre los métodos y este orden será organizado por ó
el intérprete, en general o en relación al caso de interpretación específico".2
3. LA INTEGRACIÓN DEL DERECHO
Por la Integración del Derecho se entiende a aquel procedimiento por cual ante la falta o de
ficiencia de una norma para un caso concreto se integra o une al Ordenamiento Jurídico para
llenar aquel vacío.
Este concepto se encuentra relacionado al de interpretación pero cabe aclarar que son dife
rentes; puesto que la interpretación presupone la existencia de la norma a la que se le debe
aclarar o esclarecer. Cuando la interpretación resulta impotente para resolver un caso concre
to, el intérprete (en especial el juez) debe dejar de ser tal para pasar a cumplir una función
integradora, es decir, completar o llenar los vacíos.
MÉTODOS DE INTEGRACIÓN: en la actualidad los métodos de integración son:
La heterointeg ración: Mediante este método se recurre a ordenamientos diversos (por
ejemplo, colmar las lagunas de la ley con el Derecho natural no expresado en ella, con el
Derecho Romano, con el canónico) o recurriendo a fuentes distintas de la Ley (¡acostum
bre, la jurisprudencia y la doctrina)3. Por eso se dice que este método más que ser una
integración del ordenamiento jurídico es una integración apoyándose en todo el ordena
miento jurídico.
La autointegración: La integración se da dentro de un mismo sector del ordenamiento, re-
curriéndose a la misma ley para llenar el vacío de otra ley, para lo cual se vale de la analo
gía y de los principios generales.
