3.1. Principios generales del derecho
Los Principios Generales del Derecho son aquellos postulados, ideas, fórmulas básicas o fun
damentales que constituyen la base de todo nuestro Ordenamiento Jurídico permitiendo a
través de ellos la creación, orientación e integración del Ordenamiento Legal.
Su vital importancia radica según García Enterría, en que aquellos principios son los únicos
capaces de armonizar e integrar ese acumulado de normas permanente y caótico que es la
legislación, hasta convertirla en un sistema operantey fluido.
Los principios generales cumplen dos funciones primordialmente:
a) Orientar e inspirar al ordenamiento jurídico, constituyéndose en el espíritu que contiene
toda norma positiva de tal manera que se conviertan en principios positivizados.
b) Como ayuda en la tarea integradora mediante los postulados que se encuentran fuera del
ordenamiento positivo.
El Ordenamiento Jurídico recurre a los Principios Generales del Derecho para llenar, subsanar
o cubrir los vacíos legales.
Cuando se habla de Principios Generales de Derecho en el artículo VIII del T. R del Código Civil
nosedetallasi los principios a aplicar son los referidos al campoo rama del Derecho donde se
analiza el vacío o si hablan de principios que rigen a todo el Ordenamiento Jurídico. Los Prin
cipios en los que el legislador se ha inspirado para dar la ley, son principios positivizados que
están dentro del Derecho escrito siendo éstos utilizados por la analogía con el fin de cubrir los
vacíos existentes.
En cambio cuando se cataloga a los Principios Generales del Derecho un una función subsidia
ria por falta o deficiencia de la ley se aplican aquellos que no se encuentran dentro sino fuera
del ordenamiento positivo y que se han de encontrar en los ideales de justicia, convicciones
sociales, morales, políticas nuevas o tradicionales o arraigadas en el alma del pueblo. De esta
forma el artículo VIII del T. R del Código Civil se refiere tanto a los principios generales expresa
dos como a los no expresados, pues utiliza la fórmula “Principios Generales del Derecho” y no
fórmulas como Principio General del Derecho vigente, Principio General del Ordenamiento
Jurídico del Estado.
En cuanto a la aplicación de los Principios Generales del Derecho no positivizados su uso no
debe ir en contra de los principios contenidos en la ley y a su vez respetándose la jerarquía de
los principios del Derecho Peruano.
3.2. La analogía
La analogía es un método de integración jurídica cuya particularidad consiste en que el opera
dor judicial toma una norma con un supuesto elaborado para una situación determ inada^ la
aplica a otra distinta, pero semejante a la prescrita en el texto legal.
El uso de la analogía implica necesariamente creación o innovación del Derecho.
La analogía se funda en el principio “A igual razón igual Derecho", en el principio de igualdad
(o regla formal de justicia) que prescribe que se deban tratar por igual los casos semejantes
(igualdad en los aspectos relevantes); por más que la analogía lu ri aplique principios, éstos
