Límites de la Analogía
Según Aníbal Torres6citando a Luis Diez Picaso, podemos establecer las siguientes reglas:
1. Las leyes prohibitivas y las leyes sancionadoras no admiten por lo general la analogía y
deben ser entendidas de manera restrictiva (“odiosa sunt restrigenda”, “in dubio pro reo", “in
dubio pro libertóte”).
2. Las normas limitativas de la capacidad de la persona o de los derechos subjetivos deben
considerarse también como disposiciones odiosas y por consiguiente ser entendidas de
modo restrictivo y no ampliarlas por analogía.
3. Las normas del llamado “ius singulori” o de Derecho excepcional, por su mismo carácter,
es decir, por estar establecido ‘‘contro tenorem rotionis” tampoco den ser analógicamente
extendidas (‘‘non suntproducendum ad consequentios”.
Según el art. 139-9 de la Constitución Política prescribe el principio de inaplicabilidad por ana
logía de la ley penal y de las normas que restrinjan derechos, sin embargo la garantía de pro
hibición de la analogía sólo se aplica cuando sea perjudicial para el inculpado (analogía in
malam partem), es decir, cuando se extiendan los efectos de la punibilidad a supuestos no
previstos por ley. Por el contrario, la analogía favorable (analogía in bonam partem) es acep
tada a través de los procesos de interpretación de la ley penal.
En el Derecho Penal, el principio de prohibición de analogía se aplica no sólo a los tipos pe
nales (supuestos de hecho y consecuencias jurídicas) previstos en la parte especial del Código
Penal, sino también a aquellos casos en los que la parte general comprenda preceptos que
amplíen la imputación penal, como es el caso de la tentativa, la coautoríay la participación.
Además, existen otros principios que limitan o impiden la utilización de la analogía:
No puede establecerse normas de sanción vía la analogía.
No puede crearse tributos, ni concederse exoneraciones, ni extenderse las disposiciones
tributarias por analogía.
No se puede establecer vía analogía obligaciones o prohibiciones.
No procede la analogía a partir de normas prohibitivas, excepcionales, especiales o de las
que restringen derechos.
