Conocim iento y aplicación de instrum entos del m étodo jurídico
3.3 La equidad
La idea básica de la equidad tiene un doble efecto: como expresión de igualdad, ponderación
y ecuanimidad en la aplicación de la justicia. Y también, como expresión de comprensión y
mitigación en el momento de establecer las consecuentes jurídicas negativas (aplicación de
penas, sanciones).
Clases:
Equidad c o r r e c tiv a Es una manifestación de ponderación, juicio cabal y prudencia en la
aplicación de una norma, útil como elemento de apoyo para el intérprete o hermenéutica
en latécnicade interpretación. Enmienda los defectos que pudiera acarrear una norma al
ser aplicada a casos particulares y concretos no previstos de manera plenaria porel legis
lador.
Equidad sustantiva.- Es un criterio integrador propiamente dicho (tarea legislativa), como
mecanismo de sustitución de la incuria, negligencia, ocio, autorización o delegación atri
buí bles a legislador aquí, la equidad es base exclusiva de una decisión administrativa o
judicial. Esta modalidad se emplea en tres casos:
a) Cuando el ordenamiento jurídico expresamente permite al funcionario público re
solver según su concienciay leal sabery entender. Se trata de una facultad discrecio
nal.
b) Cuando el ordenamiento jurídico expresamente permite al funcionario público con-
cretizar o cubrir los denominados conceptos elásticos (buena fe, orden público, mo
ral social y buenas costumbres, etc.).
c) Cuando el ordenamiento jurídico expresamente permite al funcionario público to
mar en cuenta las circunstancias especiales que rodean el caso particular.
Esta modalidad es consecuencia de una permisión legislativa. Como modo de integración,
permite al operador del derecho enderezar el derecho vigente, encauzando las estructuras
jurídicas de conformidad con la realidad, es decir, según la naturaleza político-social del en
torno.
Funciones:
Es uno de los modos como se suplen las lagunas de la ley; es un mecanismo de ayuda que
aparece mediante la “individualización” de la justicia, adaptando la ley a circunstancia
particulares,
Es la correcta aplicación de la ley; pues api ¡cada “atípico” caso de manera literal, generaría
consecuentes jurídicas injustas. Ayuda a flexibilizar la general idad de una norma jurídica,
en vista de las particularidades que concurren en un caso no percibido con nitidez por el
legislador.
Es la utilización de un criterio racional; avalado por el valor que sustenta al derecho. Im
plica un margen de discrecionalidad lógico-jurídica que asiste a la función judicial. En
esta función, la equidad constituye la piedra angular de la grandeza de la labor del juez,
quien es el encargado de conciliar su vinculación con la ley al juzgarse un caso concreto,
promoviendo el equilibrio entre la seguridad jurídica y la justicia.
