3.4. La argumentación jurídica
La pregunta sobre qué es "argumentación jurídica” no es rápiday tampoco es fácil de respon
der, como advierte Manuel Atienza.
Para el autor, “la teoría de la argumentación jurídica alcanza tres campos:
a) El de la producción de normas, se atiene a la fase legislativa de las normas.
b) El de la aplicación de normas, pretende dilucidar los llamados hará cases o casos difíciles
relativos a la interpretación y aplicación del derecho.
c) El de la dogmática jurídica, ofrece a los órganos jurídicos responsables por laactividadde
la creación y aplicación de las normas, criterios auxiliares en el proceso de adopción de la
decisión en el momento en que una norma deba ser aplicada al caso concreto7.
La configuración actual de la teoría de la argumentación jurídica es producto de la evolución
y sintetización de distintas teorías predecesoras la teoría que puede considerarse como la do
minante es la teoría de la argumentación jurídica de Robert Alexy, sostiene que la Argumen
tación jurídica es un caso especial del discurso práctico general y cuyo objetivo fundamental
es el cómo fundamentar las decisiones jurídicas.
La teoría de la argumentación jurídica tiene dos aspectos fundamentales: la justificación in
terna, la cual implica que la conclusión se derive directamente, a través de un silogismo jurí
dico, de las premisas; y la justificación externa, que implica la justificación de las premisas
empleadas en la justificación interna.
Tipos de argumentación:
A iege lata, de acuerdo a la ley vigente.
A legeferenda, cuando se invoca una ley que está por tener vigencia.
A autorictate, cuando se utiliza como respaldo de una argumentación a una autoridad,
autor, de una institución o quizá de una sentencia del Tribunal Constitucional por ejem
plo.
A dpopulum , se utiliza para enervarsentimientos del pueblo.
Analítica, implica descomponer el argumento, desmembrar, para luego volver a compo
ner, como se hace en las sentencias del Tribunal Constitucional al desmembrar conside
rando por considerando.
A fo rtio ri, el que puede lo más puede lo menos, ejemplo Si la declaración de ¡nconstitu-
cionalidad tiene efectos derogatorios y es erga onrnes, entonces la interpretación que el
Tribunal efectúe debe tener carácter general.
A remd, cuando se funda en hechos notorios, hechos evidentes, de conocimiento general.
Se utiliza generalmente en el ámbito civil, puesto que lo evidente no se prueba.
A rubrica, basado en la realidad, utiliza explicando el momento histórico. Ejemplo-, "no se
puede amparar el derecho al trabajo de todos porque el Estado está en crisis”.
