3.5. La justificación de las decisiones judiciales y fiscales
3.5.1. Justificación de las decisiones judiciales
Según Robert ALEXY, toda decisión jurídica, debe cumplir dos niveles mínimos de fundamen-
tación o justificación: Uno, denominadojustificación Interna, que trata de versi ladecisión del
Juez es lógica, es decir si se corresponde lógicamente con las premisas que se proponen como
su sustento, y otro segundo nivel denominado Justificación Externa, que tiene que ver con la
corrección o fundamentación racional del contenido de las premisas usadas en la justificación
interna. Así, toda sentencia debe tener:
a) Un nivel lógico formal, de validez, del razonamiento deductivo.
b) Un nivel argumentativo, respecto a los hechosy pruebas que corresponden a la controver
sia, en función a las normas, conceptos e instituciones con los cuales se interpretan y se
califican jurídicamente tales hechosy pruebas.
A. Justificación interna de la sentencia
La justificación interna de la sentencia se refiere a la validez formal de la decisión a que ha
llegado el Juez. Alude a la coherencia lógica de una resolución judicial.
Perspectiva lógico formal: una conclusión es necesariamente verdadera si deriva de la inferen
cia válida de dos premisas verdaderas, es decir lógicamente correctas, válidas.
La justificación interna, permite determinar pues, si el paso de las premisas a la conclusión tie
ne lugar de acuerdo con las reglas del razonamiento lógico; en suma, se refiere a la corrección
o validez de la inferencia, expresada en la conclusión de la sentencia.
Para lograr la justificación interna se hace uso del SILOGISMO, como estructura mínima de
razonamiento lógico-formal.
