Pero para resolver casos más complejos este esquema lógico - deductivo básico no es suficiente, se utiliza
rán formas de silogismos rnás complejos derivados del modelo clásico, denominado por Santa Cruz como
SILOGISMO DECISIONAL5, por ejemplo:
PREMISA MAYOR o NORMATIVA: Si alguien mata, mediante una conducta típica y antijurídica que le sea
imputable personalmente, entonces ha cometido delito de homicidio y se le aplicará una consecuencia
penal, a ser determinada por el Juez.
PREMISA MENOR o FACTICA: Está probado que Juan ha matado a Pedro mediante una conducta típica,
antijurídica y que le es imputable personalmente.
CONCLUSIÓN: Juan ha cometido delito de homicidio y se le aplicará una pena.
Este esquema es resultado de sucesivos silogismos previos, a los que se denomina SILOGIS
MOS COMPLEMENTARIOS; por ejemplo: revisando la premisa menor o fáctica del modelo pre
cedente, se ve que en ella se afirma que está probada la tipicidad, antijuricidady culpabili
dad de la conducta de Juan; tal cosa significa que previamente, respecto a cada una de dichas
cuestiones se ha tenido que dilucidar, mediante otros tantos silogismos previos, si los hechos
Incriminados a Juan, se subsumen en los criterios que determinan: i)La tipicidad, z) La antiju
ricidad, 3) La responsabilidady 4) Punibilidad Penal.
B. Justificación externa de la sentencia
Consiste en la fundamentación de las premisas del silogismo planteado en la justificación
interna.
Robert Alexy manifiesta que, el juicio sobre la racionalidad de la decisión, pertenece al campo
de la justificación externa.
Por justificación externa de la sentencia, se entiende a la fundamentación, razonable, adecua
da, suficiente y conforme al debido proceso, del contenido de las PREMISAS que integran el
