Tema 3: Conocim iento y aplicación de instrum entos del m étodo jurídico
silogismo planteado en la justificación interna o estructura lóg ica-fo rm al, del razonamiento
judicial. Como tal, se refiere a la justificación de la decisión del Juez, desde el punto de vista de
sus argumentosy comprende la justificación del contenido de la premisa normativa (premisa
mayor) y la justificación del contenido de la premisa fáctica (premisa menor).
Esta delimitación de los términos, conceptos, definiciones y argumentos incluidos en las pre
misas de la decisión judicial, requiere de una amplia gama de aportes o nociones teóricas y
doctrinarias.
C. Justificación de las decisiones fiscales
Quien administra justicia, (jueces y fiscales), deben respaldar sus decisiones en explicaciones
razonadas, a partirde los tres tipos de racionalidad propuesta por ATIENZA, que son: la lógica
y lingüística, las de soporte (de las premisas); y la discursiva.
Respecto a la sentencia que dictará el Juzgador conforme a sus atribuciones, el papel del M i
nisterio Público, como defensor de la legalidad y titu lar de la acción penal, consagrado por
el artículo 159 de la Constitución, resulta muy importante; pues, a lo largo de todo el proceso
debe dirigir la investigación y aportar la carga de la prueba; tarea que se explícita más en el
nuevo Código Procesal Penal.
El interés por el razonamiento judicial y fiscal, parte del rechazo tanto de una concepción
mecanicista de la aplicación del derecho, como de posturas irracionalistas. La aplicación del
derecho no puede reducirse a la remisión a ciertos enunciados jurídicos y a unos hechos “bru
tos” (premisas m ayory menor del tradicional silogismo judicial), es por ello que, a la hora de
analizar la aplicación del derecho, las nociones de razonamiento o justificación deben ocupar
un lugartan central como el principio de legalidad. Y es aquí donde la justificación se muestra
en suma importante, por lo que podría decirse que no hay aplicación del derecho sin ju s tifi
cación: sólo puede mostrarse que una decisión judicial o fiscal está justificada si se ofrecen
razones en apoyo de las mismas.
3.6. La ponderación
La ponderación denominado también “principio de proporcionalidad” es otro método estruc
tural, como también lo es el denominado silogismo jurídico (subsunción). Es utilizableen los
denominados casos difíciles, relativos a colisiones de principios sobre derechos fundam enta
les.
Consiste en el proceso de asignación de pesos a los principios en conflicto, para preferir aquel
que haya obtenido mayor peso de importancia (Balancing).
La ponderación implica - en un caso concreto de colisión de principios - la preferencia por el prin
cipio de mayor importanciay la afectación de otro principio que se considere de menor importancia.
Es un procedimiento racional (pero limitado) que contribuye a la solución de conflictos entre
principios, pero no ofrece resultados definitivos y exentos de alguna subjetividad.
La ponderación dota de coherencia lógica al razonamiento jurídico, pero no en sentido abso
luto, porque sus resultados no siempre son unívocos.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 46 of 1506 --

UBILEX
Dilemas:
La ponderación se utiliza en los dilemas sobre la preferencia entre 2 o más derechos fun
damentales que colisionan en un determinado caso.
El dilema puede ser una mera disyuntiva entre preferir un principio u otro, cuando la pre
ferencia por uno de ellos implica necesariamente la afectación o la no satisfacción del
otro. Este caso se resuelve gracias a la asignación de pesos de importancia a los principios
en conflicto.
El dilema puede ser trágico en los casos de empate insoluble, cuando se presentan ausen
cia de razones objetivas para preferir uno en lugar del otro, dado que los dos principios
son considerados de igual peso, de acuerdo a la fórm ula de peso que se haya empleado.
Ejem plo: Elegir entre la vida del feto por nacery la madre, cuando la preferencia por la vida de
uno implica necesariamente la muerte del otro.
Ley de la Ponderación:
“Cuanto mayores el grado de la no satisfacción o de afectación de uno de los principios, tanto
mayor debe ser la importancia de la satisfacción del otro".
Si se sigue esta ley, la ponderación se puede dividir en tres pasos que el propio Alexy identifica
claramente:
Primer paso, es preciso definir el grado de la no satisfacción o de afectación de uno de los
principios.
Segundo paso, se define la importancia de la satisfacción del principio que juega en sen
tido contrario.
Tercer paso, debe definirse si la importancia de la satisfacción del principio contrario jus
tifica la afectación o la no satisfacción del otro".
El primero y el segundo paso de la ponderación son análogos. En ambos casos, la operación
consiste en establecer un grado de afectación o no satisfacción-del primer principio—y de im
portancia en la satisfacción-del segundo p rincipio- En adelante nos referiremos a ambos fe
nómenos como la determinación del grado de afectación de los principios en el caso concre
to. Alexy sostiene que el grado de afectación de los principios puede determinarse mediante
el uso de una escala tríadica o de tres intensidades. En esta escala, el grado de afectación de
un principio en un caso concreto puede ser “leve”, “medio”o “intenso”.
Ejem plo, la afectación de la vida y la salud de una niña, que se originaría al perm itirá los pa
dres evangélicos no llevarla al hospital, podría catalogarse como intensa, dado el peligro de
muerte. De forma correlativa, la satisfacción de la libertad de cultos de los padres, que se de
rivaría de dicha permisión, podría graduarse sólo como media o leve.
En los casos fáciles, es posible determinar el peso de los principios, sin embargo, existen
casos difíciles en los que no es posible ponderar de manera enteramente lógica, en estos
últimos, como en los empates, la asignación de pesos y los argumentos para preferir un
principio se tiñe de discrecionalidad subjetiva.
