1. TEORÍA GENERAL DE LOS DERECHOS FUNDAMENTALES
1.1. Contenido y alcances
La acepción derechos fundamentales (ároits fondamentaux) que se gesta en pleno movimien
to político y cultural en Francia hacia 1770 también se emplea para referirse a los derechos
constitucionales. Adquirió auge en Alemania en la Ley Fundamental de Bonn de 1949, con el
nombre de Grundrechte mediante el cual se articula el sistema de relaciones entre el individuo
y el Estado, en cuanto fundamento de todo el orden jurídico político.
Señala el profesor Luis Castillo Córdova1 que “Una mirada rápida a la Constitución peruana (CP)
permite constatar que en ella se emplea las expresiones derechos fundamentales2 y derechos
constitucionales3. Todos son derechos constitucionales al estar recogidos en la Constitución, lo que
permitiría hablar de derechos constitucionales fundamentales y de derechos constitucionales no
fundamentales. Esta constatación exige plantear la siguiente cuestión: en la Constitución peruana,
¿es constitucionalmente correcta esta diferenciación? Veamos. Si fuese correcta habría que admitir
la necesidad de diferenciar unos derechos de los otros y, consecuentemente, la necesidad de optar
por un criterio diferenciador. Este no podría ser más que la importancia del derecho, de modo que
unos derechos— los constitucionales fundamentales— serían más importantes que los otros —
los constitucionales no fundamentales— . Este criterio pareciera ser el adoptado por el Constitu
yente peruano a la hora que ha dividido el Título I de la siguiente manera: Derechos fundamentales
de la persona (Capítulo I); De los derechos sociales y económicos (Capítulo 11); y De los derechos
políticos y de los deberes (Capítulo III). De forma tal que los derechos reconocidos en el Capítuloi
serían derechos (constitucionales) fundamentales, y estos serían los recogidos en la larga lista del
1 Anuario Iberoamericano de justicia Constitucional. El Contenido Constitucional de los Derechos Fundamentales.
Madrid 2010, p. 91.
2 La expresión se halla recogida en el rótulo del capítuloxdel Título I; en el artículo 34-4 CP en el que se dispone
que «No pueden someterse a referéndum la supresión o la disminución de los derechos fundamentales de la
persona»; en el artículo 74 CP: «Estado, al ejercer la potestad tributarla, debe respetarlos principios de reserva
de la ley, y los de igualdad y respeto de los derechos fundamentales de la persona»; en el artículo 137.2 CP;
«Estado de sitio, en caso de invasión, guerra exterior, guerra civil, o peligro inminente de que se produzcan,
con mención de los derechos fundamentales cuyo ejercicio no se restringe o suspende»; entre varios otros.
3 Así, aparece empleada en el artículo 23 CP: «Ninguna relación laboral puede limitar el ejercicio de los dere
chos constitucionales»; en el artículo 137.1 CP: «Estado de emergencia, en caso de perturbación de la paz o
del orden interno, de catástrofe o de graves circunstancias que afecten la vida de la Nación. En esta eventua
lidad, puede restringirse o suspenderse el ejercicio de los derechos constitucionales relativos a la libertad y
la seguridad personales, la inviolabilidad del domicilio, y la libertad de reunión y de tránsito en el territorio
comprendidos en los incisos 9,11 y 12 del Artículo 2° y en el inciso 24, apartado f del mismo Artículo»; artículo
162 CP: «Corresponde a la Defensoría del Pueblo defender los derechos constitucionales»; entre varios otros.
