Tema 4. Teoría general de la Constitución
artículo 2 CP; todos los demás derechos recogidos en la Constitución serían derechos constitucio
nales (no fundamentales). Sin embargo, quienes pretendan sostener esta conclusión se enfrentan
a las siguientes dificultades. Primera, si fuese verdad que la lista de derechos recogida en el artí
culo 2 CP sólo contiene derechos fundamentales, es decir, derechos con una mayor importancia
o fundamentalidad que los demás, entonces, no se entiende cómo en el mencionado artículo se
reconocen derechos como el derecho a la paz, a la tranquil idad, al disfrute del tiempo libre y al des
canso (artículo 2.22 CP) que en una división entre derechos más importantesy menos importantes,
sería necesariamente de los segundos. Segunda, si los derechos sociales y los derechos políticos
fuesen derechos constitucionales no fundamentales por estar fuera del artículo 2 CR entonces, no
se entiende que en esta disposición constitucional vengan mencionados derechos típicamente so
ciales como el de trabajar libremente (artículo 2.15 CP), o derechos típicamente políticos como los
de elección, de remoción o revocación de autoridades, de iniciativa legislativay de referéndum (ar
tículo 2.17 CP). Y tercera, si se admitiese que en la Constitución peruana hay dos clases de derechos
diferenciados por su mayor o menor importancia o fundamentalidad, entonces, necesariamente
se requiere que existan dos mecanismos de protección con eficacia diferente: el mecanismo menos
eficaz estará destinado a proteger derechos no fundamentales, y el de mayor eficacia a los dere
chos fundamentales4. Pero ocurre que en la Constitución peruana están recogidos mecanismos de
protección de derechos con una misma eficacia constitucional5. Cada una de estas tres dificultades
se convierte en una razón para sostener como incorrecta la conclusión de que en la Constitución pe
ruana hay que diferenciar los derechos constitucionales fundamentales de los no fundamentales.
Por el contrario, cada una de ellas aboga por otorgar una misma consideración a todos los derechos
recogidos en la Constitución.
De modo que con la expresión derechos fundamentales o derechos constitucionales se hace
alusión a lo mismo: a la constitucionalización de una serie de exigencias humanas que, for
muladas como bienes humanos, son debidos a la persona por ser tal. Está legitimado, por
tanto, el empleo de una u otra expresión”.
El Tribunal Constitucional emitió su primer precedente vinculante, caso Anicama Hernández (STC
Exp. N°i4i7-2005-PA/TC), donde estableció con carácter general los alcances de la protección del
derecho a la pensión a través de un proceso de amparo. Sin embargo, en dicho precedente también
se establecieron algunos alcances generales de los derechos fundamentales. Así tenemos:
1. Los derechos fundamentales de la persona humana
El Tribunal Constitucional define los derechos fundamentales basado en el Neoconstitucio-
nalismo, doctrina iusfilosófica predominante en un Estado Constitucional de Derecho y que
