Consecuentemente, si bien el reconocimiento positivo de los derechos fundamentales (comúnmente, en
la Norma Fundamental de un ordenamiento) es presupuesto de su exigibilidad como límite al accionar del
Estado y de los propios particulares, también lo es su connotación ética y axiológica, en tanto manifiestas
concreciones positivas del principio-derecho de dignidad humana, preexistente al orden estatal y proyecta
do en él como fin supremo de la sociedad y del Estado (artículo 10 de la Constitución).
FJ. 4. La enumeración de los derechos fundamentales previstos en la Constitución, y la cláusula de los
derechos implícitos o no enumerados, da lugar a que en nuestro ordenamiento todos los derechos funda
mentales sean a su vez derechos constitucionales, en tanto es la propia Constitución la que incorpora en el
orden constitucional no sólo a los derechos expresamente contemplados en su texto, sino a tocios aquellos
que, de manera implícita, se deriven de los mismos principios y valores que sirvieron de base histórica y
dogmática para el reconocimiento de los derechos fundamentales.
2. Proceso de amparo y derechos fundamentales.
F.J. 8: "Reconocer que el proceso de amparo sólo procede en caso de afectación directa de los
derechos fundamentales (expresos o implícitos), implica, ante todo, determinar si la:(supuéstau
afectación en la que incurre el acto u omisión reputada de inconstitucional, en efeetoyincide*
sobre el ámbito que resulta directamente protegido por dicho derecho.
Este presupuesto procesal, consustancial a la naturaleza de todo proceso constitucional, ha
sido advertido por el legislador del Código Procesal Constitucional (C.P.Const.), al precisar en el
inciso 1) de su artículo 5 o que los procesos constitucionales no proceden cuando "[¡Jos hechos y el petitorio
de la demanda no están referidos en forma directa al contenido constitucionalmente protegido del derecho
invocado” ,6
■ ■
Con esta afirmación el Tribunal Constitucional se adhiere en principio a la teoría absoluta del
contenido esencial de los derechos fundamentales, por la cual no todo el derecho será pro
tegido por las garantías constitucionales, sino sólo aquella parte que es su “núcleo duro”, que
está conformado por las características básicas del derecho que permiten hacerlo lo que es y
diferenciarlo de los demás.
