En tal perspectiva, existen determinados derechos fundamentales cuyo contenido constitucional directamen
te protegido, requiere ser delimitado por la ley sea- porque asilo ha previsto la propia Caria Fundamental (vg.
el artículo 27° de la Constitución en relación con el derecho a la estabilidad laboral. Cfr. STC 0976-2001 -AA,
Fundamento 11 y ss.) o en razón de su propia naturaleza (vg. los derechos sociales, económicos y culturales).
En estos casos, nos encontramos ante las denominadas leyes de configuración de derechos fundamentales.
Los derechos fundamentales cuya configuración requiera de la asistencia de la ley no carecen de un con
tenido per se inmediatamente exigióle a ¡os poderes públicos, pues una interpretación en ese sentido sería
contraria al principio de fuerza normativa de la Constitución. Lo único que ello implica es que, en tales
supuestos, la ley se convierte en un requisito sine qua non para la culminación de la delimitación concreta
del contenido directamente atribuidle al derecho fundamental".
Agrega el supremo intérprete de la Constitución a través de la STC Exp. 3330-2004-AA/TC. Fj.9.
respecto de los derechos fundamentales [“estos derechos poseen un doble carácter: son, por un
lado, derechos subjetivos; pero, por otro lado, también instituciones objetivas valorativas, lo
cual merece toda la salvaguarda posible. En su dimensión subjetiva, los derechos fundamentales
no sólo protegen a las personas de las intervenciones injustificadas y arbitrarias del Estado y de
terceros, sino que también facultan al ciudadano para exigir al Estado determinadas prestaciones
concretas a su favor o defensa; es decir, éste debe realizar todos ios actos que sean necesarios afín
de garantizar la realización y eficacia plena de los derechos fundamentales. El carácter objetivo
de dichos derechos radica en que ellos son elementos constitutivos y legitimadores de todo el or
denamiento jurídico, en tanto que comportan valores materiales o instituciones sobre los cuales
se estructura (o debe estructurarse) la sociedad democrática y el Estado constitucional”].
El maestro Raúl Ferrero R., considera que la Teoría del Estado es la disciplina filosófica que in
vestiga la esencia y finalidad del Estado. Su meta es valorativa, axiológica. La teoría del Estado
se enfrenta a lo inasequible, pues la captación de la esencia del Estado no es certera ni fácil.
La Teoría del Estado es la ciencia que tiene por objeto el estudio sistemático y metódico del
Estado considerando a éste como una realidad social, política y cultural jurídica dinámica,
camblantey consecuentemente histórica.
2.1. El Estado
El Estado es la organización jurídico-política, de la sociedad concebida como Nación. Incluye su go
bierno, sus instituciones públicas, sus leyes y las reglas de juego válidas para la vida social en general.
En el caso peruano el Perú es una república democrática, social, independientey soberana. El Es
tado es uno e indivisible. Su gobierno es unitario, representativo y descentralizado, y se organiza
según el principio de la separación de poderes. (Art. 43o Constitución).
Según el Tribunal Constitucional STC Exp. N° 0020 y 0021-2005-AI: “el carácter descentralizado
del Estado peruano no es incompatible con la configuración de Estado unitario, desde el momento que, si
bien ella supone el establecimiento de órganos de poder territorialmente delimitados, a los cuales se les
dota de autonomía política, económica y administrativa; no obstante, el ejercicio de éste debe realizarse
dentro de lo previsto por la Constitución y las leyes, marco que regula el reparto que competa a los gobier
nos regionalesy municipales”.
52 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 53 of 1506 --

Tema 4: Teoría general de la Constitución
2 2 . Elementos del Estado
Elementos Sociológicos:
a. Población: Grupo de personas que habitan en un territorio determinado.
b. Territorio: Espacio físico material, constituido por el suelo, subsuelo, espacio aéreo y do
minio marítimo, en que se lleva a cabo la actividad estatal y donde el Estado ejerce sus po
testades. Es el lugar geográfico en el que habita una población determinada; es el soporte
físico de la Nación y del Estado.
Elementos Jurídicos:
a. Gobierno: Representa al Estado y ejecuta sus funciones políticas, bajo la dirección de un
jefe de Gobierno o jefe de Estado.
b. Poder: Es el atributo del Gobierno.
El poderes la capacidad de una persona o conjunto de personas de imponer sus decisiones a una
comunidad, determinando su obedienciay garantizándola, si es menester, con la coerción.
Distribución funcional del poder del Estado:
a. - Función controladora.- El aseguramiento de la limitación del poder a favor de los valoresy
principios condicionantes de la acción estatal. Deviene en supervisar la idoneidad, eficien-
ciay eficacia en el desarrollo de los planes y política en la administración de los recursos
materiales, personales y económicos que tienen a su cargo los funcionarios que ejecutan
las directivas, evaluación y hasta de anulación de actos administrativos o legislativos con
trarios a la Constitución o las leyes.
b. - Función legislativa.- Esta función le corresponde al Parlamento, puesto que todas las le
yes tiene que pasar por él, las cuales aparecen como obra suya. La Constitución le da otra
función al Parlamento: controlar el gobierno.
c. - Función ejecutiva-administrativa.- Referida a la dirección de la política general (interna
y externa). Dicho de otra manera se encarga de velar por la administración del Estado, la
economía, la defensa militar, la política social, etc. Según la Constitución, posee iniciativa
legislativa, puesto que puede presentar leyes al gobierno. El gobierno tiene legislación
delegaday reglamentaria.
d. - Función jurisdiccional.-Su función es la de administrar justicia de acuerdo con la Cons
titución. Los jueces encuentran una limitación en la Constitución y las leyes. Esta función
requiere de autonomía para desenvolverse, no sólo porque está en juego la libertad o los
derechos de la persona, sino porque se ha convertido en una garantía económica al ser
imparcial en las controversias entre inversionistas y el Estado.
Distribución territorial del poder del Estado:
El Estado Unitario
Es aquel donde el poder político se manifiesta desde un solo centro de afluencias y decisión.
Se trata de una única instancia reconocida como detentadora del poder. El Estado unitario
conlleva que lo órganos de poder político se encuentren concentrados o reunidos en un solo
núcleo gubernamental.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 54 of 1506 --

UBILEX
a) Estado unitariostrictosensu: Esta forma de Estado se caracteriza porque la autoridad cen
tral del Estado monopoliza el poder de mando en el ejercicio de las funciones públicas, el
cual se encuentra organizado piramidalmente. Existe un solo centro de impulsión políti
ca.- el gobierno central.
b) Estado unitario desconcentrado: En esta forma de Estado la autoridad central del Estado
atenúa un cierto grado de su vocación aglutinadora. La desconcentración implica el acto
de delegación de funciones, atribuciones y decisiones desde el nivel de una autoridad
superior, hacia autoridades subordinadas a ella dentro del ámbito del mismo organismo
público.
c) Estado unitario descentralizado: La descentralización permite establecer organismos y
entidades en diversos espacios - local, departamental, regional- a fin de cumplan fun
ciones que anteriormente eran desempeñadas por el propio gobierno central. En otras
palabras el gobierno, la ley, la autoridad, la justicia, se descentraliza. Sale del centro y se
concede a los representantes del interior un margen de autonomía para administrarse en
determinadas materias, pero siempre dentro de la Constitución, los Códigos y la política
general del gobierno.
2.3. El Estado Complejo
Es aquel que está conformado por una pluralidad de organizaciones político-jurídicas exter
namente unidas, lo que da origen a los denominados Estados de Estados.
a) La confederación: Es la unión permanente de estados independientes, cuyo fin u objetivo
consiste en la mutua cooperación en un determinado rubro de materias y actividades, con
servando cada cuerpo político como título principal su soberanía. La confederación se en
cuentra compuesta por unidades políticas que no pierden su calidad de estados soberanos
por el mero hecho de su asociación.
b) El Estado federal: Es un conjunto de comunidades políticas, primigeniamente sobera
nas, que deciden asociarse a efectos de constituir una organización política superior para
alcanzar metas y objetivos comunes.
c) El Estado libre asociado: Es el cuerpo político que mediante un acto de libre determina
ción y por la vía de un tratado, se liga a otro a efectos que este asuma su defensa y repre
sentación internacional.
2.4. Estructura del Estado
La estructura del Estado Peruano, lo constituyen el conjunto de organismos que conforman el
llamado Sector Público, bajo el PRINCIPIO DE SEPARACIÓN DE PODERES, por el cual cada uno
de los organismos del Estado ejerce sus funciones propias mediante órganos especializados
en base a la división del trabajoy al principio de coordinación.
El principio de separación de poderes, reconocido en el artículo 43° de la Constitución,(...) un sis
tema de control y balance entre los poderes del Estado así como la existencia de relaciones de
coordinación y cooperación entre ellos. Así entendido, el principio de separación de poderes se
