Tema 4: Teoría general de la Constitución
constituye en una garantía de los derechos constitucionalmente reconocidos y en un límite al
poderfrente al absolutismoy la dictadura.
Si bien nuestra Constitución reconoce las funciones básicas del Estado, legislativa, ejecutiva, y
jurisdiccional, no puede asumirse que: i) Que éstas sean las únicas funciones; ii) Que existan
distinciones nítidas y rígidas entre tales funciones del Estado; y iii) Que se encuentren en un
rango superior a las funciones de los órganos constitucionales. (STC Exp. N° ooos-zooy-PI/TC)
2.5. Funciones y competencias de los poderes del Estado
a. Poder Legislativo
El Poder Legislativo reside en el Congreso, consta de Cámara Única. El número de
congresistas es de 130. El Congreso se elige por un período de 05 años mediante un
proceso electoral organizado conforme a ley. Los candidatos a la presidencia no pue
den integrar las listas de candidatos a congresistas. Los candidatos a vicepresidentes
pueden ser simultáneamente candidatos a una representación al Congreso. Para
ser elegido congresista se requiere ser peruano de nacimiento, haber cumplido
25 años y gozar del derecho de sufragio. (Artículo 90o Constitución). El mandato
legislativo es irrenunciable. Las sanciones disciplinarias que impone el Congreso a
los representantes y que implican suspensión de funciones no pueden exceder de
120 días de legislatura. (Art. 95° Constitución).
Funciones
Función de control político.- Los mecanismos o procedimientos de control reconoci
dos por el ordenamiento jurídico peruano son: - Investidura al Consejo de Ministros.
- Interpelación. - Voto de Censura. - Acusación Constitucional o Antejuicio Político. -
Comisiones y Subcomisiones de Investigación.-Comisión de Fiscalización.-Revisión
de actos legislativos del Ejecutivo. -Control del presupuesto. -Pedidos de informes.
- Invitación a informar. - Estación de Preguntas.
ACUSACIÓN CONSTITUCIONAL Y AN TEJU iO O POLÍTICO
El Congreso de la República lleva adelante procesos (ACUSACIÓN CONSTITUCIO
NAL) destinados a evaluar la conducta de sus integrantes o de los funcionarios de
Estado que la Constitución taxativamente refiere (Arts. 99 y 100), diferenciándose
aquellos en razón de la naturaleza de los hechos:
a. Si se trata de delitos sólo el Poder Judicial puede juzgarlos y por ello el papel
del Congreso es habilitante de ese juzgamiento. Para esa habilitación existe el
antejuicio político.
b. Si se trata de infracciones constitucionales el propio Congreso los juzga y san
ciona. Para ese juzgamiento existe el Juicio Político ante la Comisión de Acusa
ciones Constitucionales, la Comisión Permanentey el Pleno.
c. Si se trata de faltas éticas, el propio Congreso las evalúa y sanciona. Para esa
evaluación existe el proceso sancionadorante la Comisión de Éticay el Pleno del
Congreso.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 56 of 1506 --

UBILEX
En el modelo peruano de acusación constitucional, conviene establecer muy breve
mente necesarios deslindes conceptuales entre instituciones que, aunque diferentes
en su origen y tradición, suelen confundirse:
Antejuicio político:
El Tribunal Constitucional en laSTCExp. N°00006-2003-AI/TC-Lima (Caso 65Congresistas)
ha señalado de manera acertada: "Del privilegio del antejuicio político son beneficiarios el Pre
sidente de la República, los congresistas, los Ministros de Estado, los miembros del Tribunal Consti
tucional, los miembros del Consejo Nacional de la Magistratura, los Vocales de la Corte Suprema,
los Fiscales Supremos, el Defensor del Pueblo y el Contralor General de la República (artículo 99 de
la Constitución).
En virtud de dicho privilegio, los referidos funcionarios públicos tienen el derecho de no ser procesados
penalmente por la jurisdicción ordinaria, si no han sido sometidos previamente a un procedimiento
político jurisdiccional, debidamente regulado, ante el Congreso de la República, en el cual el cuerpo
legislativo debe haber determinado la verosimilitud de los hechos que son materia de acusación, así
como su subsunción en un(os) tipo(s) penal(es) de orden funcional, previa e inequívocamente estable
cido(s) en la ley.
En ese sentido, en el antejuicio solo cabe formularse acusaciones por las supuestas responsabilidades
jurídico-penales (y no políticas) de los funcionarios estatales citados en el artículo 99 de la Constitu
ción, ante los supuestos delitos cometidos en el ejercicio desús funciones. Una vez que el Parlamento
ha sometido a investigación la denuncia (que puede provenir de su propio seno)y ha determinado
la existencia de suficientes elementos de juicio que, desde su perspectiva, configuran la comisión de
un delito en el ejercicio de las funciones, actúa como entidad acusadora, dejando sin efecto la pre
rrogativa funcional del dignatario, suspendiéndolo en el ejercicio de sus funciones, y poniéndolo a
disposición de la jurisdicción penal.
De esta forma, en los casos de antejuicio, las funciones del Congreso pueden ser, en cierta medida,
asimiladas a las del Ministerio Público (porque acusa), e incluso a las del juez instructor (porque
previamente investiga), pero nunca a las del juez decisor (porque nunca sanciona). Y es que la fa
cultad de aplicar sanciones sobre la base de argumentos jurídico-penales, es exclusiva del Poder
Judicial.”
En síntesis, el antejuicio es una prerrogativa funcional de la que gozan determinados fun
cionarios, con el propósito de que no puedan ser procesados ante la judicatura penal por
los delitos cometidos en el ejercicio de sus funciones, sin que medie un procedimiento
con las debidas garantías procesales ante el Congreso de la República y la consecuente
acusación del propio Legislativo.
juicio político
Según el Tribunal Constitucional STC Exp. N° 00006-2003-Al/TC-Lima (Caso 65 Congresis
tas): "(...), el Tribunal Constitucional considera que la función congresal sancionadora, prevista en
el primer párrafo del artículo io o ° de la Constitución, no sólo puede ser ejercida en aquellos casos en
los que exista una sentencia condenatoria emanada del Poder Judicial, por los delitos funcionales en
que incurran los funcionarios previstos en su artículo 99o, sino también en los casos en que se confi-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 57 of 1506 --

Tema 4: Teoría general de la Constitución
guren responsabilidades eminentemente políticas, aun cuando no exista la comisión de un delito de
por medio. Y es que si bien la función puni ti vo-j urisd icciona I es privativa del Poder Judicial (aquella
que puede sancionar sobre la base de la "razón jurídica”), la función político-punitiva (aquella que
puede sancionar sobre la base de la “razón política”) no lo es. Y no podría serlo, pues justamente el
principio de separación de poderes es el que garantiza la ausencia de toda valoración política en las
decisiones del Poder Judicial.
Lo expuesto permite afirmar que en la Carta Fundamental no solamente se encuentra consagra
do el antejuicio, sino también el juicio político, esto es, aquel que permite iniciar un procedimiento
a los funcionarios enumerados en su artículo 9 9 °, en razón de las “faltas políticas" cometidas en el
ejercicio desús funciones, con la finalidad de “retirar el poder de quien hace mal uso de él e impedir
que [...] pueda ser reinvestido de poder en el futuro.” (Broussard, Paulo. O impeachment. Editora
Sara i va. ida. Ed, 1992. p. 77)■ Al respecto, Bidart Campos refiere que “se lo denomina juicio “político”
[...] porque no es un juicio penal; en él no se persigue castigar sino separar del cargo; no juzgar un
hecho como delictuoso, sino una situación de gobierno como inconveniente para el Estado". (Manual
de Derecho constitucional argentino. Ediar., 1986. p. 611).
Esa es la manera como se debe interpretar la previsión constitucional según la cual está permitido
acusar a los referidos funcionarios públicos por “infracción de la Constitución”. Y es que toda falta
política en que incurran los funcionarios que componen la estructura orgánica prevista en la Carta
Política, compromete peligrosamente el adecuado desenvolvimiento del aparato estatal. En estos
casos, la razón del despojo del cargo no tiene origen en la comisión de un delito, sino en la comisión
de faltas que aminoran, en grado sumo, la confianza depositada en el funcionario, la que debe ir
indefectiblemente ligada al cargo que ostenta".
De esta manera, en el juicio político el funcionario es acusado, procesado y, de ser el caso,
sancionado porel propio Congreso, porfaltas única y estrictamente políticas.
Función legislativa.-Comprende la iniciativaen laformación de las leyesy resolucio
