del Congreso.
El Congreso de la República puede delegar en el Poder Ejecutivo la facultad de legis
lar, mediante decretos legislativos, sobre materia específica y por el plazo determ i
nado establecidos en la ley autoritativa. El Presidente de la República da cuenta al
Congreso o a la Comisión Permanente de cada decreto legislativo.
