Tema 4: Teoría general de la Constitución
La Ley N° 319 8 8 , ha modificado 53 artículos de la Constitución, estas reformas constitucionales
entran en vigor a partir de las próximas elecciones generales (año 20261. con el retorno a la
bicameralidad, la reforma constitucional aprobada acorta la potestad excepcional del presi
dente de la República de disolver el poder legislativo contemplada en el actual artículo 134 de
la Constitución, sólo para la cámara de diputados. De esta manera, la Cámara de Senadores
no podrá ser disuelta.
Otra reforma constitucional aprobada es que ahora cuando, al inicio de su gestión, el primer
m inistroy el Consejo de Ministros comparezcan ante la Cámara de Diputados para exponer la
política general del gobierno,ya no plantearán una cuestión de confianza, actualmente deno
minada como "cuestión de confianza obligatoria".
b. Poder Ejecutivo
El Poder Ejecutivo es una de las tres facultades y funciones primordiales del Estado (junto
con la legislativa y la judicial) consistente en dictar y hacer cumplir las leyes que suele
aprobar el gobierno o el propio jefe del Estado.
El Presidente de la República es el Jefe de Estado y personifica a la nación. Al Presidente le
corresponde la conducción del Poder Ejecutivo.
Estructura del Poder Ejecutivo:
1. El Presidente de la República.- Es el Jefe de Estado, simboliza y personifica a la Na
ción. Es Jefe supremo de las Fuerzas Armadasy Policiales.
Para ser elegido Presidente de la República se requiere ser peruano por nacimiento,
tener más de treinta y cinco años de edad al momento de la postulación y gozar del
derecho de sufragio.
Competencia:
Le corresponde, la dirección política general de gobierno y de los diferentes organis
mos de la administración pública; representa al Estado dentro y fuera de la Repúbli
ca; dirige la política exterior; las relaciones internacionalesy la política de desarrollo
del país.
2. El Consejo de Ministros.- Organismo integrado por el Presidente más los Ministros
de Estado.
Es un organismo del Poder Ejecutivo con personería de derecho público inter
no, cuya principal función es apoyar al Presidente del Consejo de Ministros en el
cumplim iento de sus funciones.
Es el organismo coordinador intersectorial de la función política adm inistrati
va del Estado; en función de dicha política establece las coordinaciones con los
otros poderes del Estado, así como con los organismos autónomos y los niveles
de Gobierno Regional y Local.
Presidente del Consejo de Ministros:
Es la máxima autoridad política y administrativa de la Presidencia del Consejo de
Ministros. Es Ministro de Estado sin cartera.
