El Presidente del Consejo de Ministros establece los objetivos, formula y dirige
las políticas de carácter multisectorial, coordina los esfuerzos de las demás enti
dades de la administración pública en su respectivo ámbito de competencias y
supervisa la gestión de la Presidencia del Consejo de Ministros.
3. Ministerios.- Son organismos centrales del Poder Ejecutivo con personería de dere
cho público interno a cargo de los Ministros de Estado que conducen la gestión de
los asuntos públicos de su competencia de conformidad con la política general del
gobierno central.
Los Ministerios tienen funciones normativas, reguladoras, fiscalizadoras y de
ejecución.
Ministros:
Son los que formulan, dirigen, coordinan, determinan, ejecutan, supervisan y eva
lúan las políticas de los sectores a su cargo, y asumen la responsabilidad inherente a
dicha gestión en el marco de la política general del gobierno nacional.
4. Organismos Públicos.-Son entidades con personería jurídica de derecho público in
terno adscritas a un Ministerio, creadas para la realización de actividades específicas
de gestión especializada, con autonomía técnica, adm inistrativay funcional.
5. Organismos Reguladores (OSINERG, OSITRAN, OSIPTEL, SUNASS).- Son entida
des con personería jurídica de derecho público interno de alcance nacional que por
actuar en ámbitos especializados requieren de autonomía técnica, administrativa,
funcional, económica y financiera. Están adscritos a la Presidencia del Consejo de
Ministros.
Ejercen funciones de supervisión, regulación, normativa, fiscalizadoray sancio-
nadora, solución de controversias y solución de reclamos.
c. Poder Judicial
Es la potestad de administrar justicia y se ejerce a través de sus órganos jerárquicos con
arreglo a la Constitución.
Está integrado por:
- Organos Jurisdiccionales: Corte Suprema, Cortes Superiores, Juzgados de Paz Letra
dos, Juzgados de Pazy Juzgados Especializados Mixtos.
Órganos que ejercen su gobierno y administración: Presidente de la Corte Supre
ma, Sala Plena de la Corte Suprema, Consejo Ejecutivo, Gerencia general y el Consejo
Ejecutivo Distrital.
De conformidad con el artículo 139° de la Constitución, son principios y derechos de la
función jurisdiccional:
1. La unidady exclusividad de la función jurisdiccional. No existe ni puede establecerse juris
dicción alguna independiente, con excepción de la m ilita ry la arbitral. No hay proce
so judicial por comisión o delegación.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 61 of 1506 --

Tema 4: Teoría general de la Constitución
La unidad y exclusividad de la jurisdicción se entiende como la estructura organi-
zaday jerarquizada del Poder Judicial, en cuyo vértice se ubica la Corte Suprema de
Justicia (con competencia sobre todo el territorio de la República), las cortes supe
riores de justicia (en el ámbito territorial de los respectivos distritos judiciales), los
juzgados de primera instancia (cualquiera que sea su competencia por razón de la
materia), las capitales de las provincias, y los juzgados de paz letrados(con compe
tencia en la ciudad o población de su sede). Esta estructura también comprende a
los juzgados de paz, cuya elección, atribuciones, deberes, derechosy demás aspec
tos vinculados a esta institución, son regulados por ley especial - Ley N° 29824-Ley
de Justicia de Paz.
2. La independencia en el ejercicio de la función jurisdiccional. El Tribunal Constitucional en
la STC N.° 0023-2003-AI/TC señala que la Independencia judicial debe ser entendida
como aquella capacidad autodeterminativa para proceder a la declaración del de
recho, juzgando y haciendo ejecutar lo juzgado, dentro de los marcos que fijan la
Constitución y la ley. En puridad, se trata de una condición de albedrío funcional.
La independencia judicial debe, pues, percibirse como la ausencia de vínculos de su
jeción política o económica o de procedencia jerárquica al i nterior de la organización
que ejerce jurisdicción” (STC N° 0023-2003-AI/TC, F.J. 28,29,31 y 33; STC 0004-2006-
AI/TC).
3. La observancia del debido proceso y la tutela jurisdiccional. El Tribunal Constitucional ma
nifiesta que mientras la tutela judicial efectiva supone tanto el derecho de acceso a los
órganos de justicia como la eficacia de lo decidido en la sentencia; el derecho al debido
proceso, en cambio, significa la observancia de los derechos fundamentales esenciales
del procesado, principiosy reglas esenciales exigibles dentro del proceso como Instru
mento de tutela de los derechos subjetivos. (STC N.°08i23-2005-HC/TC, F.J.6).
4. La publicidad en los procesos, salvo disposición contraria de la ley.
5. La motivación escrita de las resoluciones judiciales en todas las instancias, excepto
los decretos de mero trámite, con mención expresa de la ley aplicabley de los funda
mentos de hecho en que se sustentan.
6 . La pluralidad de la instancia.
7. La indemnización, en la forma que determine la ley, por los errores judiciales en los
procesos penalesy por las detenciones arbitrarias, sin perjuicio de la responsabilidad
a que hubiere lugar.
8 . El principio de no dejar de administrar justicia por vacío o deficiencia de la ley. En tal
caso, deben aplicarse los principios generales del derecho y el derecho consuetudi
nario.
9. El principio de inaplicabiIidad por analogía de la ley penal y de las normas que res
trinjan derechos.
10. El principio de no ser penado sin proceso judicial.
n . La aplicación de la ley más favorable al procesado en caso de duda o de conflicto
entre leyes penales.
