d. Órganos constitucionales
La Constitución Política, para la salvaguardia del estado de derecho y la mayor eficiencia
en la ejecución de algunas labores, ha constituido algunos organismos autónomos, que
no dependen de ninguno de los poderes del Estado, estos son:
a. - TRIBUNAL CONSTITUCIONAL.
b. - JUNTA NACIONAL DEJUSTICIA.
c. - MINISTERIO PÚBLICO.
d. DEFENSORÍA DEL PUEBLO.
e. - JURADO NACIONAL DE ELECCIONES (JNE).
f. - OFICINA NACIONAL DE PROCESOS ELECTORALES (ONPE).
g. - REGISTRO NACIONAL DE IDENTIFICACIÓN Y ESTADO CIVIL (RENIEC).
