Tema 4: Teoría general de la Constitución
2.6. Debido proceso
El numeral 3 del Art. 139o de la Constitución precisa que el debido proceso constituye un prin-
cipiode la función jurisdiccional. Porotro lado, ladoctrinayjurisprudencia nacional sostienen
que el debido proceso no solo constituye un principio aplicable a quienes ejercen función ju
risdiccional, sino también un derecho fundamental. En esa medida, el debido proceso com
parte el doble carácter de los derechos fundamentales. Por un lado, constituye un derecho
subjetivo, que resulta exigióle por todas las personas; y por otra parte, un derecho objetivo,
dado que contiene una dimensión institucional que lleva implícito los fines sociales y colec
tivos de justicia.
El Tribunal Constitucional ha señalado a través de su jurisprudencia que el debido proceso
constituye “la observancia de los derechos fundamentales esenciales del procesado, principios y reglas
esenciales exigibles dentro del proceso como instrumento de tutela de los derechos subjetivos”11, a lo que
se puede añadir además, que dicho derecho12 “está concebido como el cumplimiento de todas las
garantíasy normas de orden público que deben aplicarse a todos los casosy procedimientos, incluidos los
administrativos”. En conclusión, se puede señalar que el derecho al debido proceso es aquel
que garantiza la tutela de derechos fundamentales dentro de un proceso que busca dar so
lución a una controversia de naturaleza jurídica.
2.7. Alcances y contenido del debido proceso formal y material
En el derecho comparado se clasifica al debido proceso en dos tipos, el debido proceso formal
o procesal y el debido proceso sustantivo o sustancial, siendo el primero de mayor utilización,
de tal forma que cuando se utiliza el term ino debido proceso se hace referencia normalmente
a su faceta procesal es decir al debido proceso formal, dándose ambas manifestaciones del
debido proceso o proceso justo en el sistema jurídico estadounidense.
El Tribunal Constitucional también ha desarrollado las manifestaciones del debido proceso al
señalar que “el debido proceso tiene, a su vez, dos expresiones: una formal y otra sustantiva; en la de ca
rácter form al, los principios y realas que lo integran tienen que ver con las formalidades estatuidas, tales
como las que establecen el juez natural, el procedimiento preestablecido, el derecho de defensa, la
motivación; en su faz sustantiva, se relaciona con los estándares de justicia como son la razonabilidad
y proporcionalidad que toda decisión judicial debe suponer (STC Exp. N° 00023-2005''PI/TC-Lima.
Fj. 48).
2.8. Debido proceso formal o procesal
El Debido Proceso Adjetivo es un derecho complejo de carácter procesal y que está confor
mado por un conjunto de derechos esenciales que impiden que la libertady los derechos de
los individuos sucumban ante la ausencia o insuficiencia de un proceso o procedimiento o
se vean afectados por cualquier sujeto de derecho que pretenda hacer uso abusivo de estos.
11 STC Exp. N.° 9727-2005-PHC/TC. FJ. 7.
12 STC Exp. N.° 067-93-AA/TC. Citado por: Chiabra Valera, María Christina. El debido proceso legal y la tutela jurisdic
cional efectiva: más similitudes que diferencias. Revista de Derecho Toro Jurídico” N ° v . Editada por Foro Académi
co Asociación Civil. Diciembre 2010. p. 72.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 64 of 1506 --

UBILEX
Abarcará por ello, tanto el derecho al proceso (entendido como la posibilidad de accederá un
proceso o procedimiento con la finalidad de que el órgano competente se pronuncie sobre su
pretensión y le brinde tutela efectivay diferenciada), como el derecho en el proceso (conjunto
de derechos con que cuenta todo sujeto de derecho que participa en un proceso o procedi
m ie n to ^ que será durante su inicio, tramitación y conclusión).
2.8.1. Contenido
En su dimensión adjetiva o formal, el debido proceso está comprendido por determinados ele
mentos procesales mínimos que son necesarios e imprescindibles para el establecimiento de un
proceso justo, tales como el derecho de defensa, el derecho a probar, derecho a un juez imparcial,
el derecho a impugnar, ser escuchado, entre otros. A su vez, estos elementos impiden que la li
bertad y los derechos de los individuos se afecten ante la ausencia o insuficiencia de un proceso.
Por esta razón, diversos autores coinciden en señalar que la dimensión procesal del derecho al
debido proceso es un derecho continente dentro del cual se hallan una serie de derechos de
manera ilimitada.
2.9. Debido proceso material o sustancial
El debido proceso sustantivo exige, porsu parte, que los actos tanto del legislador, del juezy de
la administración sean razonables y respetuosos de los derechos fundamentales, a tal punto
que su inobservancia debe sersancionada con la inaplicación de aquel acto o con su invalidez.
En el proceso judicial, esta labor se posibilita a través del control difuso que realiza el juez, lo
que implica que el juzgador puede declarar ineficaz la ley e inaplicaria para un caso concreto.
Por ello el debido proceso sustancial tiene por fin asegurar la razonabilidad de lo decidido en
un proceso.
3. GARANTÍAS INSTITUCIONALES Y PROCESALES
3.1. Garantías institucionales
Las “garantías institucionales” son aquellas que la Constitución consagra para que ciertas or
ganizaciones o instituciones puedan cumplir con sus funciones propias, frente a injerencias
externas. Por ejemplo, es el caso de la autonomía de las Universidades, la independencia del
Poder ludicial, etc.
3.2. Garantías procesales
Garantías Procesales son las seguridades que se otorgan para impedir que el goce efectivo de
los derechos fundamentales sea conculcado por el ejercicio del poder estatal, ya sea lim itan
do ese poder o repel iendo el uso.
Las garantías procesales son reconocidas en todo tipo de proceso jurisdiccional y administrativo,
recibiendo diferentes nombres dependiendo del tipo de proceso, por ejemplo: garantías del pro
ceso civil, garantías del proceso penal, garantías del proceso constitucional; algunos le adicionan
el término “constitucionales” denominándolas como garantías constitucionales del proceso civil,
penal, etc.; en relación al Nuevo Código Procesal Constitucional, suelen ser mencionadas como
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 65 of 1506 --

T-sjto -í1: Teoría general de la Constitución
“procesos constitucionales”. Constituyendo todas las garantías procesales independientemente
de las especialidadesy el ordenamiento procesal, seguridades o mecanismos para que los dere
chos fundamentales sean igualmente tutelados en todo proceso judicial o administrativo.
La mayoría de las Constituciones de Latinoamérica han incorporado un conjunto de garan
tías genéricas y una extensa relación de garantías específicas. Como Garantías genéricas se
consideran: el derecho a la tutela jurisdiccional, la presunción de inocencia, el derecho a la
defensa, y el debido proceso. Estas refuerzan e incluso dan origen a las Garantías específicas
como: El juez natural, publicidad, pluralidad de instancia, cosa juzgada, etc. existiendo una
interrelación entre ellas.
En nuestro país las garantías procesales encuentran sustento y protección constitucional en
el artículo 139 de la Constitución Política de 1993 consignándolas como “Principios y Derechos
de la Función jurisdiccional” contemplando 22 garantías procesales, de las cuales las ocho pri
meras y la décimo sexta, son de aplicación general a todo tipo de proceso como es el caso de
los procesos civiles; y del inciso noveno al veintidós están referidos en estricto al proceso pe
nal. Esta norma constitucional garantiza derechos procesales como el debido proceso, tutela
jurisdiccional efectiva, la cosa juzgada, motivación de resoluciones judiciales, pluralidad de
instancia, derecho de defensa, gratuidad de la justicia entre otros; cuya finalidad se orienta a
la protección constitucional de las garantías a observar en los procesos judiciales.
Las garantías procesales generales son las siguientes:
1. La unidad y exclusividad de la función jurisdiccional. No existe ni puede establecerse ju
risdicción alguna independiente, con excepción de la m ilita ry la arbitral. No hay proceso
judicial por comisión o delegación.
2. La independencia en el ejercicio de la función jurisdiccional. Ninguna autoridad puede
avocarse a causas pendientes ante el órgano jurisdiccional ni interferir en el ejercicio de
sus funciones. Tampoco puede dejarsin efecto resoluciones que han pasado en autoridad
de cosa juzgada, ni cortar procedimientos en trámite, ni modificar sentencias ni retardar
su ejecución. Estas disposiciones no afectan el derecho de gracia ni la facultad de investi
gación del Congreso, cuyo ejercicio no debe, sin embargo, interferir en el procedimiento
jurisdiccional ni surte efecto jurisdiccional alguno.
3. La observancia del debido proceso y la tutela jurisdiccional. Ninguna persona puede ser
desviada de la jurisdicción predeterminada por la ley, ni sometida a procedimiento dis
tinto de los previamente establecidos, ni juzgada por órganos jurisdiccionales de excep
ción ni por comisiones especiales creadas al efecto, cualquiera sea su denominación.
4. La publicidad en los procesos, salvo disposición contraria de la ley. Los procesos judiciales
por responsabilidad de funcionarios públicos,y por los delitos cometidos por medio de la
prensa y los que se refieren a derechos fundamentales garantizados por la Constitución,
son siempre públicos.
5. La motivación escrita de las resoluciones judiciales en todas las instancias, excepto los
decretos de mero trámite, con mención expresa de la ley aplicable y de los fundamentos
de hecho en que se sustentan.
6 . La pluralidad de la instancia.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 66 of 1506 --

UBILEX
7. La indemnización, en la forma que determine la ley, por los errores judiciales en los pro
cesos penales y por las detenciones arbitrarias, sin perjuicio de la responsabilidad a que
hubiere lugar.
8 . El principio de no dejar de administrar justicia por vacío o deficiencia de la ley. En tal caso,
deben aplicarse los principios generales del derechoy el derecho consuetudinario.
Definimos las principales garantías procesales:
La unidad y exclusividad de la función jurisdiccional
Unidad de la función jurisdiccional
Principio reconocido por el inciso 1 del artículo 139o de la Constitución, que prescribe que: “No
existe ni puede establecerse jurisdicción alguna independiente, con excepción de lo arbitral y
lo militar. No hay proceso judicial por comisión o delegación”.
El principio de unidad permite que la función jurisdiccional sea ejercida por una entidad “uni
taria”, a efectos de asegurar el cumplimiento del principio de igualdad ante la ley, previsto en
el inciso 2 del artículo 2° de la Constitución; y, con ello, que todos los justiciables se encuen
tren, en principio y como regla general, sometidos a los mismos tribunales, sin que se consi
dere constitucional la existencia de fueros especiales o de privilegio en “razón” de la mera e
inadmisible diferenciación de las personas o de cualquier otra consideración absurda.
En la sentencia recaída en la SCT Exp. N° oiy-2003-Al/TC, el Tribunal Constitucional sostuvo
que el principio de unidad de la función jurisdiccional: “(...) se sustenta en Ia naturaleza indivisi
ble de la jurisdicción, como expresión de la soberanía. Según ésta, la plena justiciabllidad de todas las
situaciones jurídicamente relevantes han de estar confiadas a un único cuerpo de jueces y magistrados,
organizados por instancias, e independientes entre sí, denominado Poder Judicial
Sin embargo, el principio de unidad no obsta que el legislador pueda establecer, al interior
del Poder Judicial, juzgados especializados; siempre que dichos órganos intrajurisdiccionales
aseguren al justiciable todas las garantías vinculadas al debido proceso y a la tutela judicial
efectiva.
Exclusividad de la función jurisdiccional
Este principio está previsto por el inciso 1 del art. 139o de la Constitución, que preceptúa que
son principios y derechos de la función jurisdiccional la unidady la exclusividad de la función
jurisdiccional, considerando excepcionalmente a la jurisdicción m ilitar y arbitral indepen
diente. Si bien el mencionado inciso de la Constitución ha considerado excepcionalmente a
la jurisdicción m ilitar como una jurisdicción independiente, ello no autoriza a que ésta diseñe
y autorice el ejercicio de sus atribuciones con inobservancia de los principios constitucionales
que informan la actividad de todo órgano que administra justicia, tales como el de indepen
dencia e imparcialidad de la función jurisdiccional, así como el de la garantía de inamovilidad
de los jueces.
Conceptualmente, la exclusividad se concibe como la prohibición constitucional al legislador,
de que atribuya la potestad jurisdiccional a órganos no conformantes del Poder Judicial.
66 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 67 of 1506 --

Tamil 4: Teoría general de la Constitución
El principio de exclusividad ostenta un doble sentido13.
Sentido positivo es el resultado de la confluencia de los principios de separación de poderes
(artículo 43° de la Constitución) y de tutela judicial efectiva (inciso 3 del artículo 139o de la
Constitución).
Sentido negativo, excluye a la potestad jurisdiccional de otros cometidos públicos distintos a
ladirim enciade los conflictos jurídicos en sede judicial.
Debido Proceso
El debido proceso, goza de protección constitucional en el art. 139 de nuestra Carta Magna,
así como en los artículos 8 de la Convención Americana de los Derechos del Hombre y artí
culo 14 del Pacto Internacional de Derechos Civiles y Políticos, alcanzando interpretación de
la Corte Interamericana de los Derechos Humanos, en el sentido de su carácter indispensa
ble e imprescindible en la administración de justiciay para la obtención de decisiones justas,
asentando que el debido proceso es un derecho fundamental que sirve de instrumento para
alcanzar justicia, que es un derecho humano el obtener todas las garantías que permitan al
canzar decisiones justas (Caso Baena Ricardo Sentencia del zde febrero del 2001 párrafo 127);
en relación a las garantías judiciales previstas en el art. 8 de la Convención Americana de De
rechos Humanos ha interpretado que estas suponen que cualquier autoridad Pública incluso
judicial, debe respetar al em itir sus resoluciones que determinen derechos y obligaciones de
las personas, las garantías establecidas en la Convención (Caso Las Palmeras Sentencia de fe
cha 6 de diciembre del 2001).
El Tribunal Constitucional establece “el derecho al debido proceso previsto por el artículo
139.3o de la Constitución Política del Perú, aplicable no sólo a nivel judicial sino también en
sede administrativa e incluso entre particulares, supone el cumplimiento de todas las garan
tías, requisitos y normas de orden público que deben observarse en las instancias procesa
les de todos los procedimientos, incluidos los administrativos y conflictos entre privados,
a fin de que las personas estén en condiciones de defender adecuadamente sus derechos
ante cualquier acto que pueda afectarlos. (SCI Exp. N.° 04944-201i-PA/TC- Lima). Como ya
se mencionó el debido proceso, como tal, presenta dos expresiones: la formal y la sustantiva;
en la de carácter formal, los principiosy reglas que lo integran tiene que ver con las formali
dades estatuidas, tales como las que establecen el juez natural, el procedimiento preestable
cido, el derecho de defensa y la motivación; y en su expresión sustantiva, están relacionados
los estándares de razonabilidad y proporcionalidad que toda decisión debe suponer.
Derecho a la Tutela Jurisdiccional:
Está reconocido en nuestro ordenamiento constitucional en el art. 139o, inciso 3, donde si bien
aparece como “principioy derecho de la función jurisdiccional”, es claro tanto para la doctrina
unánime como para la propia jurisprudencia del TC, que se trata de un derecho constitucional
que en su vertiente subjetiva.13
13 Manual del Sistema Peruano de Justicia. Lima: Instituto de Defensa Legal, Pontificia Universidad Católica del Perú
y jueces para la ju sticiay Democracia, 2003.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 68 of 1506 --

UBILEX
Según el Tribunal Constitucional "La tutela judicial efectiva es un derecho constitucional de natura
leza procesal en virtud del cual toda persona o sujeto justiciable puede accederá los órganos jurisdic
cionales, independientemente del tipo de pretensión formulada y de la eventual legitim idad que pueda
o no, acompañarle a su petitorio. En un sentido extensivo la tutela judicial efectiva permite también
que lo que ha sido decidido judicialmente m ediante una sentencia, resulte eficazmente cumplido. En
otras palabras, con la tutela judicial efectiva no sólo se persigue asegurar la participación o acceso del
justiciable a los diversos mecanismos (procesos) que habilita el ordenamiento dentro de los supuestos
establecidos para cada tipo de pretensión, sino que se busca g a rantizar que, tras el resultado obtenido,
pueda verse este últim o m aterializado con una mínima y sensata dosis de eficacia". STC Exp. N° 763-
2005''PA/TC-Lima
Así tenemos que la tutela jurisdiccional efectiva no se lim ita a garantizar el acceso a la justicia,
su ámbito de aplicación es mucho más amplio, pues garantiza obtener un pronunciamiento
sobre el fondo de las pretensiones que se deducen en un proceso.
Sin embargo, al considerar el Tribunal Constitucional que es derecho de todo justiciable poder
acceder a la jurisdicción, como manifestación de la tutela judicial efectiva no implica la obli
gación de estimar favorablemente toda pretensión formulada, sino que simplemente sienta
la obligación de acogerla y brindarle una sensata como razonada ponderación en torno a su
procedencia o legitimidad.
Presunción de Inocencia:
En el Sistema Internacional de Protección de los Derechos Humanos, el derecho a la presun
ción de inocencia aparece considerado en el art. 11.1 de la Declaración Universal de los Dere
chos Humanos, en el sentido de que “Toda persona acusada de delito tiene derecho a que se
presuma su Inocencia mientras no se pruebe su culpabilidad, conforme a la ley y en juicio pú
blico en el que se le hayan asegurado todas las garantías necesarias para su defensa. (...)”. De
igual modo, el citado derecho es enfocado en el artículo 14.2 del Pacto Internacional de Dere
chos Civiles y Políticos y el artículo 8.2 de la Convención Americana sobre Derechos Humanos.
En relación con esta última, “(...) la Corte ha afirmado que en el principio de presunción de ino
cencia subyace el propósito de las garantías judiciales, al afirmar la idea de que una persona es
inocente hasta que su culpabilidad es demostrada”. En concordancia con estos instrumentos
internacionales de protección de los derechos humanos, el art. 2, inciso 24 de nuestra Cons
titución establece que “Toda persona es considerada inocente mientras no se haya declarado
judicialmente su responsabilidad”. De esta manera, el constituyente ha reconocido la presun
ción de inocencia como un derecho fundamental.
Según el Tribunal Constitucional el derecho fundamental a la presunción de inocencia es:
a) Un derecho fundamental y una presunción iuris ta n tu m , en tanto que ¡mplicaque al pro
cesado se le considera ¡nocente mientras no se pruebe su culpabilidad: vale decir, hasta
que no se exhiba prueba en contrario. Rige desde el momento en que se imputa a alguien
la comisión de un delito, quedando el acusado en condición de sospechoso durante toda
la tramitación del proceso, hasta que se expida la sentencia definitiva. (STC 0618-2005-
PHC/TC, FF.]J. 21 y 22).
