Tema 4: Teoría general de la Constitución
b) Puede ser desvirtuada en función a ia actividad probatoria en el marco de un proceso
penal. La presunción de inocencia se mantiene ''viva'' en el proceso penal siempre que no
exista una sentencia judicial que, como corolario del cauce investigativo llevado a cabo
con las garantías inherentes al debido proceso, logre desvirtuarla14. Comprende el prin
cipio de libre valoración de la prueba en el proceso penal que corresponde actuar a los
Jueces y Tribunales; que la sentencia condenatoria se fundamente en auténticos hechos
de prueba, y que la actividad probatoria sea suficiente para generar en el Tribunal la evi
dencia de la existencia no sólo del hecho punible, sino también la responsabilidad penal
que en él tuvo el acusado y así desvirtuar la presunción. (STC0618-2005-PHC/TC, FJ 22).
c) Su carácter de relativo justifica la imposición de medidas cautelares personales al im
putado. “El derecho fundamental a la presunción de inocencia no es un derecho absoluto
sino relativo. De ahí que, en nuestro ordenamiento, se admitan determinadas medidas
cautelares personales-com o la detención preventiva o detención provisional-, sin que
ello signifique su afectación, porque tales medidas sirven precisamente para esclarecer
el hecho reprochado y por ello son imprescindibles para llevar a cabo un procedimiento
penal orientado en principios propios de un Estado de derecho; siempre, claro está, que
tales medidas sean dictadas bajo criterios de razonabilidady proporcionalidad. Parte de
esa relatividad del derecho a la presunción de inocencia se vincula también con que dicho
derecho incorpora una presunción iuris tantum y no una presunción absoluta; de lo cual
se deriva, como lógica consecuencia, que la presunción de inocencia puede ser desvir
tuada o destruida mediante una mínima actividad probatoria”. (STC Exp. N° 10107-2005-
PHC/TC. FJ 07).
d) Su relación con el ¡n dubio pro reo. El principio in dubio pro reo no es un derecho subjetivo,
sino un principio de jerarquía constitucional cuyo fin es garantizar el cabal respeto del de
recho fundamental a la libertad individual, bien para resguardar su plena vigencia, bien
para restringirlo de la forma menos gravosa posible, en el correcto entendido de que tal
restricción es siempre la excepción y nunca la regla. (STC Exp. N°i994-2002-PHC/TC).
Derecho de Defensa:
La Convención Americana de Derechos Humanos dispone, en el apartado b) del inciso z del
art. 8 o, se establece que “Durante el proceso, toda persona tiene derecho, en plena igualdad, a una
comunicación previa y detallada de la acusación formulada". En esa línea, los apartados a) y b) del
párrafo 3 del artículo 14 del Pacto Internacional de Derechos Civilesy Políticos establecen que
durante el proceso toda persona acusada de un delito tendrá derecho, en plena igualdad, a
ser informada sin demora, en un idioma que comprenda y en forma detallada, de la natura-
lezay las causas de la acusación formulada contra ella; a disponer del tiem poy de los medios
adecuados para la preparación de su defensay a comunicarse con un defensor de su elección.
Nuestra Constitución reconoce el derecho a la defensa en el inciso 14), art. 139o, establecien
do: “El principio de no ser privado del derecho de defensa en ningún estado del proceso. Toda persona
será informada inmediatamente y por escrito de la causa o las razones de su detención. Tiene derecho a
comunicarse personalmente con un defensor de su elección y a ser asesorada por éste desde que es citada
14 STC Exp. N.° 2915-2004-PHC/TC. F] 12.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 70 of 1506 --

UBILEX
o detenida por cualquier autoridad”. Así, en virtud de dicho derecho se garantiza que los justicia
bles, en la protección de sus derechos y obligaciones, cualquiera que sea su naturaleza (civil,
mercantil, penal, laboral, etc.), no queden en estado de indefensión.
Por su parte, el artículo IX del Título Preliminar del Nuevo Código Procesal Penal, establece
que: “Toda persona tiene derecho inviolable e irrestricto a que se le informe desús derechos, a
que se le comunique de inmediato y detalladamente la imputación formulada en su contray
a ser asistida por un Abogado Defensor de su elección o, en su caso por un abogado de oficio,
desde que es citada o detenida por la autoridad”
El contenido constitucionalmente protegido del derecho de defensa queda afectado cuan
do, en el seno de un proceso judicial, cualquiera de las partes resulta impedida, por concre
tos actos de los órganos judiciales, de ejercer los medios necesarios, suficientes y eficaces
para defender sus derechos e intereses legítimos.
Según el Tribunal Constitucional de lo dispuesto por nuestra Constitución (Art. 139 inciso 14)
se establece-, "de la lectura de dicho artículo se desprende una doble obligación por parte de los órganos
judiciales. La prim era se plasma en la obligatoriedad de que toda persona sea inform ada inm ediata,
adecuadamente y por escrito de la causa o las razones de su detención, así como de los fundam entos
jurídico-fácticos por los cuales se le em ite auto de enjuiciam iento y se le procesa. Solo de esta manera
puede garantizarse que el acusado pueda estructurary planificar su defensa en forma efectiva para po
der afrontar el debate contradictorio. La segunda exigencia se plasma en el derecho de todo justiciable
de comunicarse personalm ente con un defensor de su elección y a ser asesorado por éste desde que es
citado o detenido por cualquier autoridad, con lo que se garantiza que la persona tenga pleno conoci
miento de los aspectos jurídicos que conforman el principio acusatorio y que pueda organizar eficientey
oportunamente su defensa”. STC Exp. N° 04587-2009''PA/TC-Lima.
Manifestaciones del Derecho de Defensa:
a) Derecho a ser informado de la imputación o de ser el caso, de la acusación:
i. Contenido de la información: Esta información debe comprendertanto la naturaleza
de la imputación formulada en contra de la persona así como la causa de dicha acu
sación.
ii. Oportunidad de la información.
b) Derecho al tiempo y a las facilidades necesarias para la defensa: De ahí que, el conte
nido esencial del derecho de defensa queda afectado cuando, en el seno de un proceso
judicial, cualquiera de las partes resulta impedido, por concretos actos de los órganos
judiciales, de hacer uso de los medios necesarios, suficientes y eficaces para ejercer la
defensa de sus derechos e intereses legítimos.
c) Derecho a contar con asistencia pública.
Motivación debida de las resoluciones
En la jurisprudencia nacional, el Tribunal Constitucional y las respectivas instancias judiciales
han reconocido la debida motivación como elemento de un debido proceso, y que como tal,
debe estar presente en todo tipo de proceso o de procedimiento. Así, el Tribunal Constitu
cional peruano se ha pronunciado en el siguiente sentido: el contenido constitucionalmente
70 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 71 of 1506 --

Tema 4: Teoría general de la Constitución
protegido del derecho fundamental al debido proceso está comprendido el derecho a la m oti
vación de las resoluciones. Si se interpreta restrictivamente el artículo 139°, incisos de la Cons
titución, el cual prevé que: “[s]on principiosy derechos de la función jurisdiccional (.. J5. La motivación
escrita de las resoluciones judiciales en todas las instancias, excepto los decretos de mero trámite, con
mención expresa de la ley aplicabley de los fundamentos de hecho en que se sustentan (...)" (STC Exp. N°
4002-2006-PA/TC). Por otro lado, la Sala Civil Transitoria de la Corte Suprema de la República
ha declarado textualmente lo siguiente: “Tercero.-Que, conforme a lo establecido en el inciso cuarto
del artículo ciento veintidós del Código Procesal Civil, toda resolución debe contener la expresión clara
y precisa de lo que se decide u ordena, respecto de todos los puntos controvertidos; Cuarto- Que, dicho
mandato guarda consonancia con la exigencia constitucional de la motivación, entendiéndose que esta
constituye un elemento eminentemente intelectual, que expresa el análisis crítico y valorativo llevado a
cabo por el juzgador, expresado conforme a las reglas de la logicidady comprende tanto el razonamiento
de hecho como el de derecho en los cuales el juzgador apoya su decisión”. (Cas. N° 1102-2000-lamba-
yeque).
La motivación de las sentencias es vinculada como derecho fundamental a la tutela judicial
efectiva, que implica, el derecho del justiciable de conocer las razones de las decisiones ju d i
ciales; y dentro de ésta la conecta con el derecho a obtener una resolución fundada en dere
cho. Así, según el Tribunal Constitucional: “La motivación debida de las decisiones de las entidades
públicas-sean o no de carácter jurisdiccional- es un derecho fundamental que forma parte del conte
nido esencial del derecho a la tutela procesal efectiva. El derecho a la motivación debida constituye una
garantía fundamental en los supuestos en que con la decisión emitida se afecta de manera negativa la
esfera o situación jurídica de las personas. Así, toda decisión que carezca de una motivación adecuada,
suficiente y congruente, constituirá una decisión arbitraria y, en consecuencia, será inconstitucional”.
(STC Exp. N° 04944-2011-PA/TC-Lima).
4. ESTADOS DE EXCEPCIÓN
Son mecanismos constitucionales que permiten poneren suspenso la vigencia de ciertos de
rechos fundamentales y cuya causa radica en la existencia de factores internos o externos
que ponen en grave riesgo la integridad del Estado y que tiene como finalidad restaurar en
tre otras cosas la seguridad del Estado.
El Congreso es el órgano encargado de evaluar si la declaración del estado de excepción es
una necesidad; es decir si las medidas tomadas son indispensables para asegurar el restable
cimiento del orden público, la seguridad nacional y la normalidad.
Este régimen procura mantener la estabilidad de un régimen constitucional ante una situa
ción de desborde y violencia que afecta la vida de los ciudadanos y de la nación en general. Se
acude al régimen de excepción, en tanto las medidas y restricciones autorizadas en tiempo
ordinario son claramente insuficientes para mantener el orden público.
Su finalidad es defender la perdurabilidady cabal funcionamiento de la organización político
jurídico.
Conforme a la Constitución (Art.137) los estados de excepción son dos: el estado de emergen-
ciay el estado de sitio. El primero se decreta ante los supuestos de alteración de la paz o del
