Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 72 of 1506 --

UBILEX
orden interno, de catástrofe o graves circunstancias que afecten la vida de la Nación. El se
gundo se establece en caso de invasión, guerra exterior, guerra civil o peligro inminente de
la producción de éstas. Ambos regímenes son decretados por el Presidente de la República,
con aprobación del Consejo de Ministros.
4.1. Estado de emergencia
i. Los supuestos que lo habilitan son:
Perturbación de la paz o del orden interno.
Catástrofe o graves circunstancias que afecten la vida de la nación.
¡i. Es una medida transitoria, es decir, tiene que tener un plazo determinado, pues el men
cionado dispositivo constitucional establece que la situación no debe de exceder de 6o
días. Ante la necesidad de prórroga, es necesaria la emisión de un nuevo decreto.
iii. Sólo posibilita la restricción de cuatro derechos amparados en nuestra Constitución.-
Derecho a la libertady seguridad personales.
Inviolabilidad de domicilio.
Libertad de tránsito.
Libertad de reunión.
iv. No es obligatorio que las Fuerzas Armadas asuman el control del orden interno del país,
ya que esta decisión queda a elección del Presidente.
En el rol que deben cumplir las Fuerzas Armadas durante el estado de emergencia, éstos
están sujetos a los principios de razonabilidad y proporcionalidad en el ejercicio de sus
facultades. Asimismo, es necesario que el Ejecutivo (en la persona del Presidente de la
República), establezca las directivas y planes que desarrollarán las fuerzas del orden, a
fin que sus funciones estén debidamente delimitadas, según la disposición que indica los
supuestos por los que se decreta el estado de emergencia.
v. Control jurisdiccional, expresado en la verificación jurídica de la aplicación de los princi
pios de razonabilidady proporcionalidad del acto restrictivo o suspensivo de los derechos
fundamentales de la persona, y en el cumplim iento del íter procedimental exigido por
la Constitución para establecer su decretamiento; así como en el uso del control político
parlamentario para que se cumplan los principios de rendición de cuentas y de responsa
bilidad política.
4.2. Estado de sitio
El Estado de Sitio se declara cuando se presentan circunstancias más graves que las que per
miten en declarar el Estado de Emergencia. Así, en el Art. 137-2 de la Constitución, se señala
que el Estado de Sitio se puede decretar en caso de invasión, guerra exterior, guerra civil, o
peligro inminente de que se produzcan.
Es declarado por el Presidente de la República, con acuerdo del Consejo de Ministros,y el pla
zo de su instauración no puede exceder de 45 días (Art. 137.2 de la Constitución).
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 73 of 1506 --

Tema 4: Teoría general de la Constitución
El Estado de Sitio se puede prorrogar, se entiende, si se mantiene las circunstancias que m oti
varon su declaración. Sin embargo, en aplicación de lo prescrito en la parte final del Art. 137 de
la Constitución, su prórroga no se hace con un nuevo Decreto del Ejecutivo, como se hace para
el caso de prórroga del Estado de Emergencia, sino que se tendrá que aprobar por el Congreso,
el cual, al decretarse el Estado de Sitio, debe reunirse de pleno derecho.
5. INTERPRETACIÓN CONSTITUCIONAL
Según García Toma, se denomina así al proceso mediante el cual se determina o se asigna
un sentido a las normas contenidas en el texto fundam ental. El papel de los intérpretes
constitucionales consiste en declarar el significado y alcance de las normas constituciona
les. Tal declaración se efectúa cuando, al percibirse in totum los fenómenos políticos y ju
rídicos que integran la norma que es objeto de interpretación, se elige aquel sentido que
mejor se adecúe a los valores y fines que por esa norma se intenta consagrar en el seno de
la sociedad política.
"fija interpretación constitucional es [...] una labor de «concretizaclón» y también de intermedia
ción entre el momento constituyente y el momento de aplicación de las disposiciones consti
tucionales. No hay interpretación fuera del tiempo. El contexto y sus múltiples manifestaciones
dansentido y objetividad a la interpretación, que esantetodo una actividad humana que partiem
do del texto de la Constitución, debe sin embargo ser capaz de incorporar otros elementos de la
vida cultural, social y anímica del momento en que la sociedad, a través [sic] del proceso, solicita
la «ejecución>■dé determinada cláusula constitucional". (STC 4853-2004-PA-TC).
5.1. Principios de interpretación constitucional
Los métodos de interpretación constitucional no se agotan en aquellos criterios clásicos de in
terpretación normativa (literal, teleológico, sistemático e histórico), sino que abarquen, entre
otros elementos, una serie de principios que informan la labor hermenéutica del juez consti
tucional. Tales principios son (STC Exp. N °5854- 2005-PA/TC- Piura. Fj. 12):
a) El principio de unidad de la Constitución: Conforme al cual la interpretación de la Constitución
debe estar orientada a considerarla como un “todo” armónico y sistemático, a partir del
cual se organiza el sistema jurídico en su conjunto.
b) El principio de concordancia práctica: En virtud del cual toda aparente tensión entre las pro
pias disposiciones constitucionales debe ser resuelta “optimizando" su interpretación, es
decir, sin “sacrificar” ninguno de los valores, derechos o principios concernidos, y teniendo
presente que, en últim a instancia, todo precepto constitucional, incluso aquellos perte
necientes a la denominada “Constitución orgánica” se encuentran reconducidos a la pro
tección de los derechos fundamentales, como manifestaciones del principio-derecho de
dignidad humana, cuya defensa y respeto es el fin supremo de la sociedad y el Estado
(artículo i° de la Constitución).
c) El principio de corrección funcional: Este principio exige al juez constitucional que, al realizar
su labor de interpretación, no desvirtúe las funciones y competencias que el Constituyen
te ha asignado a cada uno de los órganos constitucionales, de modo tal que el equilibrio
inherente al Estado Constitucional, como presupuesto del respeto de los derechos funda
mentales, se encuentre plenamente garantizado.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 74 of 1506 --

UBILEX
d) El principio de función in te g ra d o s: El “producto” de la Interpretación sólo podrá ser conside
rado como válido en la medida que contribuya a integrar, pacificary ordenar las relacio
nes de los poderes públicos entre síy las de éstos con la sociedad.
e) El principio de fuerza normativa de la Constitución: La interpretación constitucional debe
encontrarse orientada a relevary respetar la naturaleza de la Constitución como norma
jurídica, vinculante in to to y no sólo parcialmente. Esta vinculación alcanza a todo poder
público (incluyendo, desde luego, a este Tribunal) y a la sociedad en su conjunto.
El tema de la interpretación constitucional comprende a su vez la interpretación de la Cons
titución, la interpretación constitucional de la ley y la interpretación de los derechos funda
mentales.
L Interpretación de la Constitución
Consiste en asignar un sentido a la Constitución, a efectos de coadyuvar a su correcta aplica
ción a la realidad. Esta asignación requiere que previamente se precisey determine la existen
cia de los valores y principios constitucionales existentes en su seno.
B. Interpretación Constitucional de la Ley
En la interpretación de la ley conforme a las normas constitucionales, el intérprete debe apli
car todos los métodos de interpretación al texto analizado (literal, ratio legis, etc.), asignarle
todos los significados que obtenga, confrontar estos significados con los preceptos y princi
pios constitucionales, y finalmente elegir, entre esos significados, aquél que guarde mayor
conformidad con las normas constitucionales.
En la interpretación constitucional confluyen dos momentos interpretativos: el de la inter
pretación de la norma canon de control, es decir, el de la interpretación de la Constitución y
el de la interpretación de la ley conforme a los sentidos interpretativos encontrados en la
interpretación de la Constitución. Este segundo momento de la interpretación constitucional
se encuentra, al igual que el primero, conformado por un proceso particular y sujeto a deter
minados principios que el TC peruano se ha encargado de explicitar.
La interpretación constitucional de la ley, adquiere particular relieve cuando la interpretación
arroja alternativa o conjuntamente uno o más contenidos inconstitucionales. Ante esta situa
ción y de acuerdo al [s/''c] principio de conservación de la ley es que el Tribunal ha desarrollado
lo que en la experiencia comparada se ha dado en llamar «interpretación conforme», di recta
mente conectado con el tema de las sentencias interpretativas.
El TC explica así el proceso de interpretación constitucional de la ley y el de interpretación
conforme:
El sustento conceptual de la interpretación conforme: la distinción entre “disposición” y “nor
m a”. (STC N°Exp. ooio-zooz-A I/T C )
El Tribunal Constitucional, ha precisado que en todo precepto legal se puede distinguir
entre «disposición» y «norma», entendiendo por la primera aquel texto, enunciado lin
güístico o conjunto de palabras que integran el precepto,y por la segunda, aquel o aque
llos sentidos interpretativos que se pueden deducir de la disposición o de parte de ella.
Esta distinción no implica que ambas puedan tener una existencia independiente, pues
se encuentran en una relación de mutua dependencia, no pudiendo existir una norma
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 75 of 1506 --

Tema 4: Teoría general de la Constitución
que no encuentre su fundamento en una disposición, ni una disposición que por lo me
nos no albergue una norma.
Esta posibilidad de que el Tribunal Constitucional pueda distinguir entre «disposición» y
«norma», cuando se trata del proceso de inconstitucionalidad, es el presupuesto básico
de las denominadas sentencias interpretativas, cuyo fundamento, tal como se ha precisa
do, radica en el principio de conservación de la ley y en la exigencia de una interpretación
conforme a la Constitución, a fin de no vulnerar el principio de supremacía constitucional.
Las sentencias interpretativas recaen normalmente sobre disposiciones ambiguas, con
fusas o complejas, de las que se pueden extraer varios sentidos interpretativos, por lo que
corresponde al Tribunal Constitucional analizar la constitucionalidad, en primer lugar, de
la disposición; y, seguidamente, de todas aquellas normas que se desprendan de la dis
posición cuestionada con la finalidad de verificar cuáles se adecúan a la Constitución y
cuáles deben ser expulsadas del ordenamiento jurídico.
La interpretación de acuerdo con la constitución. “Las sentencias in te rp re ta tiva s-m a n ip u la ti-
vas (norm ativas). (STC 0004-2004-CC/TC).
En este caso el órgano de control constitucional detecta y determina la existencia de un
contenido normativo inconstitucional dentro de una leyó norma con rango de ley. La ela
boración de dichas sentencias está sujeta alternativa y acumulativamente a dos tipos de
operaciones: la ablativay la reconstructiva.
• La operación ablativa o de exéresis consiste en reducir los alcances normativos de
la ley impugnada «eliminando» del proceso interpretativo alguna frase o hasta una
norma cuya significación colisiona con la Constitución. Para tal efecto, se declara la
nulidad de las «expresiones impertinentes»; lo que genera un cambio del contenido
preceptivo de la ley.
• La operación reconstructiva o de reposición consiste en consignar el alcance norma
tivo de la ley impugnada «agregándosele» un contenido y un sentido de interpreta
ción que no aparece en el texto por sí mismo.
La existencia de este tipo de sentencias se justifica por la necesidad de evitar los
efectos perniciosos que puedan presentarse en determinadas circunstancias, como
consecuencia de los vacíos legales que surgen luego de la «expulsión» de una ley o
norma con rango de ley del ordenamiento jurídico. Tales circunstancias tienen que
ver con la existencia de dos principios rectores de la actividad jurisdiccional-consti-
tuyente, a saber; el principio de conservación de la ley y el principio de interpretación
desde la Constitución. Conviene tener presente en qué consisten:
El principio de conservación de la ley. Mediante este axioma se exige al juez constitucional
«salvar», hasta donde sea razonablemente posible, la constitucionalidad de una ley im
pugnada, en aras de afirmar la seguridad jurídica y la gobernabilidad del Estado, es de
cir, la expulsión de una ley del ordenamiento jurídico por inconstitucional, debe ser la
últim a ratio a la que debe apelarse. Así, la simple declaración de inconstitucionalidad no
debe ser utilizada, salvo si es imprescindible e inevitable.
