Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 76 of 1506 --

UBILEX
El principio de interpretación desde la Constitución. Mediante este axioma o pauta básica
se asigna un sentido a una ley cuestionada de inconstitucionalidad, a efectos que
ella guarde coherenciay armonía con el plexo del texto fundamental.
Dicha interpretación hace que la ley sea conforme a la Constitución; cabiendo, para tal efecto,
que se reduzca, sustituya o modifique su aplicación para los casos concretos.
Este tipo de sentencias propician el despliegue de los efectos de las normas constitucionales
que podrían ser obstaculizados por los «huecos normativos» emanados de un simple fallo es-
timatorio.
Las normas inducidas y deducidas emanadas de una sentencia manipulativa-interpretativa
(normativa) se encuentran implícitas dentro del ordenamiento constitucional, pero son objeti
vadles mediante este procedimiento.
C. Interpretación de los derechos fundamentales
La interpretación de los derechos fundamentales también se halla informada por ciertos prin
cipios o pautas hermenéuticas que el Colegiado Constitucional también se ha encargado de
precisar, entre los cuales destaca primordialmente, en la jurisprudencia del TC, el principio pro
domine y el principio de interpretación conforme a los tratados internacionales de derechos
humanos. Veamos:
Principio “pro ¡nomine”. - Ante eventuales diferentes interpretaciones de un dispositivo le
gal, se debe optar por aquella que conduzca a una mejor protección de los derechos fun
damentales, descartando así las que restrinjan o limiten su ejercicio. [...] el principio pro
domine impone que, en lugar de asumir la interpretación restrictiva, en este caso, de oca
sionar la caducidady así impedir el ejercicio del derecho a la tutela judicial, se tenga que,
por el contrario, optar por la tesis que posibilite que el particular pueda ejercer su derecho
a la tutela jurisdiccional, para impugnar el acto administrativo presuntamente lesivo.
Su interpretación conforme a los tratados internacionales. Tos derechos fundamentales
reconocidos por nuestra Constitución deben ser obligatoriamente interpretados de con
formidad con los tratados y los convenios internacionales sobre derechos humanos rati
ficados por el Perú y en concordancia con las decisiones adoptadas por los tribunales in
ternacionales sobre derechos humanos constituidos según tratados de los que el Perú es
parte. En caso de incompatibilidad entre una norma convencional y una constitucional, o
de incompatibilidad entre decisiones de tribunales internacionales y del Tribunal Cons
titucional, los jueces preferirán la norma o decisión que más favorezca a la personay sus
derechos humanos.” (Cuarta Disposición Final y Transitoria de la Constitución y artículo
VIII del Título Preliminar del Código Procesal Constitucional).
6. TÉCNICAS PARA RESOLVER CONFLICTOS CONSTITUCIONALES
Pueden producirse conflictos constitucionales en los siguientes ámbitos.
a) Entre los poderes públicos.
Ello ocurrirá cuando, en uso de su potestad pública, un poder invada atribuciones de otro.
Por ejemplo, la ley decide materias que son propias de la Constitución.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 77 of 1506 --

Tema 4: Teoría general de la Constitución
b) Conflictos entre el Estadoy los particulares.
Ellos se producirán cuando el Estado al usar su autoridad, violente cualquiera de los dere
chos que a los habitantes de la Nación les asegura la Carta Fundamental según el sistema
de cada país.
6.1. Proceso competencial
Para resolver esos enfrentamientos existe el Proceso Competencial, viene a ser aquel proceso
constitucional orgánico que tiende a resolver enfrentamientos que se suscitan sobre las com
petencias o atribuciones designadas directamente por la Constitución o las leyes orgánicas
que delimitan ámbitos propios de los Poderes del Estado, los órganos constitucionales, los
Gobiernos regionales o municipales. Dichos enfrentamientos se producen cuando alguno de
los poderes del Estado o de las entidades públicas toma decisiones que no le corresponden o
rehúye actuaciones que son propias de su competencia, interfiriendo en las atribuciones de
otros órganos que las tienen asignadas por la Constitución o las Leyes Orgánicas.
Competencia - Según el numeral 3, del artículo 202 de la Constitución, corresponde al Tribu
nal Constitucional conocer los conflictos de competencia, o de atribuciones asignadas por la
Constitución, conforme a ley.
Finalidad- Cesar Landa señalaq ue protege fundamentalmente dos principios separación de
poderes y de organismos constitucionales (división horizontal) y la redistribución territorial
del poder (división vertical).
El proceso competencial tiene como finalidad que se respeten las competencias que la Cons
titución y las leyes atribuyen a los poderes del Estado, los órganos constitucionales (por ejem
plo, la Junta Nacional de Justicia, el Ministerio Público, la Defensoría del Pueblo), los gobier
nos regionales o municipales. Se presenta al Tribunal Constitucional, quien lo resuelve como
instancia única. El propósito de este proceso es que no se vulnere la distribución de competen
cias que el ordenamiento jurídico ha establecido, ya sea invadiéndose un ámbito competen
cial ajeno o, rehuyéndose una atribución propia. La sentencia respectiva determina el poder,
órgano o ente a la que pertenece la competencia o, en su caso, ordena que sea ejercida por el
poder, órgano o ente renuente.
Formas del conflicto.-
C onflicto P ositivo: Cuando dos o más entidades constitucionales se disputan entre sí una
competencia o atribución constitucional. En este supuesto el Tribunal Constitucional
debe encargarse de definir quién es el titu la r de la competencia o atribución en controver
sia,y los efectos serán la anulación de los actos y relaciones jurídicas que ilegítimamente
se hubieran producido. (Art. 109 del Nuevo C.R Const.).
C onflicto N egativo : cuando dos o más entidades constitucionales se niegan a asumir una
competencia o atribución constitucional la sentencia, además de determinar su titu la
ridad, puede señalar, en su caso, un plazo dentro del cual el poder del Estado o el ente
estatal de que se trate debe ejercerlas. (Arts. 109,112 del Nuevo C.R Const.). Se distingue
del proceso de Cumplimiento, porque en el proceso competencial los sujetos constitu-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 78 of 1506 --

clónales se declaran incompetentes para asumir un mandato constitucional y no legal o
administrativo.
El Tribunal Constitucional, a través de su jurisprudencia ha señalado que existen otros casos
que se constituyen en conflictos competenciales, así tenemos:
- Conflictos por omisión en cumplimiento de acto obligatorio: establece que existe conflicto com
petencia! cuando un órgano constitucional omite llevar a cabo una actuación, descono
ciendo las competencias constitucionales atribuidas a otro órgano constitucional (STC N°
0005''2005''PC/TC).
Conflicto constitucional por menoscabo de atribuciones constitucionales (STC 0006-2006-PC/TC.
Fj.22): clasificado en tres subtipos:
a) Conflicto constitucional por menoscabo en sentido estricto, cada órgano constitucional co
noce perfectamente cuál es su competencia, sin embargo, uno de ellos lleva a cabo
un indebido o prohibido ejercicio de la competencia que le corresponde, lo que re
percute sobre el ámbito del que es titu lar el otro órgano constitucional.
b) Conflicto constitucional por menoscabo de interferencia, las competencias de los órganos
constitucionales están enlazadas a tal punto que uno de ellos no puede ejercer la
suya si no tiene la cooperación o la actuación de la competencia que le pertenece al
otro.
c) Conflicto constitucional por menoscabo de omisión, uno de los órganos omite ejercer su
competencia produciéndose, como consecuencia de ello, una atrofia o im posibili
dad de ejercicio de la competencia del otro órgano constitucional, solo que, en este
caso, la omisión funcional no es condición indispensable para el ejercicio de la com
petencia o atribución del otro órgano constitucional.
Los poderes o entidades estatales en conflicto actuarán en el proceso a través de sus titulares.
Tratándose de entidades de composición colegiada, la decisión requerirá contar con la apro
bación del respectivo pleno.
Procedencia.- Es procedente la demanda competencial cuando ésta reúne, en suma, dos re
quisitos indispensables: a) legitimidad de las partes, y b) existencia de un conflicto de competencias
constitucionales cierto. (STC N °00003- 2005-PC/TCy STC N° 00013-2003-PC/TC).
Legitimidad.
Activa: Los titulares de los Poderes del Estado, de los órganos constitucionales autóno
mos, y de los gobiernos regionales y locales. Cuando el Órgano en conflicto es colegiado,
el acuerdo de demandar debe ser adoptado por el respectivo pleno.
Pasiva: La Ley no lo establece, pero se entiende que será demando el poder u órgano del
Estado que pretende ejercer o ejerce la competencia o atribución materia del conflicto o
que niega su actuación alegando que corresponde a otro poder; órgano o entidad estatal.
Trámite del proceso competencial.- Conforme con lo prescrito por el art. 111 del NCPConst.
el procedimiento se sujeta, en cuanto sea aplicable, a las normas que regulan el proceso de
inconstitucionalidad. Se entiende, también, que el proceso competencial pasa por las etapas
