requiere del voto conforme de cuatro magistrados para declarar su inadmisibílídad. (Art. 111 NCP-
Const. modificado por Ley N” 32153)
Contenido de la sentencia.- En los procesos competenciales, la sentencia se obtiene con el
voto conforme de 04 magistrados. En caso de empate, el presidente del Tribunal Constitucio
nal tiene voto decisorio. De no Ilegarse al número de votos exigidos, se tendrá por infundada la
demanda (Art. 112 del NCPConst. primer párrafo, modificado por Ley N °32153).
El Tribunal debe expedir sentencia dentro de los 60 días hábiles desde que se interpuso la
demanda.
En caso de co n flicto positivo. La sentencia determina los poderes o entes estatales, a que corres
ponden las competencias o atribuciones controvertidas y anula las disposiciones, resolucio
nes o actos viciados de incompetencia. También resuelve lo que procediere sobre las situacio-15
