En caso de co nflicto negativo. Cuando se hubiera promovido conflicto negativo de competen-
cias y atribuciones, la sentencia, además de determinar su titularidad, puede señalar, en su
caso, un plazo dentro del cual el poder del Estado o el ente estatal de que se trate debe ejerci
