los procesos competenciales, vinculándose no solamente a todas las entidades públicas sino
a toda la población.
7. JURISDICCIÓN CONSTITUCIONAL
7.1. Garantías constitucionales
Las garantías constitucionales-o procesos constitucionales como lo denomina el Nuevo Có
digo Procesal Constitucional - Ley N° 3130716- están regulados en el artículo 200o de la Cons
titución. Son mecanismos de defensa que tiene toda persona ante la vulneración de sus dere
chos fundamentales o también pueden ser planteados para ejercer un control normativo de
normas infraconstitucionales.
Estas garantías o procesos constitucionales pueden ser:
Los procesos de Hábeas Corpus, amparo, Hábeas Data y Cumplimiento son tramitados,
en primera y segunda instancia ante el Poder Judicial. Si el agraviado en su derecho no
logra la tutela de su derecho puede acudir mediante el recurso de agravio constitucional
ante el Tribunal Constitucional, agotando con ello las instancias nacionales.
En el caso de los procesos de inconstitucionalidady competencial, ellos son conocidos, en única
instancia, por el Tribunal Constitucional de acuerdo al artículo 202o de la Constitución. Por últi
mo, el proceso de Acción Popularse tramita exclusivamente en el Poder judicial pronunciándose
en última instancia la Sala Constitucional y Social de la Corte Suprema de la república.
El Nuevo Código Procesal Constitucional (Pub. el 23.07.2021) modificado por la Ley N° 32153
(Pub. el 05.11.2024), incorpora cambios relevantes en el trám ite de los procesos constituciona
les, llevando a cabo una reforma integral tanto en el Título Preliminar, disposiciones generales
y en las disposiciones específicas de los procesos constitucionales.
a) Título Preliminar:
En el Art. III del TPy Cuarta Disposición Complementaria Final establece que, los procesos
constitucionales se encuentran exonerados del pago de tasas judiciales, con excepción de
los procesos de amparo contra resolución judicial, laudo arbitral o proceso parlamentario
interpuesto por personas jurídicas con fines de lucro.
En el Art. V del T.R regula la posibilidad de recurrir al a mi cus curiae, figura procesal que
permite que terceros ajenos al proceso ofrezcan su opinión sobre la controversia.
