Tema 4: Teoría general de la Constitución
En el ¡ArAVl del T.R incorpora un nuevo requisito para crear, modificar, apartarse o dejar
sin efecto un precedente vinculante y es contar con 05 votos conformes de los Magistrados que
conforman el Pleno del Tribunal Constitucional. En el caso de los procesos de Acción Popular,
ahora se permite que la Corte Suprema cree, modifique o derogue precedentes vincu
lantes del Poder Judicial con el voto conforme de 04 jueces supremos siempre que sean
conformes a la interpretación que resulte de las resoluciones del Tribunal Constitucional.
(Art. mod. Ley N °32153).
En el Art. VIII del T.P Los derechos constitucionales protegidos por los procesos constitu
cionales deben interpretarse conforme a la Declaración Universal de Derechos Humanos,
los tratados internacionales suscritos por el Perú y las sentencias de tribunales interna
cionales en los que el Perú es parte. En caso de conflicto entre normas convencionales
y constitucionales o entre decisiones de tribunales internacionales y del Tribunal Cons
titucional, se debe preferir la norma o decisión que más favorezca a la persona y a sus
derechos humanos. (Art. mod. Ley N° 32.153).
La Ley N° 32153 pretende reducir el ámbito de protección de los derechos fundamentales,
al precisar que éstos se deben interpretar conforme a los tratados de derechos humanos
"de los que el Perú es parte”, en la versión primigenia del Nuevo Código Procesal Constitu
cional se hacía referencia a la interpretación de los derechos constitucionales conforme
a las “decisiones” de los tribunales internacionales (Corte Interamericana de Derechos
Humanos). La CIDH emite decisiones en función contenciosa (sentencias) y en función
consultiva (opiniones consultivas). Con la modificación introducida por la Ley N°32i53 se
ha precisado que las decisiones de órganos como la Corte IDH sólo serían las sentencias
(ya no las opiniones consultivas) y sólo en casos en los que el Perú es parte (demandada).
b) Disposiciones Generales de los Procesos Constitucionales de Hábeas Corpus, Amparo,
Hábeas Data y Cumplimiento
El A rt.i° precisa que los procesos constitucionales tienen como finalidad proteger los de
rechos constitucionales individuales o colectivos. Se evita regularel amparo colectivoy no
hace referencia a los derechos difusos.
El Art. 4 establece que "el demandante que no cuenta con los recursos económicos sufi
cientes o se encuentra en estado de vulnerabilidad, puede recurrirá la defensa pública y,
si la hubiere, a la especializada en defensa constitucional y derecho procesal constitucio
nal" supuesto no previsto por la Ley N° 29360, “Ley del Servicio de Defensa Pública” y su
Reglamento-D.S. N°0i3-2009-JUS.
El segundo párrafo del Art. 5°, establece que “en los procesos constitucionales contra re
solución judicial no se notifica ni se emplaza con la demanda a los jueces o magistrados
del Poder Judicial”. Respecto de esta disposición el Tribunal Constitucional a través de la
STC Exp. o2748-2019-PHC/TC (FJs. 12,13,14) de fecha 15 de octubre de 2021 se ha pronun
ciado inaplicando el citado párrafo del Art. 5 del NCPconst., con vista de lo dispuesto en
los incisos 3 y 14 del artículo 139 de la Constitución. El primero hace referencia al debido
proceso y a la tutela jurisdiccional efectiva, como una garantía de la administración de
justicia, mientras que el segundo consagra “El principio de no ser privado del derecho de
defensa en ningún estado del proceso”. El Tribunal entiende que dicha prohibición afecta
