El inciso 2) del Art. 27oseñala que “el Ministerio Público form ula denuncia penal contra el
titu lar de la entidady los que resulten responsables, pudiendo exigir su prisión preventi
va”. Afectando así las competencias del Ministerio Público, que antes de la modificatoria
podía evaluar los hechos del caso y decidir si ameritaba hacer la denuncia o no.
El Art. 42o dispone que, la Sala Constitucional o, si no lo hubiere, la Sala Civil de turno
y la Sala Constitucional y Social de la Corte Suprema, son competentes para resolver en
segundo grado, si la afectación de derecho se origina en: a) Una resolución judicial de
