procedimiento de selección de obra pública o ejecución de estay c) Una decisión de los
Órganos del Congreso en un proceso parlamentario, conformidad con el artículo 52-A.
Es competente el juzgado constitucional si la violación de derechos se origina en una re
solución judicial firme expedida por un juez o sala especializada, siendo competente para
resolveren segundo grado la sala constitucional o sala civil. (Art. mod. Ley N° 32153)-
El Art. 4 5 ° establece que, tratándose del proceso de amparo contra resoluciones judicia
les o laudos arbitrales, el plazo para la interposición de la demanda es de 30 días hábiles.
