7.2. El Proceso de Hábeas Corpus
Definición.- El Hábeas Corpus, es un proceso destinado a la protección del derecho a la liber
tad personal, por el que se trata de impedir que la autoridad o alguno de sus agentes puedan
prolongar de forma arbitraria la detención o la prisión de un ciudadano. A través del Hábeas
Corpus, una persona privada de libertad puede obtener su inmediata puesta a disposición de
la autoridad judicial competente, que resolverá acerca de la legalidad o no de la detención.
El Hábeas Corpus, en el derecho comparado, tutela dos derechos fundamentales, la libertad
individual relativa a su libertad de movimiento y por tanto a no ser objeto de detenciones
arbitrarias y el derecho a la integridad personal, a no ser objeto de daños en su persona, como
lesiones, tortura o muerte. En ese sentido tiene como objeto el reponer las cosas al estado an
terior a la privación, perturbación o amenaza de dichos derechos por lo cual tiene un carácter
sumarlo (urgente) y potencialmente eventual en tanto se autoriza desde que aparece posible
una violación eventual a estos derechos para evitar que la violación se torne en irreparable.
Lógicamente, de tornarse en irreparable la violación, la acción de garantía pierde su objeto
(sustracción de la materia).
La acción de Hábeas Corpus, tiene como fin inmediato el restablecimiento de la libertad per
sonal vulnerada o amenazada. Esto significa regresar a la situación anterior en que se encon
traba el sujeto, en uso de su libertad. A decir de Ortecho Villena, este propósito resulta per
fectamente claro, frente a un arresto, pero resulta un tanto impreciso, pero no por eso menos
efectivo, cuando se trata de otros aspectos de la libertad personal, por ejemplo, en la omisión
de otorgar un pasaporte o el de ser asistido por un abogado, en caso de encontrarse detenido
ilegalmente o en el caso de Incumplimiento de una excarcelación ya ordenada.
Características.-
1) Informalidad: No se requiere de ningún requisito para presentar la demanda, sin más
obligación que detallar una relación sucinta de los hechos, se puede usar en su presen
tación cualquier medio disponible para el demandante o afectado, correo electrónico,
WhatsApp, teléfono, celular, telegrama, entre otros.
BALOTARI0 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 85 of 1506 --

Tema 4: Teoría general de la Constitución
2) No simultaneidad: No existe otro proceso para salvaguardar los derechos constituciona
les que protege. No existen vías paralelas.
3) Actividad vicaria: La demanda puede ser presentada por el agraviado o cualquier otra
persona en su favor, sin necesidad de contar con representación procesal.
4) Unilateralidad: No es necesario escuchar a la otra parte para resolver la situación del
agraviado.
5) Imprescriptibilidad: El plazo para interponer la demanda no prescribe. La interposición
de una demanda de hábeas corpus no está sujeta a un plazo de prescripción por la conti
nuidad de la violación del derecho a la libertady derechos conexos.
Derechos protegidos.- En el Perú, es procedente el Hábeas Corpus ante la acción u omisión
que amenaceovulnere los siguientes derechos que, enunciativamente (Art. 33 del N.C.RCons.),
conforman la libertad individual:
1) La integridad personal y el derecho a no ser sometido a tortura o tratos inhumanos o hu
millantes, ni violentado para obtener declaraciones.
2) El derecho a no ser obligado a prestar juramento ni forzado u obligado a declarar o re
conocer culpabilidad contra sí mismo, contra su cónyuge o conviviente, o sus parientes
dentro del cuarto grado de consanguinidad o segundo de afinidad.
3) El derecho a no ser exiliado sino por sentencia firme.
4) El derecho a no ser desterrado, expatriado o confinado por autoridad administrativa por
razones políticas, raciales, culturales, étnicas o por cualquier otra índole.
5) El derecho a no ser separado del lugar de residencia o expulsado del país sino por manda
to judicial o por aplicación de la ley correspondiente.
6) El derecho del extranjero, a quien se ha concedido asilo político, de no ser expulsado al
país cuyo gobierno lo persigue, o en ningún caso si peligrase su libertad o seguridad por
el hecho de ser expulsado.
7) El derecho de los nacionales o de los extranjeros residentes a ingresar, transitar o salir del
territorio nacional, salvo mandato judicial o aplicación de la ley correspondiente.
8) El derecho a no serdetenido sino por mandato escrito y motivado del juez, o por las auto
ridades policiales en caso de flagrante delito; o si ha sido detenido, a ser puesto dentro de
las 48 horas más el término de la distancia, a disposición del juzgado que corresponda, de
acuerdo con el acápite f) del inciso 24) del artículo 2 de la Constitución, sin perjuicio de las
excepciones que en él se consignan. En ningún caso debe interpretarse que las 48 horas a
las que se refiere el párrafo precedente o el que corresponda según las excepciones cons
titucionales es un tope indispensable, sino el máximo a considerarse a nivel policial.
9) El derecho a decidir voluntariamente prestar el servicio militar, conforme a la ley de la
materia.
10) El derecho a no serdetenido por deudas, salvo en el caso del delito de omisión de asisten
cia familiar.
11) El derecho a no ser privado del documento nacional de identidad, así como de obtener el
pasaporte o su renovación dentro o fuera de la República.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 85

-- 86 of 1506 --

UBILEX
■ ■ H 12) El derecho a no ser incomunicado sino en los casos establecidos porel literal g) del inciso
24) del artículo 2 de la Constitución.
13) El derecho a no ser sometido a esclavitud, servidumbre, explotación infantil o trata en
cualquiera de sus modalidades.
14) El derecho a ser asistido por un abogado defensor libremente elegido desde que se es
citado o detenido por la autoridad policial u otra, sin excepción.
15) El derechoa retirar la vigilancia del d om icilioy asuspenderel seguimiento policial, cuan
do resulten arbitrarios o injustificados.
16) El derecho a la excarcelación de un procesado o condenado, cuya libertad haya sido decla
rada porel juez.
17) El derecho a que se observe el trámite correspondiente cuando se trate del procedimiento
o detención de las personas, a que se refiere el artículo 99 de la Constitución.
18) El derecho a no ser objeto de ejecución extrajudicial y/o desaparición forzada.
19) El derecho a la verdad, de conformidad con su reconocimiento jurisprudencial.
20) El derecho del detenido o recluso a no ser objeto de un tratam iento carente de razonabi-
lidady proporcionalidad, respecto de la forma y condiciones en que cumple el mandato
de detención o la pena.
21) El derecho a la protección de la familia frente a actos de violencia doméstica.
22) El derecho a la defensa de los derechos constitucionales conexos con la libertad indivi
dual.
Clases.- Tanto del Tribunal Constitucional, el Nuevo Código Procesal Constitucional y la doc
trina, según las situaciones y circunstancias en que se producen la afectación a la libertad fun
damental afectada, han establecido las siguientes clases de Hábeas Corpus:
a) Hábeas corpus reparador. Dicha modalidad se utiliza cuando se produce la privación ar
bitraria o ilegal de la libertad física como consecuencia de una orden policial; de un man
dato judicial en sentido lato-juez penal, civil, militar-; de una decisión de un particular so
bre el internamiento de un tercero en un centro psiquiátrico sin el previo proceso formal
de interdicción civil; de una negligencia penitenciaria cuando un condenado continúe en
reclusión pese a haberse cumplido la pena; por sanciones disciplinarias privativas de la
libertad; etc. (Exp. N.° 2 6 6 3 -2 0 0 3 -HC/TC).
En puridad, el hábeas corpus reparador representa la modalidad clásica o inicial desti
nada a promover la reposición de la libertad de una persona indebidamente detenida.
b) Hábeas corpus innovativo. Resulta procedente en los casos que pese a haber cesado o
haberse convertido en irreparable la violación de la libertad personal, es necesario la in
tervención de la autoridad jurisdiccional a fin de que tales situaciones no se repitan en
el futuro contra la persona del accionante. El juez constitucional atendiendo al agravio
producido declarará fundada la demanda precisando los alcances de su decisión, dispo
niendo que el demandado no vuelva a incurrir en las acciones u omisiones que motivaron
la interposición de la demanda. (Exp. N .°2663-2003-HC/TC. FJ.6 .).
Domingo García Beláunde [C onstitucióny Política, Eddili, Lima 199T pág.148], expresa que
dicha acción de garantía “debe interponerse contra la amenaza y la violación de este de-
86 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 87 of 1506 --

Tema 4: Teoría general de la Constitución
recho, aun cuando éste ya hubiera sido consumado” Asimismo, César Landa Arroyo [Tri
bunal Constitucional, Estado Democrático, Editorial Palestra, Lima 2003, pág. 193], acota que
a pesar de haber cesado la violación de la libertad individual, sería legítimo que se
plantee un hábeas corpus innovativo, siempre que el afectado no vea restringida a futuro
su libertad y derechos conexos”.
c) Hábeas corpus preventivo. Que podrá ser utilizado en los casos en que, no habiéndose con
cretado la privación de la libertad, existe empero la amenaza cierta e inminente de que ello
ocurra, con vulneración de la Constitución o la ley de la materia. Al respecto, es requisito sirte
qua non de esta modalidad que los actos destinados a la privación de la libertad se encuen
tren en proceso de ejecución; por ende, la amenaza no debe ser conjetural ni presunta. (Exp.
N °06i 67-2005-PHC, F] 39).
d) Hábeas corpus excepcional. Nuestra Constitución, regula los Estados de Excepción en el
artículo 137°, y el artículo 200o, parte final, establece que el ejercicio de las acciones de
hábeas corpus y de amparo no se suspende durante la vigencia de los regímenes de ex
cepción a que se refiere el artículo 137o. Es innegable así, la procedencia del hábeas corpus
en los Estados de excepción, que denominamos de excepción por las condiciones reinan
tes en que se la tramitación correcta de este hábeas corpus debe hacerse a la luz de los
principios de razonabilidady proporcionalidad que se utilizan para determinar la validez
de los actos que restringen derechos en los Estados de Excepción.
e) Hábeas corpus restringido. Se emplea cuando la libertad física o de locomoción es objeto
de molestias, obstáculos, perturbaciones o incomodidades que, en los hechos, configu
ran una seria restricción para su cabal ejercicio. Es decir, que, en tales casos, pese a no
privarse de la libertad al sujeto, "se le lim ita en menor grado”. Entre otros supuestos, cabe
mencionar la prohibición de acceso o circulación a determinados lugares; los seguimien
tos perturbatorios carentes de fundamento legal y/o provenientes de órdenes dictadas
por autoridades incompetentes; las reiteradas e injustificadas citaciones policiales; las
continuas retenciones por control migratorio o la vigilancia domiciliaria arbitraria o in
justificada, etc. Entonces, dado que el objeto del hábeas corpus restringido consiste en
atender no aquellos supuestos en los cuales el derecho a la libertad personal es afectado
totalmente, sino que procede en aquellos casos en los cuales existe una restricción menor
en la libertad física de la persona, se convierte en el instrumento idóneo para tutelar el
derecho fundamental a la libertad de tránsito. (Exp. N °i o i o i - 05-PHC, FJi).
f) Hábeas corpus traslativo. Opera en los casos de los procesados, en que las autoridades
judiciales o penitenciarias indebidamente pudieran estar prolongando su detención en
un proceso judicial, o de los reos que ya han cumplido su condena pero siguen en cár
cel. Acontece por ejemplo, en los casos en que existe exceso de detención al continuar
el procesado detenido más allá del plazo fijado por la ley, o si el condenado no obstante
haber cumplido su condena continúa en prisión. Es decir, el derecho a la excarcelación
de un procesado o condenado, cuya libertad haya sido declarada por el Juez. César Lan
da Arroyo, Teoría del Derecho Procesal Constitucional, Editorial Palestra, Lima 2003, pág. 116,
refiere que en este caso "se busca proteger la libertad o la condición jurídica del status de
la libertad de los procesados, afectados por las burocracias judiciales [...]”. (Exp. N .°z663-
2003-HC/TC. FJ.6 .).
