Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 88 of 1506 --

UBILEX
I H H j g) Hábeas corpus instructivo. Esta modalidad podrá ser utilizada cuando no sea posible
** ubicar el paradero de una persona deten ida-desaparecida. Por consiguiente, la finali
dad de su interposición es no sólo garantizar la libertad y la integridad personal, sino,
adicionalmente, asegurar el derecho a la vida, y desterrar las prácticas de ocultamiento
o indeterminación de los lugares de desaparición. En efecto, la Corte Interamericana de
Derechos Humanos, en el caso Ernesto Castillo Páezvs. República del Perú, (párrafo 84 de
la sentencia del 3 de noviembre de 1997), estableció lo siguiente-. “Habiendo quedado de
mostrado como antes se dijo (supra, párrafo 71), que la detención del señor Castillo Páez
fue realizada por miembros de la Policía del Perú y que, por tanto, se encontraba bajo la
custodia de éste, la cual lo ocultó para que no fuera localizado, la Corte concluye que la
ineficacia del recurso de hábeas corpus es imputable al Estado, configurando con ello una
violación del artículo 25o de la Convención en relación con el artículo 1.1.” (Exp. N .°2663-
2003-HC/TC. FJ.6 J.
h) Hábeas corpus correctivo. Dicha modalidad, a su vez, es usada cuando se producen actos
de agravamiento ilegal o arbitrario respecto a las formas o condiciones en que se cumplen
las penas privativas de la libertad. Por ende, su fin es resguardar a la persona de tratamien
tos carentes de razonabilidad y proporcionalidad, cuando se ha determinado cumplir un
mandato de detención o de pena. Así, procede ante la amenaza o acto lesivo del derecho a
la vida, la integridad física y psicológica, o del derecho a la salud de los reclusos o personas
que se encuentran bajo una especial relación de sujeción internados en establecimientos
de tratamiento públicos o privados (tal el caso de personas internadas en centros de rehabi
litación y de menores, en internados estudiantiles, etc.). Igualmente, es idóneo en los casos
en que, por acción u omisión, importen violación o amenaza del derecho al trato digno o se
produzcan tratos inhumanos o degradantes. Es también admisible la presentación de esta
modalidad en los casos de arbitraria restricción del derecho de visita familiar a los reclusos;
de ilegitimidad del traslado de un recluso de un establecimiento penitenciario a otro; y por
la determinación penitenciaria de cohabitación en un mismo ambiente de reos en cárcel de
procesados y condenados. Por ello, es legítimo que ante la afectación de tales derechos fundamen
tales o de aquellos derechos directamente conexos al de la libertad personal o ante la lesión de derechos
diferentes al de la libertad, cuya afectación se genere como consecuencia directa de una situación de
privación o restricción del derecho a la libertad individual, puedan ser protegidos a través del proceso
de hábeas corpus, que la tipología elaborada por la doctrina ha denominado como hábeas corpus co
rrectivo..." (Exp. N°02700-2006-PHC, FJ. 2y3)
i) Hábeas corpus conexo. Cabe utilizarse cuando se presentan situaciones no previstas en
los tipos anteriores. Tales como la restricción del derecho a ser asistido por un abogado de
fensor libremente elegido desde que una persona es citada o detenida; o de ser obligado a
prestar juramento; o compelido a declarar o reconocer culpabilidad contra uno mismo, o
contra él o la cónyuge, etc. Es decir, si bien no hace referencia a la privación o restricción en
sí de la libertad física o de la locomoción, guarda, empero, un grado razonable de vínculo y
enlace con éste. Adicionalmente, permite que los derechos innominados-previstos en el
artículo 3o de la Constitución-entroncados con la libertad física o de locomoción, puedan
ser resguardados. (Exp. N.°2663-2003''HC/TC).
