ante el juez constitucional donde se produjo la amenaza o afectación del derecho o don
de se encuentre físicamente el agraviado si se trata de procesos de detenciones arbitrarias
o de desapariciones forzadas.
b) Calificación de la demanda: Implica la verificación de la demanda respecto del cumplimiento
de las exigencias de fondo y forma prevista en la Ley. Se prohíbe el rechazo liminar de las de
mandas a fin de garantizar un mayor acceso a la justicia constitucional.
