plazo indefectible de 10 días hábiles. Se faculta a las partes solicitar copia de los audiosy
videos de la audiencia pública.
Si con el escrito que contesta la demanda, el juez concluye que ésta es improcedente o
que el acto lesivo es manifiestamente ilegítimo, podrá em itir sentencia prescindiendo de
