demandante o el favorecido).
7.3. El Proceso de Amparo
7.3.1. Definición
Establecido en el artículo 200o, inciso 2) de la Constitución, así como en el Título III del Nuevo
Código Procesal Constitucional. El proceso de amparo o acción de amparo es la demanda jurí
dica que tutela los derechos constitucionales del ciudadano, cumpliendo una doble función de
protección al ciudadano en sus garantías fundamentales y a la propia constitución al garantizar
la inviolabilidad de sus preceptos ya sea por normas generales contrarias a dichos preceptos o
por actos de autoridad que vulneren el contenido o los derechos fundamentales reconocidos en
la Constitución.
Este recurso es una acción judicial cuyo objetivo consiste en proteger todos los derechos di
ferentes de la libertad física (estos se encuentran protegidos específicamente por el Hábeas
Corpus).
Así como el hábeas corpus garantiza el ejercicio de la libertad física o ambulatoria, el amparo
tiende a garantizar cualquiera de los derechos fundamentales. De modo que puede recurrir a
esta acción quien se vea privado de ejercer cualquiera de los derechos reconocidos expresa o
implícitamente por la constitución, un tratado o ley.
Cabe señalar que la Constitución de 1979 introduce por primera vez el amparo con rango cons
titucional y como garantía constitucional específica, distinta del hábeas corpus.
7.3.2. Derechos protegidos
En el Perú se puede ejercer el amparo en defensa de los siguientes derechos:
1) De igualdad y de no ser discriminado por razón de origen, sexo, raza, características ge
néticas, orientación sexual, religión, opinión, condición económica, social, idioma, o de
cualquierotra índole.
2) Al libre desenvolvimiento de la personalidad.
3) Del ejercicio público de cualquier confesión religiosa.
