El Tribunal Constitucional, vía precedente vinculante, Exp N° 02383- 2013-PA/TC Caso Elgo Ríos, determinó
cuándo nos encontramos frente a una vía igualmente satisfactoria ai proceso de amparo. Para ello, estableció
cuatro criterios para analizar la pertinencia ele la vía constitucional, que deben cumplirse de manera copulativa:
1. Que la estructura del proceso es idónea para la tutela del derecho;
2 Que la resolución que se fuera a emitir podría brindar tutela adecuada;
3. Que no existe riesgo de que se produzca la irreparabilldad; y,
4. Que no existe necesidad de una tutela urgente derivada de la relevancia dei derecho o de la gravedad de
las consecuencias.
7.3.3. Modalidades especíales del Proceso de Amparo
I. Amparo contra resoluciones judiciales que vulneran derechos fundamentales
El numeral 4, in fine, del artículo 200 de la Constitución indica que la Acción de Amparo «No
procede contra normas legales ni contra resoluciones judiciales emanadas de procedimiento
regular». Admite así, a contrario sensu, que dicha acción procede cuando la resolución judicial
emana de un procedimiento Irregular. En concordancia con este precepto constitucional, el
primer párrafo del artículo 9 del NCPC, precisa que el amparo «procede respecto de resolucio
nes judiciales firmes dictadas con manifiesto agravio a la tutela procesal efectiva, que com
prende el acceso a la justicia y al debido proceso».
Al respecto el Tribunal Constitucional a través del Exp. N °3T79-2 0 0 4 -AA/TC (FJ. 5,6)señala que:
La respuesta (doctrinal y) jurisprudencial que se ha dado al tema en cuestión normal
mente se ha intentado a partir de una interpretación de la limitación contenida en el
segundo párrafo del inciso 2) del artículo 200 de la Constitución, cuyo texto reproduce
con algunas variantes lo que en su momento preveía el inciso 3) del artículo 6 de la Ley
N°. 23506, ahora derogado, según el cual el amparo: (...) no procede contra (...) resoluciones
judiciales emanadas de procedimiento regular.
Descartada una iectura de dicho precepto constitucional en el sentido de que no cabía la
interposición de un amparo contra resoluciones judiciales, existe consenso en admitirse
que, más que una prohibición, en realidad, dicho precepto contiene una limitación, cuyo
ámbito de actuación opera en aquellos casos en los que la resolución judicial emana de
un proceso “regular”, pero no en aquellos otros donde ésta se expide en el seno de un
proceso “irregular”.
¿cuándo un proceso judicial puede considerarse "regular”?o, dicho en términos negativos,
¿cuándo una resolución judicial emana de un proceso “Irregular"? La absolución de tal
interrogante, a su vez, fue: Una resolución judicial emana de un proceso regular si ésta
se expide con respeto de los derechos que Integran el debido proceso y la tutela juris
diccional efectiva, ambos reconocidos en el Inciso 3) del artículo 139 de la Constitución.
Lo que venía a significar que mediante el amparo sólo se podía cuestionar resoluciones
judiciales si es que en el momento de expedirse, la irregularidad se materializaba en la
afectación de derechos que forman parte de aquél.
