Con ello, por un lado, se ratificaba la tesis de que el amparo contra resoluciones judiciales
no podía constituir un instrumento procesal que se superpusiera a los medios impugna-
torios existentes en la legislación procesal y, tampoco, en la habilitación de una vía en la
que se pudiera reproducir una controversia formulada ante las instancias de la jurisdic
ción ordinaria.
Pero, al mismo tiempo, se venía a institucionalizar una doctrina jurisprudencial, según la
cual los jueces ordinarios, en el ejercicio de sus funciones, sólo se encontraban vinculados
a un número determinado de derechos fundamentales. En concreto, sólo en relación con
aquellos de naturaleza procesal (tutela procesal y todos los derechos que lo integran).
En definitiva, ya sea por vía jurisprudencial o por vía legislativa, la concreción sobre el
ámbito de protección del amparo contra resoluciones judiciales se ha circunscrito sólo a
la protección de los derechos fundamentales de orden procesal, quedando fuera de su
ámbito todos los otros derechos igualmente fundamentales (o constitucionales).
En cuanto a la competencia19, la doctora Ana María Arrarte señala-, “en su versión original del
2021, el Nuevo Código Procesal Constitucional precisó que la demanda de amparo contra re
solución judicial “se interpone ante la sala constitucional o, si no lo hubiere, ante la sala civil de turno
déla corte superior de justicia respectiva”. Luego, por Ley N° 31583, se les dio el mismo tratamiento
a los amparos contra: (i) laudos arbitrales, (¡i) procedimientos de selección de obra público
o ejecución de esta; y, (iii) decisión de los órganos del Congreso, dentro de un proceso parla
mentario.
Ahora, con la Ley N°32153, se ha precisado el siguiente trám ite en el caso de amparos contra
resoluciones judiciales:
