II. Amparo contra normas autoapi¡cativas
El proceso de amparo contra normas procede si concurren los siguientes presupuestos:
a) Cuestionamiento de norma para el caso concreto y no en abstracto: Se ha sostenido en
la STC Exp. N° 2308-2004-AA/TC que el inciso 2) del artículo 200o de la Constitución no
contiene una prohibición de cuestionarse mediante el amparo leyes que puedan ser le
sivas en sí mismas de derechos fundamentales, sino una simple limitación que pretende
impedir que a través de un proceso cuyo objeto de protección son los derechos constitu
cionales se pretenda impugnar en abstracto la validez constitucional de las normas con
rango de ley.
b) Debe tratarse de normas autoapi ¡cativas: La procedencia de este instrumento procesal
está supeditada a que la norma legal a la cual se le imputa el agravio sobre un derecho
fundamental se trate de una norma operativa o denominada también de eficacia inme-
diata(autoapl¡cativa), esto es, aquella cuya aplicabilidad no se encuentre sujeta a la reali
zación de algún acto posterior o a una eventual reglamentación legislativa, en la medida
en que adquiere su eficacia plena en el mismo momento en que entra en vigencia.
c) En el caso de amenaza: Por un lado, si se trata de una alegación de amenaza de viola
ción, ésta habrá de ser ciertay de inminente realización, y, por otro lado tratándose de la
alegación de violación, tras realizar actos de aplicación concretos sustentados en una ley,
como sucede en cualquier otra hipótesis del amparo, es preciso que éstos efectivamente
lesionen el contenido constitucionalmente protegido de un derecho fundamental.
III. Amparo contra Amparo
Según precedente vinculante del Tribunal Constitucional, constituirá objeto del “amparo con
tra amparo” (STC Exp. N° 04853''2004-AA/TC-La Libertad):
PRIMER SUPUESTO: sentencias estimatorias de segundo grado que afectan derechos fun
damentales. En este punto conviene precisar que conforme tiene establecido este Tribunal
(Exp. N.° 3i79-2004-AA/TC)(F], 12), la protección de los derechos fundamentales vía un nuevo
proceso de amparo no se agota en los aspectos formales, toda vez que el "amparo contra am
paro" comparte el mismo potencial reparador cuando se trata de la afectación de cualquier
derecho fundamental; esto es,"(...) comprender residualmente la protección de todos los de
rechos constitucionales no protegidos por los otros procesos de tutela de los derechos funda
mentales (hábeas corpus y hábeas data)".
“El nuevo amparo podrá incluir como pretensión lo que ha sido objeto del prim er amparo sólo si
la violación del contenido constitucíonalmente protegido del derecho fundamental es de tal in
tensidad que desnaturaliza la decisión misma y la convierte en inconstitucional; caso contrario,
no procederá el "amparo contra amparo" por haberse configurado la cosa juzgada constitucio
nal". (STC Exp. N° 04853-2004-AA/TC. FJ.12)
