SEGUNDO SUPUESTO: sentencias estimatorias que desconocen la doctrina constitucional
establecida en la Jurisprudencia del Tribunal Constitucional. Entendiendo por tal la que está
contenida en sentencias que: i) interpretan la Constitución, ii) interpretan la ley, y iii) esta
blecen proscripciones interpretativas. Al respecto, en la STC 03741- 2004-AA/TC, el TC define
el concepto de «doctrina jurisprudencial» señalando que «Las sentencias del Tribunal Consti
tucional, dado que constituyen la Interpretación de la Constitución del máximo tribunal ju
risdiccional del país se estatuyen como fuente de derecho y vinculan a todos los poderes del
Estado. [...] La jurisprudencia constituye, por tanto, la doctrina que desarrolla el Tribunal en los
distintos ámbitos del derecho, a consecuencia de su labor frente a cada caso que va resolvien
do» (FJ.42). Finalmente, en torno a la distinción entre jurisprudencia y precedente vinculante
puntualiza que «[...] tanto la jurisprudencia como el precedente constitucional tienen en co
mún la característica de su efecto vinculante» (FJ.43).
TERCER SUPUESTO: decisiones denegatorias de segundo grado que afectan derechos de
terceros que no han intervenido en el proceso y del recurrente que no ha tenido ocasión de
interponer el respectivo recurso de agravio. En los siguientes presupuestos: (1) el caso del
tercero que no ha participado en el primer proceso, bien por no haber sido adm itido como
parte en el primer amparo, pese a contar con los presupuestos procesales para ello, bien por
desconocimiento del trámite al no habérsele notificado como correspondía en su calidad de
litisconsorte necesario. En este supuesto, la decisión desestimatoria de segundo grado le ha
producido agravio sin que pueda ejercer su derecho de defensa; y (2) el caso de quien, habien
do sido parte en el proceso, no ha podido interponer el recurso de agravio en su oportunidad,
sea por no habérsele notificado oportunamente la sentencia desestimatoria o porque, pese a
habersido notificado, no ha podido conocer de su contenido poralguna imposibilidad mate
rial debidamente acreditada.
IV. El Amparo contra los Procedimientos Parlamentarios2021
Ubi esteadem ratio, ibi ídem ius2\ El debido proceso se exige en los procesos judiciales (Poder
Judicial), los procedimientos administrativos (Poder Ejecutivo) y los procedimientos parla
mentarios (Poder Legislativo), estos últimos incluyen a los procedimientos legislativos. En
el caso de los procedimientos parlamentarlos, estos constituyen un conjunto de actos parla
mentarios, tanto los actosy procedimientos parlamentarios deben desarrollarse sin afectar el
debido proceso que es un derecho humano fundamental; en efecto, los funcionarios públicos
que sean sometidos a estos procedimientos parlamentarlos tienen derecho al debido proce
so cuando son sujetos en dichos procedimientos, estando a esto, la contravención al debido
proceso en un procedimiento parlamentario da la posibilidad al afectado de interponer una
demanda constitucional de amparo, lo que nos remite a lo dispuesto en el artículo 52-A del
Nuevo Código Procesal Constitucional (CPConst) - Ley 31307 - que regula el procedimiento
especial del amparo en el caso de los procedimientos parlamentarios.
