2. ¿Qué son las atribuciones exclusivas y excluyentes?
De la lectura de esta disposición, es importante definir que son las “atribuciones exclusivas y
excluyentes", lo que nos lleva a establecer los tipos de competencias que pueden ser atribui
das a los organismos públicos constitucionales. Estas competencias son las siguientes:
a. Competencias exclusivas, son aquellas que son asignadas en exclusividad (únicamente a
un organismo constitucional). Estas competencias pueden ser:
a.i. Competencias exclusivas positivas, si son susceptibles de ser delegadas.
a.2. Competencias exclusivas negativas, si no es posible delegar las competencias ex
clusivas. En este caso, las competencias exclusivas también son excluyentes, es decir,
descarta la competencia de otros organismos constitucionales.
b. Competencias compartidas, cuando se reparten responsabilidades sobre una materia
entre dos (2) o más niveles de gobierno, siendo los niveles de gobierno: gobierno nacio
nal, gobierno regional y gobierno local.
c. Competencias delegadas, si un nivel de gobierno realiza una delegación de competen
cias a otro nivel distinto, conforme a ley, y se abstiene de tom ar decisiones sobre la mate
ria o función delegada.
d. Competencias concurrentes, cuando dos (2) o más órganos asumen fundones específi
cas comunes, existiendo una relación complementaria de tutelay control normativo.
Lo indicado tiene sustento en lo siguiente: “Al respecto, se debe tener en cuenta, en primer lugar, cuá
les son los tipos de competencias objeto de análisis en un proceso competenciaI: (i) (¡i) exclusivas, cuando
son asignadas en exclusividad, aunque pueden sera su vez positivas si son susceptibles de ser delegadas, o
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
