negativas si ello no es posible, en cuyo caso serán también excluyentes; compartidas, cuando se reparten
responsabilidades sobre una materia entredós o más niveles de Gobierno; o (Iii) delegadas, si un nivel de
Gobierno realiza una delegación de competencias a otro nivel distinto, conforme a ley,y se abstiene de
tomar decisiones sobre la materia o función delegada”(fundamento 21 Sentencia 458/2020, Expedien
te 0021-2018-PI). "Competencias concurrentes: Son materias que dan lugar a que dos o más órganos
asuman funciones específicas comunes, existiendo una relación complementaria de tutela y control nor
mativo”(fundamento 61 Sentencia del Pleno del Tribunal Constitucional, Expediente 002-2005-PI/TC).
Estando a lo anterior, cuando la disposición bajo comentario indica atribuciones exclusivas y
excluyentes del Congreso de la República, se refiere a las competencias asignadas en exclusivi
dad al Congreso de la República por la Constitución, que no son susceptibles de ser delegadas,
por lo que también son competencias excluyentes.
3. Objeto de! aupar© en los procedimientos parlam entarios
Ahora bien, la disposición bajo comentario delimita cuáles son las atribuciones exclusivas
y excluyentes que en su ejercicio pueden ser cuestionadas a través del proceso de amparo a
través del procedimiento especial analizado. De esta manera, tenemos que las atribuciones
exclusivas y excluyentes del Congreso que son objeto de este amparo son las siguientes:
a. Atribuciones referidas a la elección, designación, ratificación y remoción de altos funcio
narios.
b. Atribuciones vinculadas al juicio y antejuicio político.
c. Atribuciones vinculadas a la vacanciay suspensión presidencial.
A continuación, desarrollaremos cada una de estas atribuciones a fin de delim itar el uso del
amparo contra los procedimientos parlamentarios.
