a. Causales de vacancia presidencial. El artículo 113 de la Constitución Política del Perú es
tablece las causales de vacancia del Presidente de la República al indicar:
''''La Presidencia de la República vaca por: 1. Muerte del Presidente de la República. 2. Su permanente incapaci
dad moral o física, declarada por el Congreso. 3. Aceptación de su renuncia por el Congreso. 4. Salir de! territo
