moral o física requiere de la observancia del debido proceso, caso contrario sería posible
interponer una demanda de amparo en la vía del procedimiento especial.
b. Causales de suspensión presidencial. El artículo 114 de la Constitución Política del Perú
establece las causales de suspensión del ejercicio de la Presidencia al indicar.
