Establecido que el acto lesivo debe derivarse del ejercicio de las atribuciones al Congreso de
la República antes indicadas, es preciso establecer cuáles son las reglas especiales de tram ita
ción del procedimiento especial para este tipo de procesos de amparo.
4. Reglas especiales de tramitación
A continuación, describiremos las reglas especiales de tramitación de este tipo de procesos
de amparo contra procedimientos parlamentarios, teniendo en cuenta la disposición bajo co
mentario.
4 X Interposición de la demanda constitucional de amparo. El artículo 39 del CPConst indica:
"El afectado es !a persona legitimada para interponer el proceso de amparo”
En el procedimiento especial que nos ocupa se hace la siguiente precisión conforme al literal
a) del artículo 52-Adel CPConst que indica:
“a) La demanda la interpone el titular del derecho directamente a fectado que invoque la vulneración del debido
proceso".
De lo indicado en la referida norma, podemos establecer lo siguiente:
a. La demanda es interpuesta por el titu lar del derecho directamente afectado, conforme
a esto, quien tendrá legitimidad para obrar en este tipo de procesos será el alto funcio
nario directamente afectado, con lo que también se precisa que se debe de producir la
afectación del derecho, lo que parecería indicar que no es posible su interposición respec
to de la amenaza del derecho, sin embargo, en atención al principio pro homine, deberá
de entenderse que la amenaza como sustento de este tipo de demanda también resulta
procedente; ahora bien, cuando se indica que solo el alto funcionario afectado puede in
terponer la demanda, se excluye que esta demanda sea interpuesta por la Defensoría del
Pueblo, conforme al artículo 40, últim o párrafo, del CPConst; sin embargo, debe tenerse
en cuenta que esta norma se refiere a la legitimidad para obrar que es ejercida por el alto
funcionario directamente afectado, más no se refiere a la capacidad procesal por lo que
no se excluye la representación procesal ni la procuración oficiosa.
b. Asimismo, se precisa que esta demanda solo procedería por la vulneración del debido
proceso en los procedimientos parlamentarios a los que se refiere la disposición bajo co
mentario, de esta manera, el amparo, en este caso, dará lugar al restablecimiento de las
cosas al estado anterior a la violación del derecho, esto es, retrotraer el procedimiento
parlamentario al momento de la afectación de derecho al debido proceso, en el primer
párrafo del artículo 1 del CPConst se indica:
