4.2.Competencia En los literales b)y d) del artículo 52-A del CPConstse establece:
"b) En primera instancia la demanda es de conocimiento de la sala constitucional ddien adopta todas sus
decisiones con tres votos conformes; debiendo resolverse en un plazo máximo de 60 días hábiles desde la
presentación de la demanda"; “d) La Sala Constitucional y Social de la Corte Suprema de la República resuelve
la apelación, y adopta decisiones con cuatro votos conformes".
Esta disposición nos remite al literal d) del segundo párrafo del artículo 42 del CPConst que indica:
"Es competente la sala constitucional o, si no lo hubiere, la sala civil de tum o de la corte superior de justicia
respectiva y la Sala Constitucional y Social de la Corte Suprema es competente para resolver en segundo
grado, si la afectación de derechos se origina en": “d) Una decisión de los órganos del Congreso dentro de un
procedimiento parlamentario, de conformidad con el artículo 52-A" (el resaltado es nuestro).
Conforme a lo indicado, podemos establecer las instancias en el presente proceso de amparo
especial:
a. En primera instancia, conoce la Sala Superior Constitucional de la Corte Superior de Jus-
ticia respectiva
b. En segunda instancia, conoce la Sala Constitucional y Social de la Corte Suprema de la
República
c. En última instancia, en caso de que el demandante obtenga un resultado desfavorable
en segunda instancia, conoce el Tribunal Constitucional.
