Esto es concordante con el últim o párrafo del artículo 12 del CPConstque indica:
“SI con el escrito que contesta ta demanda, el juez concluye que esta es improcedente o que el acto lesivo es
manifiestamente ilegítimo, podrá em itir sentencia prescindiendo dé la audiencia única, ío úispues.o an
