Como se verifica, en este procedimiento especial se realiza indefectiblemente la audiencia
única en la cual el juez oye a las partes, para luego de haberse formado juicio, pronunciar su
sentencia conforme al cuarto párrafo del artículo 12 del CPConstque indica:
"En la audiencia única, el Juez oye a las partes y si se ha formado juicio pronuncia sentencia en el acto o, en
caso contrarío, lo hace en el plazo indefectible de diez días hábiles".
4.4. Improcedencia de la medida cautelar El literal e) del artículo 52-A del CPConst establece:
"e) No procede la medida cautelar".
Lo indicado concuerda con lo indicado en el últim o párrafo del artículo 18 del CPConst deno
minado “medidascautelares” que indica:
"Lo dispuesto en el presente artículo no se aplica a los supuestos del artículo 52-A".
De esta manera, la solicitud de medida cautelar, antes y durante este proceso de amparo es
pecial, es improcedente; tampoco será procedente la medida cautelar que se sustente en la
sentencia que declara fundada la demanda de amparo en primera instancia; asimismo, de
bido a la remisión al artículo 18 del CPConst, tampoco serán procedentes las solicitudes de
suspensión del acto violatorio en los procesos de amparo.
Sin embargo, respecto de la continuación en el trámite de los procedimientos parlamentarios
indicados, habría de estarse a la prohibición de avocamiento indebido a causa pendiente ante
el órgano judicial prevista en el segundo párrafo del inciso 2) del artículo 139 de la Constitución
Política del Perú que indica:
4 -5- Improcedencia de la actuación inmediata de sentencia En el literal g) del artículo 52-A
del CPConst se establece:
