"Lo dispuesto en el presente artículo no se aplica a los supuestos del artículo S2-AH:
Conforme a esto, en el caso de emitirse una sentencia estimatoria de primer grado, esta no será
de actuación inmediata, a lo que se suma que tampoco será procedente el pedido de medida
