4 .6. Recurso de apelación En el literal c) del artículo 52-A del CPConst establece:
"c) El recurso de apelación se interpone ante la misma sala y se concede con efecto suspensivo".
Siendo que la sentencia de primera instancia es emitida por una Sala SuperiorConstitucional,
el recurso de apelación contra la sentencia (estimatoria o desestimatoria) se interpondrá ante
esta misma sala superior, laque concederá el recurso de apelación con efecto suspensivo; será
con efecto suspensivo, por cuanto no procede la actuación inmediata de la sentencia.
Con relación al plazo para interponer el recurso de apelación, este es de tres (3) días hábiles
conforme al literal b) del artículo 22 del CPConst que indica:
"El recurso de apelación eh lps procesos constitucionales de hateas Corpus, amparo, hateas data y de cumpli
miento procede contra Jas resoluciones que las partes consideran que los agravia. Los plazos para impugnar
las son"; "b) En los procesos de amparo, tabeas data y de cumplimiento es de tres días hábiles" (el resaltado
es nuestro).
4.7. Plazo del procedimiento especial. En el literal b) del artículo 52-A del CPConst establece:
: "b) En primera instancia la demanda es de conocimiento de la sala constitucional, quien adopta todas sus
decisiones con tresvotos conformes; debiendo resolverse en un plazo máximo de 60 días hábiles desde la
■ presentación d e la demanda" (el.resaltado es nuestro).
El plazo máximo para resolver, en primera instancia, este proceso es de sesenta (60) días há
biles contados desde la presentación de la demanda, el cumplim iento es este plazo es bajo
responsabilidad funcional, conforme lo establece el últim o párrafo del artículo 52-A del CP
Const que indica:
"Este procedimiento especial tiene trámite preferente y urgente en todas las instancias dentro de los plazos
máximos establecidos, bajo responsabilidad funcional".
De la lectura de este párrafo, también tenemos que el cumplim iento de los plazos máximos
se extiende a las siguientes instancias bajo responsabilidad funcional, lo que nos remite al
artículo 20 del TUO de la Ley Orgánica del Poder judicial que indica:
"Los Magistrados sólo son pasibles de sanción por responsabilidad funcional en los casos previstos expresa
mente por la ley, en la forma y modo que esta ley señala".
