5. Características del procedimiento especial
En el últim o párrafo del artículo 52-A del CPConstse indica:
"Este procedimiento especial tiene trámite preferente y urgente en todas las instancias dentro de los plazos
máximos establecidos, bajo responsabilidad funcional" (el resaltado es nuestro).
De la lectura de este párrafo tenemos que son características de este procedimiento:
5.1. Trámite preferente. Por esta característica, la tramitación de este proceso de amparo será
preferida a la tramitación de otros procesos judiciales, incluso con relación a otros procesos
de amparo.
5.2. Trámite urgente. Esta característica se complementa con laobllgación de resolver las Ins
tancias de este procedimiento bajo responsabilidad funcional, por lo que entendemos que los
plazos se entienden como máximos, lo que implica la posibilidad de resolver estos procesos
antes del vencimiento de estos plazos máximos.
6. Etapas del procedimiento especial
Estando a las reglas especiales de este amparo especial y sus características, el siguiente grá
fico nos mostrará las etapas de este proceso constitucional de amparo contra procedimientos
parlamentarios que se tramitará en la vía del procedimiento especial
