7.3.4. Legitim ación y demanda
La demanda de amparo se presenta por escrito. Están legitimados para interponerla:
El afectado (persona natural o jurídica), su representante procesal (sin requerir inscrip
ción).
Para persona no residente, su representante acreditado.
Cualquier persona en caso de derechos difusos.
La Defensoría del Pueblo, en ejercicio de sus competencias constitucionales.
Se interpone ante, a elección del demandante, el juez constitucional del lugar donde se afectó
el derecho, o donde tiene su domicilio el afectado, o donde d o m icilia d autor de la infracción.
Es competente la sala constitucional o, si no lo hubiere, la sala civil de turno de la corte supe
rior de justicia respectiva y la Sala Constitucional y Social de la Corte Suprema es competente
para resolver en segundo grado, si la afectación de derechos se origina en:
a) Una resolución judicial o laudo arbitral.
b) Un procedimiento deselección de obra pública o ejecución de esta.
c) Una decisión de los órganos del Congreso, dentro de un proceso parlamentario.
En el proceso de amparo, no se admitirá la prórroga de la competencia territorial, bajo sanción
de nulidad de todo lo actuado.
7.3.5. Vías previas
El agotamiento de lavíaprevia, nodebe confundirse con el agotamiento de lavía administra
tiva, ésta últim a es la especie de la primera. Sólo procede el proceso de amparo si se agotaron
las vías previas. Si hay duda sobre su agotamiento debe admitirse la demanda por el principio
pro actione. No será exigible el agotamiento si: 1) una resolución, sin ser la últim a en la vía ad
ministrativa, es ejecutada antes de quedar consentida; 2) por su exigencia la agresión pudiera
convertirse en irreparable; 3) lavía previa no está regulada o ha sido iniciada innecesariamen
te, o, 4) No se resuelve la vía previa en los plazos fijados para su resolución.
