7.3.6. Plazos para interponer ia demanda
El plazo para interponer la demanda prescribe a los 6 o días hábiles de producida la afectación,
siempre que el afectado hubiese tenido conocimiento del acto lesivo y se hubiese hallado en
posibilidad de interponer la demanda. Si esto no hubiese sido posible, el plazo se computará
desde el momento de la remoción del impedimento.
Tratándose del proceso de amparo iniciado contra resolución judicial o laudo arbitral, el plazo
para interponer la demanda es de 30 días hábilesy se inicia con la notificación de la resolución
o laudo arbitral que tiene la condición de firme.
Para el cómputo del plazo se observarán las siguientes reglas:
1) El plazo se computa desde el momento en que se produce la afectación, aun cuando la
orden respectiva haya sido dictada con anterioridad.
2) Si la afectación y la orden que la ampara son ejecutadas simultáneamente, el cómputo
del plazo se inicia en dicho momento.
3) Si los actos que constituyen la afectación son continuados, el plazo se computa desde la
fecha en que haya cesado totalmente su ejecución.
4) La amenaza de ejecución de un acto lesivo no da inicio al cómputo del plazo. Solo si la
afectación se produce se deberá empezar a contar el plazo.
5) Si el agravio consiste en una omisión, el plazo no transcurrirá mientras ella subsista.
6) El plazo comenzará a contarse una vez agotada la vía previa, cuando ella proceda.
7) Si se trata de normas autoapl¡cativas el plazo no prescribe, salvo que la norma sea deroga
da o declarada inconstitucional.
7.3.7. Calificación de la demanda
Implica la verificación de la demanda respecto del cumplim iento de las exigencias defondoy
forma prevista en la Ley. Se prohíbe el rechazo lim inarde las demandas a fin de garantizar un
mayor acceso a la justicia constitucional.
