P '' 7.4. El proceso de hábeas data
Tiene como objeto proteger a las personas a fin de que no se dé i nformación de ellas a terceros,
en la medida en que están guardados en bancos de datos24y afecten a la integridad personal
y familiar. También la de que no se registren datos que afectan a la persona en toda clase de
servicios electrónicos, informáticos, etc. Los cuales pueden ser borrados si eso sucede. Igual-
mente, a solicitar información sin expresión de causa, a cualquier entidad pública. Es decir, es
una defensa del derecho a la privacidad, a la dignidad y el buen nombre, en la medida que es
amenazada por el mundo informático o sea por las computadoras y sus redes, así como un
derecho a la información.
7.4.1. Derechos protegidos
El hábeas data procede en defensa de los derechos constitucionales de acceso a la informa
ción pública y la autorregulación informativa, ambos reconocidos por los incisos 5) y 6) del
artículo 2 de la Constitución, así tenemos:
• A solicitar sin expresión de causa la información que requiera y a recibirla de cualquier
entidad pública, en el plazo legal, con el costo que suponga el pedido. Se exceptúan las
informaciones que afectan la intim idad personal y las que expresamente se excluyan por
ley o por razones de seguridad nacional.
Toda persona tiene derecho al secreto bancario y la reserva tributaria. Su levantamiento
solo puede efectuarse a pedido.-1. Del juez. 2. Del Fiscal de la Nación. 3. De una comisión
investigadora del Congreso con arreglo a ley y siempre que se refieran al caso investigado.
4 . Del Contralor General de la República respecto de funcionarios y servidores públicos
que administren o manejen fondos del Estado o de organismos sostenidos por éste, en
los tres niveles de gobierno, en el marco de una acción de control. 5. Del Superintendente
de Banca, Seguros y Administradoras Privadas de Fondos de Pensiones para los fines es
pecíficos de la inteligencia financiera.
• A que los servicios informáticos, computarizados o no, públicos o privados, no suminis
tren informaciones que afecten la intim idad personal y familiar.
En ese mismo sentido, el nuevo Código Procesal Constitucional en su artículo 59° establece
que "El hábeas data procede en defensa del derecho de acceso a la información pública reco
nocido en el inciso 5) del artículo 2 de la Constitución".
También procede en defensa del derecho a la autodeterminación informativa, enunciativa
mente, bajo las siguientes modalidades:
1) Reparar agresiones contra la manipulación de datos personalísimos almacenados en
bancos de información computarizados o no.
2) A conocery supervisar la forma en que la información personal viene siendo utilizada.
3) A conocer el contenido de la información personal que se almacena en el banco de datos.
24 “Se entiende pon anchivo, negistno, base o banco de datos a todo conjunto de datos onganizado de infonmación pensonaly que sean
objeto de tnatamiento o pnocesamiento físico, electnónico o computanizado.ya sea público o privado,y cualquiena que fuene la mo
dalidad de su fonmación, almacenamiento, onganización o acceso." Alt. 53 NCPConst.
no BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 111 of 1506 --

Tema 4: Teoría general de la Constitución
4) A conocer el nombre de la persona que proporcionó el dato.
5) A esclarecer los motivos que han llevado a la creación de la base de datos.
6) A conocer el lugar donde se almacena el dato, con la finalidad de que la persona pueda
ejercer su derecho.
7) A modificar la información contenida en el banco de datos, si se trata de información fal
sa, desactualizada o imprecisa.
8) A incorporar en el banco de datos información que tengan como finalidad adicionar una
información cierta pero que por el transcurso del tiempo ha sufrido modificaciones.
9) A incorporar información que tiene como objeto aclarar la certeza de un dato que ha sido
mal interpretado.
10) A incorporar al banco de datos una información omitida que perjudica a la persona.
11) A elim inar de los bancos de datos información sensible que afectan la intim idad perso
nal, fam iliar o cualquier otro derecho fundamental de la persona.
12) A impedir que las personas no autorizadas accedan a una información que ha sido califi
cada como reservada.
13) A que el dato se guarde bajo un código que solo pueda ser descifrado por quien está au
torizado para hacerlo.
14) A impedir la manipulación o publicación del dato en el marco de un proceso, con la fina
lidad de asegurar la eficacia del derecho a protegerse.
15) A solicitar el control técnico con la finalidad de determinar si el sistema informativo, com-
putarizado o no, garantiza la confidencialidady las condiciones mínimas de seguridad de
los datos y su utilización de acuerdo con la finalidad para la cual han sido almacenados.
16) A impugnar las valoraciones o conclusiones a las que llega el que analiza la información
personal almacenada.
7.4.2. Legitimación activa
Solo puede ser ejercida por el afectado, sus tutores o curadores o por sus herederos.
En caso el demandante sea una persona jurídica de derecho privado, interponen la demanda
su representante legal o el apoderado.
Legitimación pasiva.- Son emplazados con la demanda el titu lar o responsable y los
usuarios de bancos de datos, púbicos o privados, destinados o no a proveer información.
7.4.3. Requisitos especiales
Adicional a los requisitos establecidos en el art. 2 del NCPConst. deberá contener: i. El nombre
y dom icilio del archivo, registro o banco de datos y, en su caso, el nombre del responsable o
usuario. En caso de los archivos, registros o bancos públicos, se procurará establecer el orga
nismo estatal del cual dependen, ii. Las razones por las cuales se entiende que en el archivo,
registro o banco de datos individualizado obra información referida al agraviado; los motivos
por los cuales considera que la información que le atañe resulta discriminatoria, falsa, inexac
ta o violatoriade la intim idad personal o familiar.
