l v:" 7.4.4. Trámite del proceso d i Hábeas Data
Etapa precontenciosa
Para la procedencia del hábeas data el demandante previamente debe:
a) Tratándose del derecho reconocido en el artículo 2, inciso 5), de la Constitución, haber
presentado la solicitud de información ante la autoridad administrativa y esta, de
modo tácito o expreso, negado parcial o totalmente la información, incluso si la entre
gare incompleta o alterada.
b) Tratándose del derecho reconocido por el artículo 2, inciso 6), de la Constitución, haber
reclamado por documento de fecha cierta y que el demandado no haya contestado den
tro de los 10 días siguientes o lo haya hecho de forma incompleta o de forma denegatoria
o defectuosa.
En el caso de ambos derechos, de considerarlo el demandante puede optar poracudiral Tribu
nal de Transparencia y Acceso a la Información Pública, debe agotar esta vía previa mediante
resolución expresa o darla por agotada en el supuesto de no obtener resolución dentro del
plazo legal. Si la entidad pública o el titu la r del dato o la información desestima el pedido, el
agraviado puede interponer su demanda de habeas data en el plazo de 60 días hábiles.
El agraviado puede prescindir de la etapa precontenciosa si considera que existe peligro de
daño irreparable en el gocey ejercicio de sus derechos fundamentales.
Etapa contenciosa: La etapa contenciosa se puede resumir en el siguiente esquema.-
