7.2 .6 . Hábeas Data Cifrador.- Tiene como objeto que el dato sea guardado bajo un có
digo que sólo puede ser descifrado por quien está autorizado a hacerlo.
7.2.7. Hábeas Data Cautelar.- Tiene como propósito impedir la manipulación o publi
cación del dato en el marco de un proceso, a fin de asegurar la eficacia del de
recho a protegerse.
7.2 .8 . Hábeas Data Carantista-. Buscan el control técnico en el manejo de los datos,
a fin de determinar si el sistema informativo, computarizado o no, garantiza
la confidencialidady las condiciones mínimas de seguridad de los datos y su
utilización de acuerdo con la finalidad para la cual han sido almacenados.
7.2.9. Hábeas Data Interpretativo-. Tiene como objeto impugnar las valoraciones o con
clusiones a las que llega el que analiza la información personal almacenada.
7.2 .7 0 . Hábeas Data Indemnizatorio-, Aunque no es de recibo en nuestro ordenamien
to, este tipo de hábeas data consiste en solicitar la indemnización por el daño
causado con la propalación de la información.
2 . HÁBEAS DATA IMPURO: Solicitar el auxilio jurisdiccional para recabar una información
pública que le es negada al agraviado.
2 . 7. Hábeas Data de Acceso a Información Pública: Consiste en hacer valer el derecho de toda
persona a acceder a la información que obra en la administración pública, salvo las
que están expresamente prohibidas por la ley.
Aunque el Código hace una relación de los posibles casos de acumulación objeti
va, las pretensiones en el hábeas data no tienen porqué entenderse como limitadas
a los casos que establece la ley. Hay posibilidad de extender su alcance protector a
otras situaciones o alternativas que pudiesen darse en la realidad. La propuesta del
artículo 6i° es simplemente enunciativa.
7.5. El proceso de cumplimiento
Procede contra la abstención administrativa por omisión o por inactividad material y como tal
procede contra cualquier autoridad o funcionario renuente a acatar una norma legal o un acto
administrativo, sin perjuicio de las responsabilidades de ley. Esta acción está destinada a pedir
el cumplim iento de un acto administrativo o de una ley, en la medida que tal incumplimiento
cause perjuicio.
Lo puede presentar el mismo afectado o cualquier otra persona en su nombre, si el juez com
prueba que efectivamente aquéllas se han producido, ordena que la autoridad demandada
cumpla lo dispuesto por la leyó lo prescrito por el acto administrativo.
“El objeto de este tipo de procesos será ordenar que el funcionario o autoridad pública renuente:
i) dé cumplimiento, en cada caso concreto, a una norma legal, o ejecute un acto administrativo firme-, o z) se
pronuncie expresamente cuando las normas legales le ordenan emitir una resolución o dictar un reglamen
to. En ambos casos, el Tribunal Constitucional considera que para la procedencia del proceso de
