I cumplimiento, además de acreditarse la renuencia del funcionario o autoridad pública, deberán
tenerse en cuenta las características mínimas comunes del mandato de la norma legal, del acto
administrativo y de la orden de emisión de una resolución o de un reglamento, a fin de que el
proceso de cumplimiento prospere, puesto que de no reunir tales características, además de los
supuestos contemplados en el artículo 70odel Código Procesal Constitucional, la vía del referido
proceso no será la idónea.” (STC Exp. N °o i68-2005-AC/TC Pj.12).
7.5.1. Requisitos comunes de la norma legal y acto adm inistrativo
Conforme a la STC Exp. N °0i 68- 2005-AC/TC. Fj.14» “para que el cumplimiento de la norma legal,
la ejecución del acto administrativo y la orden de emisión de una resolución sean exigióles a tra
vés del proceso de cumplimiento, además de la renuencia del funcionario o autoridad pública, el
mandato contenido en aquellos deberá contar con los siguientes requisitos mínimos comunes:
a) Ser un mandato vigente.
b) Ser un mandato cierto y claro, es decir, debe inferirse indubitablemente de la norma legal
o del acto administrativo.
c) No estar sujeto a controversia compleja ni a interpretaciones dispares,
d) Ser de ineludibley obligatorio cumplimiento.
e) Ser incondicional. Excepcionalmente, podrá tratarse de un mandato condicional, siem
pre y cuando su satisfacción no sea compleja y no requiera de actuación probatoria.
Adicionalmente, para el caso del cumplimiento de los actos administrativos, además de
los requisitos mínimos comunes mencionados, en tales actos se deberá:
f) Reconocer un derecho incuestionable del reclamante,
g) Permitir individualizar al beneficiario.’’
7.5.2. Trámite dei Proceso de Cumplimiento
1. El trám ite es el aplicado para el Proceso de Amparo.
2. La Legitimación activa recae en: a) cualquier persona frente a normas con rango de ley y
reglamentos; b) en la persona favorecida o interesado respecto del cumplim iento de acto
administrativo; y, c) cualquier persona o Defensoría del Pueblo respecto de derechos con
intereses difusos colectivos.
3. La Legitimación Pasiva recae en la autoridad o funcionario renuente.
4. Causales de improcedencia: No procede el proceso de cumplimiento:
Contra las resoluciones dictadas por el Poder Judicial, el Tribunal Constitucional y el
Jurado Nacional de Elecciones;
Contra el Congreso de la República para exigir la aprobación o la insistencia de una ley;
Para la protección de derechos que puedan ser garantizados mediante los procesos
de amparo, hábeas data y hábeas corpus;
Cuando se interpone con la exclusiva finalidad de impugnar la validez de un acto
administrativo;
