7.6. El Proceso de Inconstitucionalidad
7.6.1. Definición
Es un proceso constitucional especial que se entabla ante el Tribunal Constitucional. Es especial
no sólo porque se entabla ante un organismo suigenemy de alto nivel, sino también por su objeto.
El objeto de la acción de inconstitucionalidad es efectuar la valoración de una ley o norma con
rango de ley de conformidad con la Constitución, ya sea por la forma o por el fondo. Se trata,
pues, de un juicio abstracto de constitucionalidad de la norma, en el cual, debido a su propia
naturaleza, no se faculta al Tribunal Constitucional a evaluar las afectaciones subjetivas
derivadas de la supuesta aplicación de la norma inconstitucional, sino, única y exclusiva
mente, a cum plir la función de eficacia integradora de la unidad constitucional, sea mediante la
expulsión de la norma inconstitucional del sistema jurídico o a través de la interpretación de
conformidad constitucional, cuando sea el caso. (STC Exp. N°003-2004-AIC/TC. Fj. 4).
7.6.2. Finalidad
La finalidad del proceso de inconstitucionalidad es la defensa de la Constitución en su con
dición de Ley Superior. Ella ostenta el máximo nivel normativo, por cuanto es obra del Poder
Constituyente; reconoce los derechos fundamentales del ser humano; contiene las reglas bá
sicas de convivencia social y política; además de creary regular el proceso de producción de las
demás normas del sistema jurídico nacional.
El proceso de inconstitucionalidad defiende la Constitución frente a las infracciones contra su
jerarquía normativa. La validez en materia de justicia constitucional es una categoría relaciona-
