compatible formal y materialmente con la norma superior25.
7.6.3. Normas objeto de control
El art. 200 inc. 4) de la Constitución y el art. 76 del Nuevo Código Procesal Constitucional se-
ñalan que el proceso de inconstitucionalidad procede contra las normas que tienen rango de
ley: leyes, decretos legislativos, decretos de urgencia, tratados que hayan requerido o no la
aprobación del Congreso conforme a los artículos 56 y 57 de la Constitución, Reglamento del
Congreso, normas regionales de carácter general y ordenanzas municipales. Que contraven
gan la Constitución en la forma o en el fondo.
Aparte de lo previsto en las normas mencionadas, el Tribunal Constitucional ha precisado su
competencia contra26:
Las leyes de reforma constitucional, es posible asignar a tales leyes la calidad de fuentes
normativas susceptibles de control de validez, debido a que, si bien es cierto que la Cons
titución es creación de un Poder Constituyente, también lo es que las leyes de reforma
constitucional son creación de un Poder Constituyente Constituido y, consecuentemente,
restringido en su actuación por los límites jurídicos contemplados con antelación por la
fuente que lo constituye27.
- Decretos Leyes28. Temas: Seguridad Social, sanciones penales agravas, PNP, legislación an
titerrorista.
- Normas conexas, la declaratoria de inconstitucionalidad no se restringe únicamente a
los preceptos derivados de la misma norma cuestionada, que haya sido materia del con
tradictorio, sino que se extiende a aquellas otras normas que se encuentren ligadas por
conexión o consecuencia, aún cuando ello no haya sido materia del petitorio29.
La lista de normas contempladas en el artículo 200o inc. 4 de la Constitución, como suscepti
bles de ser impugnadas en un proceso de inconstitucionalidad, tiene un carácter estrictamen
te enunciativo, mas no taxativo.
7.6.4. Motivos para declarar una norma como inconstitucional, por el fondo o por la forma
En un proceso de inconstitucionalidad un norma puede ser declarada contraria a la Constitu
ción, por razones de forma o fondo, así lo establece la manera expresa del Art. 200, inc. 4 de la
Constitución. El Nuevo Código Procesal Constitucional aborda ese tema en el Art.74 y estable
ce al respecto: “Los procesos de acción populary de inconstitucionalidad tienen por finalidad la
defensa de la Constitución y, en su caso, de la ley, frente a infracciones contra su jerarquía nor-
