forma como por el fondo. Por contravenir el artículo 106 de la Constitución, se puede demandar
la inconstitucional idad, total o parcial, de un decreto legislativo, decreto de urgencia o ley que
no haya sido aprobada como orgánica, si dichas disposiciones hubieren regulado materias re
