Finalmente debemos mencionar que si una demanda de inconstitucionalidad contra una
norma es desestimada por razones de forma, eso no impide cuestionarla posteriormente por
razones de fondo.
7.6.5. Legitim idad
Están facultados para interponer acción de inconstitucionalidad (Art. 203 Const.):
1. - El Presidente de la República;
2. - El Fiscal de la Nación;
3. - El Defensor del Pueblo;
4. - El 25% del número legal de congresistas;
5. - 5000 ciudadanos con firmas comprobadas por el ]NE. Si la norma es una ordenanza m uni
cipal, está facultado para impugnarla el 1% de los ciudadanos del respectivo ámbito territo
rial, siempre que este porcentaje no exceda del número de firmas anteriormente señalado;
6 . - Los presidentes de Región con acuerdo del Consejo de Coordinación Regional, o los alcaldes
provinciales con acuerdo de su Concejo, en materias de su competencia.
7. - Los colegios profesionales, en materias de su especialidad.
7.6.6. Órgano encargado del control de constitucionalidad
La demanda de inconstitucionalidad se interpone ante el Tribunal Constitucional, éste es el
órgano encargado del Control de la Constitucionalidad, para lo cual está revestido de inde
pendencia en relación con los otros órganos constitucionales y se encuentra sometido úni
camente a la Constitución y a su ley orgánica. El Tribunal Constitucional tiene como tareas la
racionalización del ejercicio del poder, vela por la preeminencia del texto fundamental de la
República sobre el resto de las normas del ordenamiento jurídico del Estado, se encarga de
velar por el respeto y la protección de los derechos fundamentales de la persona, ejerce la
tarea de intérprete supremo de los alcances y contenidos de la Constitución. Se convierte en
una especie de “guardián de la Constitución”, que actúa como satélite que circunda a los pode
res del Estado y que va a procurar que la actividad estatal se ejercite en armonía con el poder
constituyente, del cual es tributario.
7.6.7. Trámite del Proceso de Inconstitucionalidad
Etapa postulatona o expositiva: Se da con la presentación de la demanda que contiene la preten
sión de inconstitucionalidad de una norma con rango de ley. También denominada inform ati
va, es aquella que se desarrolla desde el ejercicio del derecho de acción, con la interposición de
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 120 of 1506 --

UBILEX
la demanda de manera expresa con las pretensiones que contenga, con el objeto de Integrar
la relación jurídica procesal.30
Etapa probatoria: En este proceso no existe la etapa probatoriaya que se trata de un proce
so de puro derecho al confrontarse una norma con rango de leyy la Constitución, además,
es principio que el derecho nacional no es objeto de prueba; en todo caso, sería una etapa
de exposición de argumentos.
Etapa conclusiva: Se realizan los alegatos y conclusiones sobre todo .lo actuado en el proce
so.
Etapa resolutoria.- Expedición de la sentencia o decisión judicial de la pretensión.
Etapa de ejecución: Cumplimiento de la decisión judicial. Usualmente no hay etapa impug
nativa en este tipo de proceso. También llamada ejecutiva por Nerio Gonzales Linares,
quien dice que, como consecuencia de la conclusión de la etapa decisoria del proceso, se
tiene la declaración jurisdiccional final (sentencia firme) en consecución del fin persegui
do por el actor.
En algunos casos en esta etapa del proceso se puede llegar al cumplim iento coactivo o
forzoso de la sentencia.
La nueva Constitución amplía la base de legitimados para iniciar el proceso de ¡nconsti-
tucionalidad. Otro aspecto positivo que prevé la Constitución es que por el sólo mérito
de la publicación de la sentencia que declara la inconstitucionalidad de una norma, esta
