7.6.8. Control constitucional de normas derogadas
Si, durante la tramitación del proceso de inconstitucionalidad, las normas impugnadas fueran
derogadas, el Tribunal Constitucional continuará con la tramitación del proceso en la medida
en que estas continúen siendo aplicables a los hechos, situaciones o relaciones producidas
durante su vigencia.
7.6.9. Tipos de sentencias de inconstitucionalidad
La doctrina ha establecido una doble clasificación: la primera distingue entre sentencias de
especie o de principio,y la segunda entre sentencias estimativas o desestimativas3132.
31 PACORI CARI, José María. Manual operativo del Nuevo Código Procesal Constitucional. Ubi Lex Asesores. 2021. Lima. p. 199.
32 STC Exp. N.° 004-2004-CC/TC. Fjs. 2-4.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 122 of 1506 --

UBILEX
a) Las sentencias de especie se constituyen por la aplicación simple de las normas constitu
cionales y demás preceptos del bloque de constitucionalidada un caso particulary concre
to. En este caso, la labor del juez constitucional es meramente “declarativa" ya que se limita
a aplicar la norma constitucional o los otros preceptos directamente conectados con ella.
b) Las sentencias de principio son las que forman la jurisprudencia propiamente dicha, porque
interpretan el alcancey sentido de las normas constitucionales, llenan las lagunas y forjan ver
daderos precedentes vinculantes. En cuanto a estas últimas, el Tribunal Constitucional perua
no ha dictado diversas sentencias emitidas en los Exps. N °0 0 0 8 -2 0 0 3 -AI/TCy N °o i8-2003-AI/
TC, que llamaremos “instructivas", y que se caracterizan por realizar, a partir del caso concreto,
un desarrollo jurisprudencial y doctrinario de los temas más importantes en discusión. Este
tipo de sentencias se justifican porque tienen como final idad orientar a los jueces con criterios
que puedan utilizar en la interpretación constitucional que realicen en los procesos a su cargo
y, además, porque contribuye a que los ciudadanos ejerciten mejor sus derechos.
A. Las sentencias estimativas, son aquellas que declaran fundada una demanda de incons-
titucionalidad. Su consecuencia jurídica específica la eliminación o expulsión de la norma
cuestionada del ordenamiento jurídico, mediante una declaración de invalidez constitu
cional. En dicha hipótesis, la ¡nconstitucionalidadse produce por la colisión entre el texto
de una leyó norma con rango de ley y una norma, principio o valor constitucional.
Las sentencias estimativas pueden ser:
1. Las sentencias de simple anulación: En este caso el órgano de control constitucional resuel
ve dejar sin efecto una parte o la integridad del contenido de un texto. La estimación es
parcial cuando se refiere a la fracción de una ley o norma con rango de ley (un artículo,
un párrafo, etc.); y, por ende, ratifica la validez constitucional de las restantes disposi
ciones contenidas en el texto normativo impugnado. La estimación es total cuando se
refiere a la plenitud de una ley o norma con rango de ley; por ende, dispone la desapa
rición íntegra del texto normativo impugnado del ordenamiento jurídico.
2 . Las sentencias interpretativas propiamente dichas-. En este caso el órgano de control cons
titucional, según sean las circunstancias que rodean el proceso constitucional, declara
la inconstitucionalidad de una interpretación errónea efectuada por algún operador
judicial, lo cual acarrea una aplicación indebida.
3. Las sentencias interpretativas-manipulativas (normativas): En este caso el órgano de con
trol constitucional detecta y determina la existencia de un contenido normativo in
constitucional dentro de una ley o norma con rango de ley. La elaboración de dichas
sentencias está sujeta alternativa y acumulativamente a dos tipos de operaciones:
la o b la tiv a y la re constructiva La operación ablativa o de exéresis consiste en reducir
los alcances normativos de la ley impugnada “eliminando” del proceso interpretativo
alguna frase o hasta una norma cuya significación, colisiona con la Constitución. La
operación reconstructiva o de reposición consiste en consignar el alcance normativo
de la ley impugnada “agregándosele” un contenido y un sentido de interpretación
que no aparece en el texto por sí mismo.
Existe una pluralidad de sentencias manipulativo-interpretativas; a saber:
