Tema 4: Teoría general de la Constitución
i. Sentencias reducto ras: Son aquellas que señalan que una parte (frases, palabras,
líneas, etc.) del texto cuestionado es contraria a la Constitución, y ha generado
un vicio de inconstitucionalidad por su redacción excesiva y desmesurada.
ii. Sentencias aditivas-. Son aquellas en donde el órgano de control de la constitucio-
nalidad determina la existencia de una inconstitucionalidad por omisión legis
lativa. En ese contexto procede a “añadir” algo al texto incompleto, para transfor
marlo en plenamente constitucional.
iii. Sentencias sustitutivas: Son aquellas en donde el órgano de control de la cons-
titucionalidad declara la inconstitucionalidad parcial de una ley y, simultánea
mente, incorpora un reemplazo o relevo del contenido normativo expulsado del
ordenamiento jurídico.
iv. Sentencias exhortativas: Son aquellas en donde el órgano de control constitu
cional declara la incompatibilidad constitucional de una parte o la totalidad
de una ley o norma con rango de ley, pese a lo cual no dispone su inmediata
expulsión del ordenamiento constitucional, sino que recomienda al Parlamen
to para que, dentro de un plazo razonable, expida una ley sustitutoria con un
contenido acorde a las normas, principios o valores constitucionales. Al respec
to, deben mencionarse las sentencias emitidas en los Expedientes Acumulados
N.os001/003-2003-AI/TC, en donde se exhorta al Poder Ejecutivo para que, en
salvaguarda del principio de seguridad jurídica que debe informar al Sistema
Registral, reglamente el uso del formulario registral legalizado por notario, pre
visto en el segundo párrafo del artículo T de la Ley N.° 27755; o la sentencia del
Expediente N.° 022-2003-AI/TC, en donde se exhorta a la autoridad competente
y a los Poderes del Estado involucrados a asumir las funciones que, conforme al
artículo 102o, inciso 7°de la Constitución y a las normas de desarrollo, le corres
ponde en materia de delimitación territorial, especialmente en lo que respecta
a la controversia suscitada por los límites territoriales de la Isla Lobos de tierras,
que genera un conflicto entre los gobiernos regionales de Lambayequey Piura.
v. Sentencias estipulativas: Son aquellas en donde el órgano de control de la cons-
titucionalidad establece, en la parte considerativa de la sentencia, las variables
conceptuales o terminológicas que utilizará para analizary resolver una contro
versia constitucional. En ese contexto, se describirá y definirá en qué consisten
determinados conceptos.
B. Las sentencias desestimativas, son aquellas que declaran, según sea el caso, inadmisibles,
improcedentes o infundadas las acciones de garantía, o resuelven desfavorablemente las
acciones de inconstitucionalidad. En este último caso, la denegatoria impide una nueva in
terposición fundada en idéntico precepto constitucional (petición parcial y específica referi
da a una o varias normas contenidas o en una ley); además, el rechazo de un supuesto vicio
formal no obsta para que esta ley no pueda ser cuestionada ulteriormente por razones de
fondo. Ahora bien, la praxis constitucional reconoce una pluralidad de formas y contenidos
sustantivos de una sentencia desestimativa, a saber: la desestimación por rechazo simpley
la desestimación por sentido interpretativo (interpretación estrictu sensu).
