UBILEX
7.6.10. Efectos de la sentencia
Las sentencias dictadas en un proceso de inconstitucional idad tienen efecto vinculante para to
dos los poderes públicos, vinculación que, por sus alcances generales, se despliega hacia toda la
ciudadanía. En tal sentido, en el supuesto de que alguna autoridad o persona, pretenda desco
nocer sus efectos vinculantes, resultará de aplicación el artículo 22o del CPConst33, en el extremo
que dispone que para el cumplimiento de una sentencia el juez podrá hacer uso de multas fijas
acumulativas (STC Exp. N° 0020-2005''PI/TCy 0021-2005--PI/TC (acumulados). Fjs. 156-159).
A contracorriente de lo que ocurre en los casos de la jurisdicción difusa en donde la sentencia
afecta únicamente a las partes en litigio; en el caso de la inconstitucionalidad, es de caráctererga
omnes, es decir, generalizada, de alcance global,y vinculante a todos los poderes públicos.
7.7. ES Proceso de Acción Popular
7.7.1. Definición
El artículo 200o inc. 5) de la Constitución Política de 1993 incluye dentro de las garantías consti
tucionales a la Acción Popular, la cual procede contra los reglamentos, normas administrativas
y resoluciones y decretos de carácter general, cualquiera sea la autoridad de la que emanen,
por infracción de la Constitución y de la ley. En el ámbito doctrinario, César Landa señala que
“La Acción Popular está estrechamente ligada a la acción de inconstitucionalidad de las leyes,
en la medida que su objeto también es asegurar el orden constitucional objetivo, además del
legal, pero examinando las normas inferiores a la ley".
En definitiva, el proceso de Acción Popular constituye un mecanismo de control concentrado délas
normas reglamentarias, que es ventilado exclusivamente al interior del Poder judicial, y que pre
senta como objetivos el de velar por la defensa del artículo 51o de la Carta Magna (el cual prescribe
que “La Constitución prevalece sobre toda norma legal; la ley sobre las normas de menorjerarquía,
y así sucesivamente"), y el artículo 118o inciso 8) del mismo texto normativo (que considera dentro
de las atribuciones del Presidente de la República la de “Ejercer la potestad de reglamentar las leyes
sin transgredirlas ni desnaturalizarlas; y dentro de tales límites, dictar decretosy resoluciones”).
Así, la Acción Popular es el remedio para defender la constitucionalidady legalidad frente a las
normas administrativas que la contradicen; es decir, es un medio de control constitucional y legal
de tipo jurisdiccional sobre normas inferiores como son las de nivel administrativo. La controversia
en una Acción Popular constituye una discusión de puro derecho, en el que debe determinarse si
la norma de inferior jerarquía contraviene la Constitución o la ley. Los efectos de la sentencia no son
particulares, sinogenerales, es decir, su ámbito de vigencia es para un colectivoy no una determinada persona.
7.7.2. Finalidad
Es un proceso constitucional que tiene como finalidad que las normas jurídicas de jerarquía
inferiora la ley no contravengan a la Constitución o a la ley.
7.7.3. Normas objeto de control
El proceso de acción popular procede contra los reglamentos, normas administrativas y re
soluciones de carácter general, cualquiera que sea la autoridad de la que emanen, siempre
