7.7.4. Órgano competente
El Art. 84 del NCPConst. precisa que las Salas Superiores serán los órganos competentes para
tram itar la demanda de acción popular. Así, son competentes:
La Sala Constitucional de la Corte Superior del Distrito Judicial al que pertenece el órgano
emisor, cuando la norma objeto de la acción populares de carácter regional o local; y si no
existiese, la Sala a cargo de los procesos civiles.
En los demás casos, la Sala Constitucional de la Corte Superior de Lima; y si no existiese, la
Sala a cargo de los procesos civiles.
7.7.5. Legitimidad.- La demanda de acción popular puede ser interpuesta porcualquier persona.
