Según Faúndez Ledesma, los Derechos Humanos son ante todo prerrogativas que, conforme
al Derecho Internacional, tiene todo individuo frente a los órganos del poder para preservar su
dignidad como ser humano, y cuya función es excluir la interferencia del Estado en áreas es
pecíficas de la vida individual o asegurar la protección de determinados servicios por parte del
Estado, para satisfacer sus necesidades básicas; y que reflejan las exigencias fundamentales
que cada ser humano puede form ulara la sociedad de que forma parte.
Para Pérez Luño; es el conjunto de facultades e instituciones que en cada momento histórico,
concretan las exigencias de la dignidad, la libertad y la igualdad humanas, las cuales deben
ser reconocidas positivamente por los ordenamientos jurídicos a nivel nacional e internacio
nal.
I . ORIGEN
El reconocimiento y respeto de los derechos humanos es producto de un proceso histórico
cuyos orígenes se remontan a los primeros siglos de la humanidad, pero que se formalizan en
el siglo XX luego de las dos guerras mundiales, llevando a los países que estuvieron envueltos
en estos conflictos a ponerse de acuerdo en el respeto a ciertos aspectos de la vida de las perso-
nasy las sociedades. En este proceso histórico, algunos derechos se fueron reconociendo antes
que otros, y esto supuso la lucha de personas y organizaciones sociales.
2.. DESARROLLO HISTÓRICO
1.1. La evolución de los Derechos Humanos, va unida a la fundamentación filosófica de los
mismos. Ésta se encuentra entre dos grandes corrientes del pensamiento: el Derecho Na
tural o lusnaturalismoy el Positivismo Jurídico.
Para el Derecho Natural, el Derecho está constituido “por un conjunto de valores y prin
cipios de naturaleza universal, inmutable, irrenunciable e imprescriptible que prevalece
ante cualquier contenido que hayan asumido las normas jurídicas a través del tiempo.
Las normas derivan de la voluntad divina o de la naturaleza de las cosas, a las que la razón
y la convivencia humana deben someterse. Bajo esta premisa, los derechos del hombre
son anteriores y superiores al del Estado, y no requieren de una norma específica para su
vigencia.
En la Edad Moderna, puede citarse como uno de los principales exponentes a John Locke,
para quien el verdadero estado del hombre no es el estado civil, sino el natural, aquel
donde los hombres son libres e iguales, “siendo el estado civil una creación artificial que
no tiene más objeto que permitir el más amplio desenvolvimiento de la libertad e igual
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 128 of 1506 --

UBILEX
dad naturales”. Esta concepción, inspiró luego a los redactores de la declaración de In
dependencia de los Estados Unidos y también a los enciclopedistas franceses (Voltaire,
Montesquieuy Rousseau), de gran trascendencia en la Declaración de los Derechos del
Hombrey del Ciudadano.
Siguiendo esta línea, la concepción de Rousseau, se basa en que los hombres pasan del
estado primitivo al estado social, mediante un contrato en el cual renuncian a parte de
sus derechos naturales, al tiempo que conservaban algunos de sus derechos fundamen
tales: derecho a la vida, a la libertad y a la igualdad, los que constituían hechos eternos
e inalienables que todo sistema social y estatal estaba obligado a respetar. Es la teoría
contractual basada en la ley natural.
La fundamentación positivista, propone un fundamento racional de los derechos que no
es moral y son varias tesis, entre ellas, el fundamento de los derechos está en el derecho positivo
estatal e internacional (al margen de que se admita o se rechace que el ordenamiento legal
pueda estar impregnado de valores morales indeterminados), y aquella en que el funda
mento de los derechos consiste en el interés (individual o social).
En la evolución histórica de los derechos humanos, también debe considerarse la etapa
de las Cartas inglesas, inaugurada con la Carta Magna de 1215, y complementada poste
riormente con la Petition of Rights de 1628, el Habeas Corpus Act de 1640 y 1679; y el Bill
of Rights de 1689.
La Carta Magna de 1215, es el documento histórico que los señores feudales, la nobleza y el
Clero, obligaron asuscribiral Reyjuan Sin Tierra. No es una ley, sino un Pacto entre el Reyy
los hombres libres (que no eran todos los hombres, sino los antes mencionados). Este ins
trumento reconoce un conjunto de libertades (libertad individual, seguridad personal, libre
comercio y derecho a la propiedad); y en su artículo 39 contiene reglas de derecho procesal
y otras relacionadas con la administración de justicia, que es el germen del debido proceso.
La Petition o f Rights de 1628, fue adoptada por el Parlamento, en tono sumiso frente a la
Monarquía, pero logró consagrar diversos derechos, ampliándose de esta manera duran
te el reinado de Carlos I de Inglaterra, los principios de la Carta Magna.
El Habeas Corpus Amendment Act de 1679, se dio para impedir toda detención arbitraria,
constituyéndose en una garantía específica de la libertad personal de los ingleses. Si bien
no es la primera ley del Parlamento sobre la materia, (puesya había una ley anterior-, Ha
beas Corpus Act de 1640); sin embargo, constituye la primera disposición que regula con
eficacia los procedimientos de protección de esta garantía de los ciudadanos ingleses. Se
hace esta afirmación, porque con anterioridad a su promulgación, la Corona y sus fun
cionarios disponían de varios resortes para enfrentarse a los fines de un Hábeas Corpus:
posibilidad de que la autoridad causante de la detención se negara a obedecer el writ, la
práctica de trasladar de prisión en prisión al detenido a fin de no dar respuesta al writ,
entre otros.
El Bill of Rights de 1689, constituye una declaración de derechos más moderna que la Peti
ción de Derechos de 1628, significó el reconocimiento por parte de laM onarquia.de dere
chos y libertades de los ingleses, pues el Rey tuvo que jurar ante el Parlamento.
