5. OBLIGACIONES ASUMIDAS POR EL ESTADO
U n a d e la s c a r a c t e r ís t ic a s d e los t r a t a d o s d e d e r e c h o s h u m a n o s es s u c a r á c t e r no s in a la g
m á t ic o , e sto es q u e a d if e r e n c ia d e lo s o tro s t r a ta d o s , los Estados asumen obligaciones
no en relación con otros Estados sino hacia los individuos bajo su jurisdicción.
Los t r a t a d o s d e d e r e c h o s h u m a n o s t ie n e n u n a v o c a c ió n p r o g r e s iv a o d e d e s a r r o llo . Esto
s ig n if ic a q u e los derechos reconocidos en el catálogo constituyen un estándar mínimo
que se exige al Estado.
"Las obligaciones del Estado en materia de derechos humanos implican el respeto y garantía
^ de los derechos fundamentales de las personas sometidas a su jurisdicción. Estas obligaciones
¡ han quedado enunciadas expresamente por el artículo 2° del Pacto Internacional de Derechos
■■ ■ civiles y Políticos, y los artículos V y 2° de la Convención Americana sobre Derechos Huma-
H H H nos. Estas normas internacionales constituyen, por ende, pauta interpretativa mandatoria de
V;**™ ™ ® lo dispuesto en el artículo 44. De la Constitución; vale decir, la obligación que tiene el Estado
de garantizar la plena vigencia de los derechos humanos". STC Exp. N° 4677-2005-PHC/TC, Caso
Juan Notberto Rivero Lazo. Fj. 13.
