Tema 5: Derechos Humanos
7. TRATAMIENTO DE DELITOS DE LESA HUMANIDAD (CORTE PENAL INTERNACIO
NAL)
A c t u a lm e n t e e x is te u n a d e f in ic ió n d e l c o n c e p t o d e c r im e n d e le s a h u m a n id a d . E ll a s e e n c u e n -
t r a e n el art. 7 0 d e l E s ta tu to d e la C o rte P e n a l In t e r n a c io n a l, t a m b ié n c o n o c id o c o m o el “E s t a t u
to d e R o m a ” (q u e e n t ró en v ig o r p a ra el E s ta d o p e r u a n o e h d e j u li o d e 2 0 0 2 ) , el c u a l e s t a b le c e
lo s ig u ie n t e :
■ p T T y . "1. A tos efectos de! presente Estatuto, se entenderá por “crimen de lesa humanidad" cualquiera de
los actos siguientes cuando se cometa como parte de un ataque generalizado o sistemático contra
J f k J una población civil y con conocimiento de dicho ataque:
a) Asesinato;
b} Exterminio;
c) Esclavitud;
d) Deportación o traslado forzoso de población;
e) Encarcelación u otra privación grave de la libertad física en violación de normas fundamentales de derecho
internacional;
f) Tortura;
g) Violación, esclavitud sexual, prostitución forzada, embarazo forzado, esterilización forzada u otros abusos
sexuales de gravedad comparable;
h) Persecución de un grupo o colectividad con identidad propia fundada en motivos políticos, raciales, na
cionales, étnicos, culturales, religiosos, de género definido en el párrafo 3, u otros motivos universalmente
reconocidos como inaceptables con arreglo al derecho internacional, en conexión con cualquier acto men
cionado en el presente párrafo o con cualquier crimen de la competencia de la Corte;
i) Desaparición forzada de personas;
j) El crimen de apartheid;
k) Otros actos inhumanos de carácter similar que causen intencionalmente grandes sufrimientos o atenten
gravemente contra la integridad física o la salud mental o física."
2. A los efectos del párrafo 1:
a) Por “ataque contra una población civil” se entenderá una línea de conducta que implique la comisión múl
tiple de actos mencionados en el párrafo 1 contra una población civil, de conformidad con la política de un
Estado o de una organización de cometer esos actos o para promover esa política;
b) El “exterminio" comprenderá la imposición intencional de condiciones de vida, la privación del acceso a
alimentos o medicinas entre otras, encaminadas a causar la destrucción de parte de una población;
c) Por "esclavitud" se entenderá el ejercicio de los atributos del derecho de propiedad sobre una persona, o
de algunos de ellos, incluido el ejercicio de esos atributos en el tráfico de personas, en particular mujeres y
niños;
d) Por "deportación o traslado forzoso de población" se entenderá el desplazamiento de las personas afecta
das, por expulsión u otros actos coactivos, de la zona en que estén legítimamente presentes, sin motivos
autorizados por el derecho internacional;
e) Por "tortura" se entenderá causar íntencionalmente dolor o sufrimientos graves, ya sean físicos o men
tales, a una persona que el acusado tenga bajo su custodia o control; sin embargo, no se entenderá por
tortura el dolor o los sufrimientos que se deriven únicamente de sanciones lícitas o que sean consecuencia
normal o fortuita de ellas;
f) Por "embarazo forzado" se entenderá el confinamiento ilícito de una mujer a la que se ha dejado emba
razada por la fuerza, con la intención de modificar la composición étnica de una población o de cometer
. otras violaciones graves del derecho internacional. En modo alguno se entenderá que esta definición afec
ta a las normas de derecho interno relativas al embarazo;
g) Por "persecución" se entenderá la privación intencional y grave de derechos fundamentales en contraven
ción del derecho internacional en razón de la identidad del grupo o de la colectividad;
h) Por "el crimen de apartheid" se entenderán los actos inhumanos de carácter similar a los mencionados en
el párrafo 1 cometidos en el contexto de un régimen institucionalizado de opresión y dominación sistemá
ticas de un grupo racial sobre uno o más grupos raciales y con la intención de mantener ese régimen;
, i) Por "desaparición forzada de personas" se entenderá la aprehensión, la detención o el secuestro de perso-
. ñas por un Estado o una organización política, o con su autorización, apoyo o aquiescencia, seguido de la
negativa a informar sobre la privación de libertad o dar información sobre la suerte o el paradero de esas
personas, con la intención de dejarlas fuera del amparo de la ley por un período prolongado.
3. A los efectos del presente Estatuto se entenderá que el término "género" se refiere a los dos sexos, masculi
no y femenino, en el contexto de la sociedad. El término “género" no tendrá más acepción que la que antecede.
