S e g ú n el T r ib u n a l C o n s t it u c io n a l {5ICE:»p. N 30024-201 o-Pl/TC-Lima. Fj.4 9 - Jurisprudencia
Constitucional Vinculante) “un a c to c o n s t it u y e u n c r im e n d e le s a h u m a n id a d :
a ^ "a) cuando por su naturaleza y carácter denota una grave afectación de la dignidad humana,
j O i | violando la vida o produciendo un grave daño en el derecho a la integridad física o mental de la
víctima, en su derecho a la libertad personal o en su derecho a la igualdad;
b) cuando se realiza como parte de un ataque generalizado o sistemático;
,_____ S c) cuando responde a una política (no necesariamente formalmente declarada) promovida o
consentida por el Estado; d) cuando se dirige contra población civil. Siendo que estas condi
ciones deben presentarse copulativamente,"
Asimismo, el TC "dispuso que los delitos contra la humanidad'', normalmente denominados delitos de lesa hu
manidad, no prescriben en el tiempo en virtud de la Convención sobre la Imprescriptibíiidad de los Crímenes de
Guerra y de los Crímenes de Lesa Humanidad, toda vez que este instrumento establece, en su artículo 1, que los
crímenes señalados “son imprescriptibles, cualquiera que sea la fecha en que se hayan cometido".
