Tema 5: Derechos H um anos
Los Estados miembros de la OEA pueden consultar a la Corte acerca de la interpretación de la
Convención Americana de Derechos Humanos o de otros tratados concernientes a la protec
ción de los derechos humanos en los Estados americanos. Además, pueden consultarla, en los
que les compete, los órganos de la Organización de los Estados Americanos.
Asimismo, la Corte, a solicitud de un Estado miembro de la OEA, puede darle a tal Estado opi
niones acerca de la compatibilidad entre cualquiera de sus leyes internas y los mencionados
instrumentos internacionales.
8 .3 .3 .Sentencias y Opiniones Consultivas de la Corte Interamericana de Derechos Hu
manos
Las opiniones consultivas de la Corte Interamericana de Derechos Humanos tienen, en ge
neral, un valor análogo al que tienen las sentencias de los tribunales internacionales para los
Estados que no han sido partes en el caso sentenciado: si bien no son directamente obligato
rias para ellos, representan una interpretación auténtica del Derecho internacional (en el
caso de la Convención Americana u “otro tratado” sometido a consulta), que, como fuente
auxiliar del mismo, debe ser tenido como norma por Sos Estados americanos para el cum
plimiento de sus obligaciones internacionales.
La Corte ha considerado sus opiniones consultivas, fundadas sobre el artículo 64 de la Conven
ción, como fuente jurisprudencial de Derecho internacional para resolver numerosos casos
contenciosos. Así ha ocurrido, por lo menos, en los siguientes casos contenciosos en los que, al
aplicar el artículo 62 del Pacto de San José, la Corte ha hecho valer criterios de interpretación
nacidos del ejercicio de la función que le atribuye el artículo 64:1) Corte I.D.H.: Caso Velázquez
Rodríguez, Sentencia del 29.07.1988. 2) Caso Codínez Cruz, Sentencia del 20.01.1989, 3) Corte
IDH: Caso Caballero Delgado y Santana. Sentencia de 21.01.1 9 9 4 - 4 ) Corte I.D.H.: Caso Genie Laca
yo. Excepciones Preliminares. Sentencia del 29.01.1995. 5) Corte I.D.H.: Caso Neira Alegría y Otros.
Sentencia de 19.01.1 9 95. 6) Corte IDH: Caso Caballero Delgado y Santana. 7) Corte I.D.H.: Caso
Panlagua Moralesy Otros. Excepciones Preliminares. Sentencia de 25.01.1996. 8) Corte I.D.H: Caso
El Amparo. Reparaciones. Sentencia de 14.09.1996. 9) Corte I.D.H.: Caso Loayza Tamayo. Sentencia
de 17.09.1997.10) Corte I.D.H.: Caso Suárez Rosero. Sentencia de 12.n .19 97. 11) Corte I.D.H.:
