8.4. Convención Americana de Derechos Humanos (CADH)
Llamada también Pacto de San José de Costa Rica, fue suscrita, tras la Conferencia Especiali
zada Interamericana de Derechos Humanos, el 22 de noviembre de 1969 en la dudad de San
José de Costa Rica y entró en vigencia e h 8 de julio de 1978. Es una de las bases del Sistema
¡nteramericano.
Los Estados partes en esta Convención se “comprometen a respetar los derechos y libertades
reconocidos en ellay a garantizar su librey pleno ejercicio a toda persona que esté sujeta a su
jurisdicción, sin discriminación alguna”. Si el ejercido de tales derechos y libertades no estu
viere ya garantizado por disposiciones legislativas o de otro carácter, los Estados partes están
obligados a adoptar medidas legislativas o de otro carácter que fueren necesarias para hacer
los efectivos.
