UBILEX
Además, establece la obligación, para los Estados partes, del desarrollo progresivo de los de
rechos económicos, sociales y culturales contenidos en la Carta de la OEA, en la medida de los
recursos disponibles, por vía legislativa u otros medios apropiados.
Como medios de protección de los derechos y libertades, establece dos órganos para conocer de
los asuntos relacionados con el cumplimiento de la Convención: la Comisión Interamericana de
Derechos Humanos y la Corte Interamericana de Derechos Humanos. Ambas son competentes
para conocer de los asuntos relacionados con el cumplimiento de los compromisos contraídos
por los Estados partes (Artículo 33 de la Convención Americana de Derechos Humanos).
A la fecha, veinticinco naciones Americanas han ratificado o se han adherido a la Convención:
Argentina, Barbados, Bolivia, Brasil, Colombia, Costa Rica, Chile, Dominica, Ecuador, El Salva
dor, Granada, Guatemala, Haití, Honduras, jamaica, México, Nicaragua, Panamá, Paraguay,
Perú, República Dominicana, Suriname, Trinidad y Tobago, Uruguay y Venezuela. Trinidad y
Tobago y Venezuela denunciaron a la Convención Americana sobre Derechos Humanos, el
año 1998 y 20iz, respectivamente.
BALOTARIO DESARROLLADO PARA LOS EXÁM ENES ESCRITOS DE SELECCIÓN
Y N O M B R AM IEN TO DE JUECES Y FISCALES

