Y CONTROL CONVENCION/
1. CONTROL DIFUSO
El Control Difuso es una facultad constitucional concedida a los órganos revestidos de po
testad jurisdiccional para revisar la constitucionalidad de las normas, haciendo prevalecer la
Constitución sobre la leyy ésta sobre cualquier otra norma de rango inferior.
La base del control difuso de constitucionalidad se encuentra en el artículo 138 de la Consti
tución: “En todo proceso, de existir incompatibilidad entre una norma constitucional y una
norma legal, los jueces prefieren la primera. Igualmente, prefieren la norma legal sobre toda
otra norma de rango inferior.”
Al respecto el Tribunal Constitucional (STC Exp. N° 0195-2004-AA/TC, FJ.16) define al control
difuso de constitucionalidad como un poder-deber del juez al que el artículo 138 de la Consti
tución habilita en cuanto mecanismo para preservar el principio de supremacía constitucional
y, en general, el principio de jerarquía de las normas, enunciado en el artículo 51 de nuestra
norma fundamental. El control difuso es un acto complejo en la medida en que significa pre
ferir la aplicación de una norma cuya validez resulta beneficiada de la presunción de legitim i
dad de las normas del Estado.
En el caso peruano el Tribunal Constitucional ha señalado ciertos presupuestos que se debe
advertir a fin de aplicarválidamente el control difuso (STC Exp. 1124-2001 -AA/TC):
a) Que en el proceso constitucional, el objeto de la impugnación sea un acto que constituya
la aplicación de una norma considerada inconstitucional.
b) Que la norma a inaplicarse tenga una relación directa, principal e indisoluble con la resolu
ción del caso.
c) Que la norma a inaplicarse resulte evidentemente incompatible con la Constitución, aun
luego de haberse acudido a interpretarla de conformidad con la Constitución.
Cierto es que en su modelo de origen el Control Difuso solo operaba en el escenario de un pro
ceso judicial concreto y real, por lo que podríamos afirmar que solo son los jueces los faculta
dos de aplicar el Control Difuso, sin embargo, a la fecha esto no es del todo cierto, pues dicha
facultad también lo ostenta el Jurado Nacional de Elecciones, el Tribunal Constitucional y de
más órganos colegiados administrativos con ciertas restricciones.
1.1. Control difuso de convencionalidad
El control de convencionalidad que ejercen los jueces es una obligación derivada de adecuare inter
pretar las normas de derecho interno con los tratados internacionales que el Estado haya suscrito.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R AM IEN TO DE JUECES Y FISCALES 139

-- 140 of 1506 --

UBILEX
La CIDH requiere que todos los órganos estatales realicen el control de convencionalidad, sin
embargo, reconoce que el control jurisdiccional es particularmente importante, pues la pri
mera vertiente del control de convencionalidad (cuando el Estado miembro no ha adecuado
su normativa interna) es justamente el juez, quien ejercerá el control difuso (constitucional
y convencional) para inaplicar la norma interna y hacer vigente el Sistema Interamericano.
Esto se ve reforzado por el desarrollo jurisprudencial que la CIDH ha tenido en el control de
convencionalidad ejercido por el Poder judicial. En esa línea, en el caso de Trabajadores cesa
dos del Congreso (Aguado Al faro y otros) vs. Perú del año 2006, laCIDH enfatizó que el Poder
judicial debía ejercerel control de convencionalidad.1
Esta obligación estaría también contenida en el artículo i.''i. de la Convención Americana,
cuando se establece que los estados deben adoptar medidas legislativas para garantizar el
ejercicio de los derechos. Esta garantía se ve concretizada cuando el derecho interno se ade
cúa, ya sea a través de las medidas propiamente legislativas o a través de la interpretación de
las normas internas de acuerdo al canon internacional. Esta laborde interpretación la realizan
particularmente los jueces en la resolución de casos concretos.2
El derecho interno del Perú se inicia en la Constitución Política, luego continua en la Ley, que
incluye el Decreto Legislativo, la Resolución Legislativa, el Decreto de Urgencia, la sentencia
del Tribunal Constitucional que declara inconstitucional una Ley; posteriormente el Decreto
Supremo, la Resolución Ministerial y así sucesivamente.
El control difuso de convencionalidad entonces nos permite analizar cualquiera de estas nor
mas de derecho interno versus cualquier Convención Internacional de Derechos Humanos así
como su interpretación por un Tribunal Internacional y con ellos recurrir a su inaplicación de
aquellas si es que se les opone.
El primer documento de contraste es el texto de la Convención Americana de Derechos Huma
nos, sin embargo, no es el único parámetro, sino que los jueces (y en realidad todo órgano es
tatal) deberán realizar el control de convencionalidad contrastando con la interpretación que
la CIDH realice de la Convención, como máxima interprete de las normas de la de ésta. Esta
vinculación procede de que: i) el Estado reconoce que la CIDH tiene la competencia máxima
en interpretación de la Convención; y, ii) reconoce su competencia contenciosa y no conten
ciosa desde el momento en que se adscribe como miembro.3
La CIDH también ha establecido que el control de convencionalidad alcanza a otros instru
mentos que conformarían el sistema convencional de derechos humanos. Entre ellos tenemos:
el Protocolo de San Salvador, Protocolo a la Convención Americana sobre Derechos Humanos
relativo a la Abolición de la Pena de Muerte, la Convención Interamericana para Preveniry San
cionar la Tortura, la Convención Interamericana sobre la Desaparición Forzada de Personas, la
Convención Interamericana para Prevenir, Sancionary Erradicar la Violencia contra la Mujer, la
