Tema 6: Control difuso y control convencional
Convención Interamericana para la Eliminación de Todas las Formas de Discriminación contra
las Personas con Discapacidad, la Convención Interamericana contra el Racismo, la Discrimi
nación Racial y Formas Conexas de Intolerancia, la Convención Interamericana contra Toda
Forma de Discriminación e Intolerancia, y la Convención Interamericana sobre la Protección
de los Derechos Humanos de las Personas Mayores.4
2. CONTROL DE CONVENCIONALIDAD
El control de convencionalidad es una técnica jurídica que obliga a los jueces a contrastar el
derecho interno con las disposiciones de la Convención Interamericana de Derechos Huma
nos y lo desarrollado en la jurisprudencia de laCIDH.
El control de convencionalidad se aplicaría tanto a los jueces nacionales como a los de la pro
pia Corte Interamericana, cuando conocen de un caso llevado por una de las partes que no ha
recibido protección en la jurisdicción interna. Podría decirse que el control de convencionali
dad que realizan los jueces interamericanos es subsidiario, puesto que solo podrían intervenir
si tienen un caso concreto y si es que en el caso concreto la jurisdicción nacional no respetó las
normas del Sistema Interamericano. La Constitución Peruana, en su artículo 205 regula que
se acude al Sistema Interamericano, una vez que se agota la jurisdicción interna, “agotada la
jurisdicción interna, el individuo puede recurrir a los tribunales u organismos internacionales
constituidos según tratados o convenios de los que el Perú es parte".
Así, el control de convencionalidad presupone la interrelación de los tribunales nacionales y
los tribunales internacionales en materia de derechos humanos. Y puede darse en dos niveles:
a) Internacional: el control de convencionalidad consiste en juzgaren casos concretos si un
acto o una normativa de derecho interno resulta compatible con la Convención Am eri
cana de Derechos Humanos (en adelante, CADH), disponiendo la reforma, abrogación o
inaplicación de dichas prácticas o normas, según corresponda, en orden a la protección
de los derechos humanosy a la vigencia de tal Convención y de otros instrumentos inter
nacionales en este campo. Igualmente, procede en el supuesto de que el Estado no haya
cumplido con el deber de adoptar disposiciones de derecho interno (art. 2 CADH) para
garantizarel ejercicio de los derechos humanos reconocidos por la Convención. Para ello,
la Corte Interamericana de Derechos Humanos (en adelante, la Corte), por vía jurispru
dencial, impone al Estado a tomar medidas legislativas o de otro carácter para lograr tal
finalidad. Este control puede alcanzar a la normativa en general (leyes, reglamentos, etc.),
y a la Constitución, esto últim o no tan frecuentey con alcances limitados.
b) Interno: esta modalidad se despliega en sede nacional, y se encuentra a cargo de los ma
gistrados locales. Consiste en la obligación de verificar la adecuación de las normas juríd i
cas internas que aplican en casos concretos, a la CADH (y otros instrumentos internacio
nales en el área de los derechos humanos),y a los estándares interpretativos que la Corte
ha formulado a través de su jurisprudencia. Se efectúa una interpretación de las prácticas
internas a la luz o al amparo del corpus m is básico en materia de derechos humanos, y
sobre lo cual la Corte ejerce competencia material, que se expresa en su jurisprudencia.
4 Idem. p. 43.
