Desde este punto de vista, el control de convencionalidad es un principio que, debidamente
empleado, puede contribuir a la aplicación armónica, ordenada y coherente del derecho vi
gente en cada Estado, abarcando sus fuentes internas e internacionales.
2.1. Control de convencionalidad realizado por el Tribunal Constitucional
El Tribunal Constitucional peruano, en su labor especializada y como órgano encargado del
control de la constitucionalidad de las leyes y de conocer en últim a y definitiva instancia los
procesos constitucionales de la libertad, en su uniforme jurisprudencia, a partirde las disposi
ciones de laCADH, ha inaplicado normas de rango legal o actos estatales que la contravienen.
A continuación, veamos alguno de ellos.
- El primero es el referido a la demanda de Amparo presentada por Santiago Enrique Mar
tín Rivas contra el Consejo Supremo de justicia Militar, alegando la vulneración de sus
derechos al debido proceso, a la cosa juzgada, a la amnistía y el principio de seguridad
jurídica.
Señala que en el año 1995 la Sala de Guerra le concedió el derecho de amnistía por los he
chos ocurridos en torno al denominado caso «La Cantuta» (causa 157-V-93)- Dicha medida
fue elevada en consulta a la Sala Revisora de la Justicia Militar, la misma que aprobó el
archivo definitivo del proceso. No obstante, con fecha 17 de octubre de 2001, la deman
dada reabrió el caso y se anuló la ejecutoria que disponía su archivo definitivo y, poste
riormente, desestimó el recurso de nulidad interpuesto por el recurrente. Alega que las
resoluciones emitidas por el Consejo Supremo de Justicia M ilitar contravienen las leyes
de amnistía — ley 26479 y 26492— . Asimismo, agrega que siguiendo la jurisprudencia
emitida por la Corte en el caso «Castillo Petruzzi y otros», debe concluirse que la CADH
no puede suprimir o lim itar el derecho de amnistía otorgado por el Estado peruano; más
aún,si el propioTribunal Constitucional declaró improcedente ladem andadeinconstitu-
cionalidad interpuesta contra diversos artículos de las leyes de amnistía. (STC 679-2005-
PA/TC, Fj. 1 7 -1 8 y 50)
En el segundo se precisa el lugar que ocupan los tratados sobre derechos humanosy la com
petencia contenciosa de la Corte, ratificada por el Estado peruano y la obligación que tienen
los jueces de aplicar en sede nacional las disposiciones de la CADH y los criterios jurispru
denciales establecidos por la Corte, sobre las disposiciones del derecho interno cuando se
vulneren aquellas. (STC01458-2007--PA/TC, F j.2 y 3)
En tercer lugar, tenemos la potestad reconocida a los jueces del Poder Judicial de aplicar
el control difuso en salvaguarda de las normas de derechos fundamentales contenidas en
la CADH, a pesar de que el Tribunal Constitucional haya confirmado la constitucionalidad
de la ley objeto de control difuso, reconociéndose de forma implícita, la prevalencia de
la CADH sobre las normas cuya constitucionalidad haya sido confirmada por el Tribunal
Constitucional, pero que vulneran derechos regulados en la CADH. (STC 01679-2005-PA/
TC, Fj. 9)
Finalmente, existe el caso de Aquilino Carlos Portel la Núñez, quien interpuso una de
manda de Hábeas Corpus para que se le apliquen las leyes de Amnistía. Basaba su de-
