La Teoría General del Proceso es la parte general de la ciencia del Derecho Procesal que se
ocupa del estudio de los conceptos, principios e instituciones que son comunes a las diversas
disciplinas procesales especiales.
1. PRINCIPIOS DEL PROCESO
Principio de exclusividady obligatoriedad de la función jurisdiccional.-- El Estado tiene la exclu
sividad de la administración de justicia, esto es, que tiene el poder- deber de solucionar
la litis. El Poder ] udicial tiene la hegemonía en la administración de justicia, luego de su
perada la autodefensa (solución del conflicto empleando la fuerza o violencia),y al no ser
viable la autocomposición (solución del conflicto reside en el acuerdo de las partes).
El principio de exclusividad de la función jurisdiccional posee dos vertientes: a) exclusi
vidad judicial en su vertiente negativa, según la cual los jueces no pueden desempeñar otra
función que no sea la jurisdiccional, salvo la docencia universitaria; y, b) exclusividad judi
cial en su vertiente positiva, según el cual sólo el Poder Judicial puede ejercer función juris
diccional, salvo el caso de excepciones determinadas por la ley.
Principio de la independencia de los órganos jurisdiccionales.- El principio de independencia ju
dicial debe entenderse desde tres perspectivas; a saber:
a) Como garantía del órgano que administra justicia (independencia orgánica), por su
jeción al respeto al principio de separación de poderes.
b) Como garantía operativa para la actuación del juez (independencia funcional), por
conexión con los principios de reserva y exclusividad de la jurisdicción.
c) Como capacidad subjetiva, con sujeción a la propia voluntad de ejercer y defender
dicha independencia. Cabe precisar que en este ámbito radica uno de los mayores
males de la justicia ordinaria nacional, en gran medida por la falta de convicción y
energía para hacer cumplir la garantía de independencia que desde la primera Cons
titución republicana se consagra y reconoce.
En tal sentido este principio de independencia judicial exige que el legislador adopte las medi
das necesariasy oportunas afín de que el órgano jurisdiccional y los administradores de justi
cia actúen con estricta sujeción al Derechoy a la Constitución, sin quesea posible la injerencia
de terceros al momento de delim itare interpretar parte del ordenamiento jurídico que ha de
aplicarse al caso concreto.
Principio de imparcialidad délos órganos jurisdiccionales-í\ principio de im parcialidad-estre
chamente ligado al principio de independencia funcional-se vincula a determinadas exi-
BALOTARIO DESARROLLADO PARA LOS EXÁM ENES ESCRITOS DESELECCIÓ N
Y N O M B R A M IE N TO DE JUECES Y FISCALES

