Tema 7: Teoría general del proceso
gencias dentro del proceso, definidas como la independencia del juez frente a las partesy
al objeto del proceso mismo, pidien do entenderse desde dos acepciones:
a) Imparcialidad subjetiva, que atañe a algún tipo de compromiso que el juez pueda te
ner con el caso.
b) Imparcialidad objetiva, referida a la influencia negativa que puede tener en el juez la
estructura del sistema, restándole imparcialidad, es decir, si el sistema no ofrece su
ficientes garantías para desterrar cualquier duda razonable.
Principio de contradicción o audiencia bilateral.- El principio de bilateralidad de la audiencia,
o del contradictorio, expresa que, salvo excepciones limitadas, el Juez no podrá actuar su
poder de decisión sobre una pretensión (civil, latosensu o penal) si la persona contra quien
aquella ha sido propuesta no ha tenido oportunidad de ser oída: audiatur et altera pars. Per
mite evitar la arbitrariedad del órgano jurisdiccional ya que éste sólo podrá actuar a mérito
de lo que las partes hayan propuesto en el proceso, teniendo ambas la oportunidad de ser
atendidas en el mismo a través de los distintos actos procesales que introducen al proceso.
Principio de publicidad - Significa que los actos procesales sean presenciados o conocidos
incluso por quienes no participan en el proceso como partes, sean funcionarios o auxi
liares. En materia civil las audiencias serán públicas, a menos que los jueces o tribunales
atendiendo a las circunstancias del caso, dispusieran lo contrario mediante resolución
debidamente fundamentada.
Principio de obligatoriedad de los procedimientos establecidos en la ley- Al respecto GOZAINI se
ñala que: “Cuando las reglas adjetivas señalan el modo de ser de los actos que componen
el proceso, se habla del principio de legalidad de las formas; en oposición a la libertad
de em itir requerimientos, alegaciones y decisiones, sin cum plir recaudo alguno de orden
ritual o simplemente llamado, informalismo.” En ese sentido, debe tenerse en cuenta que
aquellas normas que garantizan el debido proceso, son de orden públicoy por ende de in
eludible cumplimiento, destinadas a garantizar el derecho de las partes durante el trans
curso del proceso e impedir la expedición de sentencias arbitrarias.
Principio de la motivación de las resoluciones judiciales.- Los jueces están obligados a funda
mentar sus decisiones salvo aquellas que son simplemente de impulso procesal. Esta
exigenciatambién se impone a las otras partes del procesoya que deben sustentar todas
las peticiones que formule o las absoluciones que realice a los planteamientos de la otra
parte, así mismo deberán fundamentar los medios inpugnatorios que interponga.
Principio de cosa juzgada - La decisión final que emite un juez en la sentencia, es decir en un
pronunciamiento sobre fondo y cuando ya no exista ningún medio impugnatorio que
cuestione dicha sentencia o que no haya sido impugnada por la parte favorecida adquie
re la calidad de cosa juzgada, es decir que ninguna autoridad puede modificar o alterar
dicha sentencia quedando esta inmutable porel principio de seguridad jurídica.
2. CONDICIONES DE LA ACCIÓN
Son los requisitos procesales que permiten al Juez expedir un pronunciamiento válido sobre
el fondo.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R A M IE N TO DE JUECES Y FISCALES

-- 146 of 1506 --

Las condiciones de la acción son las siguientes:
a) Interés para obrar: Es el interés procesal, existe cuando la persona ha agotado todos los
medios para satisfacer su pretensión material y no tiene otra alternativa que recurrir al
órgano jurisdiccional.
Para que exista necesidad de acudir al órgano jurisdiccional a pedir tutela, es necesario
que se verifiquen las siguientes condiciones:
i) Que el interés sea directo, personal o concreto, que quien requiera del órgano de jus
ticia sea el propio sujetoy no un tercero, porque en ese caso la necesidad no sería de
éste, sino del tercero al que pretende sustituirse, pero también porque la verificación
de la interés para obrar no debe realizarse sobre un juicio abstracto, sino vinculado al
caso concreto y respecto del sujeto que reclama tutela jurisdiccional;
ii) Que el interés sea legítimo, con lo cual queda desterrada la posibilidad de que se
solicite algún pedido ilícito.
¡ii) Que el interés sea actual, esto es, que no haya que esperar otra condición, plazo o
cargo que cumplirse o acudir a un mecanismo previo al que forzosamente deben
acudir las partes involucradas antes de acudir al proceso.
No existirá interés para obrar cuando se exija, entre otros casos, el cumplimiento de la obliga
ción sujeta a plazo no cumplido, condición suspensiva no verificada o cargo cuya prestación
todavía no se haya satisfecho; el derecho que se pretende discutir ya fue objeto de pronuncia
miento anterior por sentencia que adquirió la calidad de cosa juzgada material o ha sido mate
ria de transacción o conciliación; tampoco cuando se puede recurrir a una vía prejudicial para la
satisfacción o reconocimiento de sus derechos, como por ejemplo, la conciliación extrajudicial
(artículo 6o de la Ley N° 26872, modificado por el Decreto Legislativo N° 1070) o el procedimiento administra
tivo (artículo 19o del TUO de la Ley del proceso contencioso administrativo- D. S, N° 011 -2019 - JUS).
b) Legitimidad para obrar: Es la legitim atio ad causam o legitim idad sustantiva. Es la adecua
ción correcta de los sujetos que participan en la relación jurídica sustantiva con los que
van a participaren la relación jurídica procesal.
L. ordinaria. Llamada “normal”, “directa” u “ordinaria”, la cual traslada al plano proce
sal las calidades que preexisten en la relación material que está siendo ventilada en
juicio.
En este caso, el actor-com o sujeto que da inicio al proceso con la presentación de
la demanda- afirma la existencia de una relación material, en la cual el demandado
está lesionando su derecho, portal motivo, el actor se presenta ante el órgano de jus
ticia invocando ser titu lar de un derecho subjetivo que en ese momento no requiere
probar le corresponde (legitimación activa) y, al mismo tiempo, el actor debe afirmar
que el demandado es quien debe cumplir con la obligación reclamada (legitimación
pasiva). En tal sentido, cuenta con legitimación ordinaria quien, en la causa judi
cial, aduce ser el titular del derecho subjetivo reclamado (legitimación activa) y a
quien se le imputa la calidad de deudor de la obligación a cumplir (legitimación
pasiva), con prescindencia de que en la realidad le asista al actor el derecho que
