Tema 7: Teoría general del proceso
reclama o que el demandado sea el obligado a cumplir la prestación exigida» pues
ello es una cuestión de fondo que recién será determinada con la sentencia.
L. extraordinaria (legitimación extendida). La cual es una suerte de ampliación legal
de la posición habilitante para intervenir en el proceso, otorgada a ciertos sujetos
que no son titulares, activos ni pasivos, del derecho discutido, de tal forma que por
el ia se permite participaren la causa judicial en calidad de parte a quienes ordinaria-
mente no lo podrían hacer.
Ejemplo: la acción oblicua o subrogatoria a la que se refiere el inciso 4) del art. 1219o
del Código Civil, porque el acreedor demanda al deudor de su deudor subrogado,
para que cumpla con la prestación debida a favor de este último, con lo cual la sen
tencia a dictarse sólo ordenará el pago a favor del deudor subrogado, pero no al de
mandante que, en otro proceso, tendrá que afectar el patrimonio recompuesto de su
deudor.
c) Voluntad de la ley: Implica que toda pretensión procesal tenga sustento en un derecho
que a su vez, tenga apoyo en el ordenamiento. Elemento intrínseco al proceso, es la exi
gencia que la pretensión procesal sea pretensión jurídica: caso justiciable.
