3. TEORÍA GENERAL DE LA PRUEBA
La Teoría General de la Prueba se puede definir como aquella derivada de la unidad funda
mental del proceso que implica una noción común de prueba para todo tipo de proceso,
“siempre que en ella se distingan aquellos puntos que por política legislativa, ya que no por
razones de naturaleza o fundón, pueden estar regulados de diferente manera en uno u otro
proceso", según precisa Devis Echeandía.
Couture señala que los problemas de la prueba consisten en saber qué es la prueba; qué se
prueba; quién prueba; cómo se prueba; qué valor tiene la prueba producida. En otros térm i
nos: el primero de esos temas plantea el problema del concepto de la prueba; el segundo, el
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R A M IE N TO DE JUECES Y FISCALES

-- 148 of 1506 --

UBILEX
objeto de la prueba; el tercero, la carga de la prueba; el cuarto, el procedimiento probatorio; el
último, la valoración de la prueba.
3.1. Fuentes de prueba
Aquel hecho, cosa, acto, actitud, fenómeno que contiene en sí una significación originaria ca
paz de transformarse en argumento probatorio si reúne las cualidades para el caso. Al res
pecto, Hinostroza indica que “Se entiende por fuente de la prueba a la información obtenida
gracias a los medios probatorios, teniendo una existencia autónoma en relación al proceso”1.
3.2. Órganos de prueba
Es la persona que suministra el conocimiento sobre determinado hecho. Ejemplo: El testigo,
el perito.
3.3. Medios de prueba
Comprende todos aquellos elementos o instrumentos utilizados por los sujetos procesales
(las partes, el juzgador y los terceros legitimados) para incorporar al proceso o procedimiento
fuentes de prueba. Son ejemplos de medios de prueba: los documentos, la declaración de
parte, la declaración de testigos, las inspecciones judiciales, los dictámenes periciales, etc.
3.4. Clases de medios probatorios
a) Medios probatorios típicos, están regulados en su ofrecimiento, admisión y actuación,
siendo los siguientes: La declaración de parte, la declaración de testigos, los documentos,
la periciay la inspección judicial (Art. 192 C.RC.).
b) Medios probatorios atípicos, si bien expresamente no están regulados, pueden ser ofre
cidos por las partes, y están constituidos por auxilios técnicos o científicos que permitan
lograr la finalidad de los medios probatorios. Por analogía se emplean las reglas de los
medios probatorios típicos. Ejemplos: La reconstrucción de los hechos; la huella dactilar
(Art. 193 C.RC.).
c) Sucedáneos de los medios probatorios. La doctrina extranjera lo considera más que me
ros auxilios de la prueba, como auténticos medios probatorios. El artículo 275 del Código
adjetivo lo define como los auxilios establecidos por la ley o asumidos por el juez para
lograr la finalidad de los medios probatorios, corroborando, complementando o sustitu
yendo el valor de los medios probatorios.
Los sucedáneos de los medios probatorios son el indicio, la presunción y la ficción legal.
Indicio. Es un razonamiento lógico inductivo, pues se parte de un acto, circunstancia o
signo suficientemente acreditados a través de los medios probatorios, que adquiere sig
nificación en su conjunto cuando conduce al juez a la certeza en torno a un hecho desco
nocido relacionado con la controversia.
1 HINOSTROZA, Alberto. La Prueba en el Proceso Civil. z° Edición. Caceta jurídica Editores. Urna, 1999. p. 17.
BALOTARIO DESARROLLADO PARA LOS EXÁM ENES ESCRITOS DE SELECCIÓN
Y N O M B R A M IE N TO DE JUECES Y FISCALES

-- 149 of 1506 --

Tema 7: Teoría general del proceso
Presunción. Se regula la presunción legal y judicial. En términos generales, la presunción
es un razonamiento lógico deductivo, que a partir de uno o más hechos indicadores lleva
al juez a la certeza del hecho investigado.
La presunción legal se subdivide:
• La presunción legal absoluta (jure et de jure), no admite discusión o prueba en con
trario. V. gr., el principio de publicidad registral consagrado en el artículo 201 z del
Código Civil".
• La presunción legal relativa (juris tantum ), admite prueba en contrario. V. gr., el po
seedor es reputado propietario, mientras no se pruebe lo contrario. Esta posesión no
puede oponerla el poseedor inmediato al poseedor mediato. Tampoco puede opo
nerse al propietario con derecho inscrito (Art. 912 del Código Civil).
Por otro lado, la presunción judicial es el razonamiento lógico del juez, basado en reglas
de la experiencia o en sus conocimientosy a partir del presupuesto debidamente acredi
tado en el proceso. V. gr., la presunción de buena fe contractual (Art. 1362 del Código Civil).
La ficción legal. Es la conclusión que la ley da porciertay es opuesta a la naturaleza o rea
lidad de los hechos; no permite prueba en contrario. Ejemplo, la clasificación de los bienes
muebles o inmuebles.
3.5. Cargas de la prueba
Por regla general, la carga de la prueba (onus pvobmdi) corresponde a quien afirma hechos
que configuran su pretensión, o a quien los contradice alegando nuevos hechos.
Si no se prueban los hechos que sustentan la pretensión, la demanda será declarada infundada.
La ley, en determinadas situaciones, determina qué parte debe probar. V. gr., en la responsabi
lidad extracontractual, el descargo por falta de dolo o culpa corresponde a su autor (art. 1969
del C.C.), esto es, al demandado; en la responsabilidad contractual, la prueba del dolo o de
la culpa inexcusable corresponde al perjudicado por la inejecución de la obligación, o por su
cumplim iento parcial, tardío o defectuoso (art. 1330 C.C.), es decir, al actor.
Lo$ hechos que no requieran probanza son los hechos no controvertidos, imposibles, o que sean notorios o
de pública evidencia; las presunciones jure et de jure. El derecho nacional no se prueba; sí requieren
probarse la costumbre y el derecho internacional privado.
3.6 Cargas dinámicas probatorias
Históricamente la institución de la carga de la prueba ha sido sostenida por el principio, según
el cual, al actor le corresponde probarlos hechos que a firm ayal demandado los hechos impe
ditivos, extintivosy/o modificativos que opone. Sin embargo, existe una tendencia de innova
ción caracterizada por una flexibilización de esas reglas clásicas de distribución de la carga de
la prueba, bajo la influencia de la doctrina de las cargas probatorias dinámicas. Según Aven-
