la cual se halla la parte para acreditar la realidad de los mismos, por cuanto dispone de los
medios y argumentos que resultan aptos para demostrarlos”. Es decir, se trata de hacer recaer
la carga de la prueba sobre la parte que se encuentra en mejores condiciones profesionales,
técnicas o de hecho para producirla.
En nuestro país la profesora Marianella Ledesma3, respecto de las cargas probatorias dinám i
cas en nuestro medio, comenta el artículo 196° del Código Procesal Civil, señalando que: Por
tanto, como constituye un apartamiento excepcional de las normas legales que establecen la distribución
de la carga de la prueba, sólo funciona cuando la aplicación rígida o mecánica de la ley conduce a resul
tados inocuos o nada valiosos. (...) En conclusión, como ya se ha sostenido, tradicionalmente se entendía
que la carga de la prueba pesaba sobre la parte que afirmaba la existencia de algún hecho controvertido.
El otro litigante dejaba satisfecha su posición con la sola negativa expresa. Con el correr del tiempo los
hombres de derecho se dieron cuenta que se presentaban situaciones donde la parte que negaba tenía a
su alcance la facilidad de la prueba y la ocultaba de mala fe, mientras que estaba lejos de las posibilidades
de la otra poder aportar elementos de convicción. La doctrina de las cargas probatorias dinámicas
abandonó la óptica tradicional y distribuye las obligaciones probatorias poniéndolas, tal como se
ha señalado, en cabeza de la parte que se encuentre en mejores condiciones para producirla. Se
funda, entre otros preceptos, en el deber de colaboración y en el principio de solidaridad del de
mandado para el arribo a la verdad real.
En nuestro país esta teoría, aplicada en diversas ramas del Derecho, está recogida legislativa
mente en el artículo 32 del TUOde la Ley N° 27584-, D.S. N° 011-2019-]US.
