4. TEORÍA GENERAL DE LA NULIDAD DE ACTOS PROCESALES
4.1. Naturaleza
Según Arrarte8: “la nulidad procesal es un medio impugnatorlo cuyo sino es “cuestionar la vali
dez o eficacia de un acto jurídico procesal o de todo un proceso”; en tal sentido al ser definido
abiertamente como medio impugnatorio cabe preguntarnos ¿a qué tipo nos referimos, se tra
ta de un recurso o un remedio?
El Código Procesal Civil en su artículo 356° hace esta doble diferencia dentro de los medios
impugnatorios, es así que podemos darnos cuenta que este incidente procesal no solamente
es un recurso pues a través de éste nos es permitido cuestionar actos procesales contenidos
en una resolución; sino que también es un remedio ya que nos permite impugnar actos pro
cesales no contenidos en resoluciones. Ejemplo: Solicitar la nulidad de una notificación o de
una audiencia.
Por ello la nulidad procesal podrá recaer sobre actos procesales que ocurran dentro del pro
ceso y que no cumplan con la formalidad establecida en la ley, y también sobre meros actos
procesales irregulares que no se vean reflejados necesariamente en una resolución, pero que
generen efectos dentro del proceso.
4.2. Clases de Nulidad
• Nulidades extrínsecas: Actos inexistentes y nulos, actos nulosy anulables, nulidades ab
solutas y relativas.
a) Inexistencia: Son aquellos actos procesales que se encuentran desprovistos de los re
quisitos mínimos indispensables. Ejemplo, la sentencia que carece de la firma del juez.
b) Nulidad absoluta: Tiene un vicio estructural que lo priva para lograr sus efectos nor
males. Procede de oficio o a pedido de parte. La nulidad pronunciada por el Juez que
declara su incompetencia. No puede ser convalidada.
c) Nulidad relativa: Cabe la posibilidad de su subsanación, tal como lo dispone el artí
culo 171 CPC. Además, en la nulidad relativa subyacen vicios que perjudica el interés
de alguna de las partes. Ejemplo: la nulidad sobre el auto que concede un embargo
sobre bienes inembargables.
d) Anulabilidad: Se produce cuando pese a su realización defectuosa, el acto produce
plenamente sus efectos mientras no sea impugnado dentro de un plazo preclusi-
vo. Ejemplos típicos: Incompetencia territorial, la recusación. Se invoca a pedido de
parte, no de oficio. Precluye por excelencia si el interesado no la pide en su primera
oportunidad.
Las irregularidades procesales: Importa una violación de la legalidad de las formas, pero tal vi
cio no es grave. Este tipo de vicios se distingue de todos los demás, porque son válidos y eficaces.
V. gr., cuando el Juez no expide la sentencia dentro del plazo de Ley.
