Tema 7: Teoría general del proceso
Principios que regulan las nulidades extrínsecas:
a) Principio de legalidad: Ningún acto procesal podrá ser declarado nulo si la Ley no prevé
expresamente esa sanción. Artículos 171; V del T.P; 122 C.RC.
La Sala Civil Transitoria de la Corte Suprema, en la Casación i908-T-96-lca, ha expresado:
“La nulidad es la sanción por la cual la Ley priva a un acto procesal de sus efectos normales, debiendo
diferenciarse la violación de las disposiciones de orden público, que entrañan siempre una nulidad
absoluta, de aquellas que sólo afectan al interés privado,y que deben ser alegadas por aquel a quien
perjudican”.
En atención a la realidad, el principio de legalidad o especificidad se ha tornado relativo.
Así, se inserta el tema de: Nulidades virtuales o implícitas: Son aquellas nulidades que no
obstante carecer de la sanción de nulidad, su quebrantamiento es tan grave que no se
puede establecer una relación jurídica procesal válida, como es el caso del Iitisconsorcio
necesario pasivo.
b) Principio de trascendencia: No hay nulidadsin perjuicio, y está consagrado en el artículo
174 C.RC.
c) Principio de convalidación: Es propio de las nulidades relativas, este principio es entendi
do como la confirmación del acto, siendo su naturaleza saneadoray pudiendo operar de
manera expresa o tácita. Será expresa cuando la parte afectada ratifique el acto viciado,
y tácita cuando no se impugne el acto dentro del plazo legal. Este principio no operará
cuando de por medio exista un acto afectado con nulidad absoluta. Supuestos: Art. 172
C.RC.
d) Principio de subsanación: No habrá nulidad si lasubsanación del vicio no h ad elnflu ire n
el sentido de la resolución o en las consecuencias del acto procesal.
e) Principio de causalidad o de independencia: Este dispone que la declaración de nulidad
de un acto procesal solo alcanzará a los actos posteriores que sean dependientes de él, es
decir, que carezcan de vinculación o nexo y, por ende, sean autónomos del acto viciado.
f) Principio de protección: Nadie será oído si alega su propia torpeza (Inciso 1 del Art. 475
del CPC). Sustentada en la teoría de los actos propios. Ejemplo: Aquel demandado que
presenta por separado su contestación de ladem anday reconvención.
• Nulidades intrínsecas: Atañen a los vicios del consentimiento, como la simulación, el
fraude procesal.
Nulidad de Cosa Juzgada Fraudulenta (Art. 178 C.RC.)
Corresponde al tema de las nulidades Intrínsecas. Por regla general, la cosa juzgada es Inmu
table, cuyo sustrato valorativo es la seguridad jurídica. Sin embargo, qué ocurrirá si se obtiene
una sentencia firm e mediante un proceso simulado por las partes, y que perjudica a un terce
ro; qué sucede cuando se ha ganado un juicio merced a una Escritura Pública adulterada en
el Jr. Azángaro, será posible invocar el carácter inmutable de la cosa juzgada. El artículo 123 in
fn e del CPC prescribe claramente que excepcionalmente no hay cosa juzgada, cuando existe
fraude procesal (valor justicia).
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 154 of 1506 --

UBILEX
La nulidad de cosa juzgada fraudulenta es una pretensión nulificante sustentada en vicios sus
tanciales de la resolución que contenga la calidad de cosa juzgada. No se discute el fondo del
asunto de lo resuelto en el proceso anterior, sino normativamente la causal de fraude procesal.
La Doctrina reconoce que la nulidad de cosa juzgada fraudulenta tiene, entre otras caracterís
ticas, la de ser excepcional (sólo procede frente a causales específicas), residual (no puede uti
lizarse si dentro del proceso hay otros mecanismos para subsanar el vicio ocurrido), extraordi
naria (sólo puede cuestionarse la autoridad de cosa juzgada recaída en una sentencia cuando
tal decisión haya sido obtenida en base al engaño o simulación) y de extensión lim itada (la
declaración de nulidad sólo atañe a aquellos actos viciados de fraude).
Nuestra legislación procesal civil lo regula como un proceso autónomo que se tram ita en la vía
más lata (proceso de conocimiento, por contar con mayor capacidad probatoria), a través del
cual se busca remediar una situación viciada por fraude procesal que ha afectado el debido
proceso, retrotrayéndose las cosas al estado anterior al que produjo el fraude procesal, anu
lando todos los actos afectados portal Inconducta.
Un requisito de procedencia para este remedio excepcional, conforme se desprende del ar
tículo 178 del Código Procesal Civil, que el acto alegado como viciado haya provenido de una
conducta procesal fraudulenta o colusiva (en realidad, la colusión es una forma o modalidad
del fraude), que afecte el derecho al debido proceso de una de las partes, y que haya sido de
terminante para la expedición de lasentencia, no existiendo oportunidad de cuestionarlo me
diante los recursos ordinarios internos del proceso respectivo.
En esa línea interpretativa (Cas. N° 2659-2018 Cusco), se ha dicho: “(■■■) el propósito de este me
canismo es únicamente rescindir aquello que ha sido afectado por la comisión de un fraude procesal. Por
tanto, desde el punto de vista del conflicto, el proceso de nulidad de cosa juzgada fraudulenta no recompo
ne la situación, únicamente detecta el defecto, rescinde la resolución que es su producto, anula los hechos
afectados por el fraudey, finalmente, garantiza las condiciones necesarias para que se reinicie el proceso
primarlo’’910. Y, más adelante-, “(...) toqúese demanda en la revisión versará única y exclusivam ente sobre
la comisión del fraude procesal, es decir, sobre una cuestión puram ente procesal''0" (resaltado del au
tor).
Clasificación del fraude procesal: 1) Unilateral o concertado; 2) Fraude cometido con el pro
ceso y el perpetrado en el proceso: Primero: proceso simulado para perjudicar a un tercero.
Segundo: Tiene por meta esgrimir el fraude procesal dentro del mismo proceso.
Requisitos de procedencia: Estos requisitos son:
1. Que la sentencia sea definitiva, haya adquirido la calidad de cosa juzgada, por ser una
decisión ejecutoriada, no consentida.
2. Que el fallo sea producto de la conducta fraudulenta.
3. Que la sentencia haya ocasionado un perjuicio efectivo.
