4.3. Efectos
La nulidad de un acto procesal afecta a los actos posteriores que de él dependan o sean su
consecuencia (art.170 C.RC.)
5. LOS PLAZOS ¥ FORMAS DE LOS ACTOS PROCESALES
Plazos de los actos procesales: Los plazos procesales son perentorios, es decir, aquel cuyo ven
cimiento determina automáticamente la caducidad de la facultad procesal para cuyo ejercicio
se concedió, sin que para lograr tal resultado, se requiera la petición de la otra parte o una
declaración judicial.
La diferencia entre plazoy término es la siguiente:
Plazo: es el espacio de tiempo dentro del cual se pueden practicar los actos procesales.
Término: es la fecha fija en que se puede practicar un acto procesal.
Las actuaciones judiciales se practican puntualmente en el día y hora hábil señalados sin ad-
m itirdilación.
De oficio o a pedido de parte, el juez pude habilitar días y horas (artículo 142 del C.RC.).
Cómputo: Artículo 147 del C.RC., días hábiles.
Interrupción y suspensión del proceso:
La interrupción corta el plazo o difiere el término para realizar un acto procesal, produ
ciendo la ineficacia de la fracción del plazo o difiriendo el térm ino transcurrido. Es inim
pugnable. Vence al tercer día de cesado el hecho impeditivo (artículo 317 del C.RC.)
La suspensión es la inutilización del período de tiempo del proceso o de una parte del
plazo concedido para la realización del acto procesal. Puede ser legal, judicial y voluntaria
(artículo 318 a 320 del C.RC.).
6. FORMAS DE LOS ACTOS PROCESALES
A. Actos procesales provenientes del juez: El juez se manifiesta a través de resoluciones:
Decretos, autos y sentencias.
Los decretos sirven para impulsarel desarrollo del proceso, disponiendo actos proce
sales de mero trámite.
Los autos resuelven la admisibilidad o el rechazo de la demanda o de la reconven
ción, el saneamiento procesal, las formas especiales de conclusión del proceso, el
concesorio o denegatorio de medios impugnatorios y demás decisiones específicas
del juez que requieran fundamentación.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 156 of 1506 --

UBILEX
Las sentencias sirven para poner fin a la instancia o al proceso.
B. Actos procesales de las partes
Para Leo Rosemberg los actos procesales de las partes son”: Todas las actividades configu
rad vas del proceso, es decir, toda conducta externa basada en la voluntad consiente (vo
luntad de actuar), regulada por el derecho procesal según presupuestos y efectos”. Estos
actos jurídicos procesales se clasifican en:
i. Actos de Postulación:
Son los actos que realizan las partes y con ellos buscan una resolución del órgano
jurisdiccional suministrando la materia para su fundamento.
Entre estos podemos señalar:
La demanda, como un acto jurídico procesal exteriorizado en el escrito que inicia el
juicioy tiene por objeto determinar las pretensiones del actor mediante el relato de
los hechos que dan lugar a la invocación del derecho que lafundam entay la petición
clara de lo que reclama, conteniendo los requisitos establecidos por el Código Proce
sal Civil.
La respuesta a este primer acto procesal, demanda, es el auto admlsorio, siempre
que cumpla con todos los requisitos de forma como de fondo, y durante el proceso
se dan una sucesión de actos procesales tanto del juez como de las partes, e incluso
de terceros que llegan a intervenir en el proceso.
Juan Monroy Cálvez, define la demanda como: “el acto jurídico procesal por el que el
actor (demandante) somete al órgano jurisdiccional su pretensión o falta de certeza.
Por extensión el medio material a través del cual se ejercita el acto jurídico antes cita
do, con el que se inicia el proceso.”
ii. Actos Constitutivos:
Son aquellos que fundan una situación procesal dentro de un proceso y a veces sur
ten efectos más allá del proceso.
Dentro de estos actos se encuentran todos aquellos que las partes, tanto deman
dante como demandado realizan a lo largo de la actividad del proceso. Ejemplo: Las
excepciones, por cuanto son actos jurídicos procesales que depuran o buscan el pe
recimiento de la pretensión Incoada.
7. NOTIFICACIONES
A través de las notificaciones se comunica a los interesados el contenido de las resoluciones
judiciales.
7.1. Clases de notificaciones:
Notificación por cédula: Cuando el órgano jurisdiccional necesariamente realiza la notifica
ción a través de una comunicación impresa a las partes y los terceros legitimados, estamos
ante la notificación por cédula (artículo 158 del C.PC.). Realmente, los actos procesales más
