trascendentes son notificados por cédula, como la resolución que declara inadmisible o im
procedente la demanda; el traslado de la demanday reconvención; la sentencia; etc. Por regla
general, la notificación se entrega directamente al interesado, salvo que éste se negare o no
pudiere firmar, lo cual se dejará constancia. Si el notificador no encontrara al interesado, le
dejará un preaviso; si tampoco se le hallará en la nueva fecha, se entregará la cédula a la per
sona capaz que se encuentre en la casa, departamento u oficina, o al encargado del edificio,
procediéndose de acuerdo a lo expuesto en el párrafo precedente.
Notificación electrónica: La notificación de las resoluciones judiciales, en todas las instancias,
se realiza por vía electrónica a través de casillas electrónicas implementadas (artículo 157 del
C.RC.).
Notificación por nota: Se configura la notificación por nota (Art. 156 del C.RC.), cuando la par
te, su letrado o la persona o personas que ésta haya designado, acude al local del juzgado y
secretaria correspondiente a conocer el contenido de las resoluciones. En todos aquellos casos
que no se deba notificar por cédula, se emplea la notificación por nota, verificándose los días
martes o jueves, o el día hábil siguiente si alguno de ellos fuera inhábil. Se le conoce también
como notificación automática, pues si las mencionadas personas no concurren en las fechas
indicadas, esta notificación surtirá sus efectos.
Notificación por comisión o exhorto (Art. 162CPC): Cuando determinados actos procesales
deban realizarse fuera del ámbito de la competencia territorial de un juez, éste comisionará
a otro para que lo realice. La parte interesada anexará el pago de la respectiva tasa judicial. El
exhorto puede ser nacional o internacional; y, en este últim o supuesto, el exhorto se tramitará
por intermedio de los órganos jurisdiccionales del país en que reside la persona a quien se va
a notificar o por el representante diplomático del Perú en éste, a elección del interesado.
Notificación por telegrama, facsímil, correo electrónico u otro medio (Arts. 163 y 164 CPC):
No se puede emplear en el traslado de la demanda o reconvención, citación para absolver
posicionesy la sentencia. Es un medio supletorio de la notificación por cédula. La notificación
por correo electrónico sólo se realizará para la parte que lo haya solicitado.
Notificación por edictos (Art. 165 a 168 CPC): La publicación de los edictos se hace en el portal
web oficial del Poder] udicial. Si ello no fuera posible por las condiciones tecnológicas o lejanía
del órgano jurisdiccional, el edicto se publica en el diario de mayor circulación de la circuns
cripción. A falta de diarios, la publicación se hace en la localidad más próxima que los tuviera,
debiéndose además fijar el edicto en la tablilla del Juzgado y en los sitios que aseguren su
mayor difusión. En todos los casos, la publicación debe efectuarse por un periodo de tres días
hábiles acreditándose su realización, agregando al expediente la constancia de su publicación
web emitida por el especialista o secretario judicial respectivo y la impresión de la publicación
realizada en el portal institucional o, de ser el caso, el prim ery el últim o ejemplar de las publi
caciones realizadas en los diarios. (Art. 167 C.RC.).
Se notifica mediante edictos: i) Cuando se trate de personas inciertas o cuyo dom icilio se
ignore; en este últim o caso, la parte debe manifestar bajo juram ento o promesa que ha ago
tado las gestiones destinadas a conocer el dom icilio de la persona a quien se deba notificar;
ii) Si debe notificarse a más de diez personas que tienen un derecho común, el juez, a pe
dido de parte, ordenará se les notifique mediante edictos; iii) Procesos de títu lo supletorio,
