8. COSA JUZGADA
La llamada cosa juzgada constituye un efecto procesal de la resolución judicial firm e que
impide que lo que ya se ha resuelto sea nuevamente revisado en el mismo proceso o en
otro proceso, se encuentra regulada en el art. 123 del CPC, su autoridad presente en las re
soluciones judiciales, al igual que sus límites y los alcances para las partes. Esta norma se
condice con el art. 446 numeral 8 del CPC, el cual ha contemplado la excepción de cosa
juzgada, una defensa de forma por la cual el demandado podrá alegar que la controversia
que el demandante pretende promover, ya ha sido objeto de discusión en un proceso previo
concluido con una sentencia que adquirió la calidad de cosa juzgada, motivo por el cual se
debe declarar la nulidad de todo lo actuado en el nuevo proceso y disponerse su conclusión.
Por otro lado, la C onstitución-en su art. 139 incisos 2 y 13-re fie re que no se puede dejar sin
efecto resoluciones judiciales que han pasado con autoridad de cosa juzgada, ni modificar
ni retardar su ejecución al Igual que regula la prohibición de revivir procesos fenecidos con
resolución ejecutoriada.
En este sentido, el Tribunal Constitucional ha señalado que incluso, existe un “derecho al res
peto de las resoluciones con autoridad de cosa juzgada”: (...) mediante el derecho a que se respete
una resolución que ha adquirido la autoridad de cosa juzgada, se garantiza “el derecho de todojusticiable,
en prim er lugar, a que las resoluciones que hayan puesto fin al proceso judicial no puedan ser recurridas a
través de medios impugnatorios,ya sea porque estos han sido agotados o porque ha transcurrido el plazo
para impugnarla-, y, en segundo lugar, a que el contenido de las resoluciones que hayan adquirido tal
condición no pueda ser dejado sin efecto ni modificado, sea por actos de otros poderes públicos, de terceros
o, incluso, de los mismos órganos jurisdiccionales que resolvieron el caso en el que se dictó”. STC Exp. N°
4 5 8 7 -2 0 0 4 ''AA/TC. Fj. N °3 8 .
Del mismo modo, la Segunda Sala de Derecho Constitucional y Social Transitoria de la Corte
Suprema de justicia de la República afirma que la cosa juzgada es una "garantía” procesal: (...)
la cosa juzgada constituye una garantía fundam ental de la administración de justicia, la cual asegura
que el objeto m ateria de un proceso, el cual ha sido resuelto por resolución judicial firm e y contra la cual
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

