Tema 7: Teoría general del proceso
no procede medio de im pugnatorio alguno, sea ventilado dentro del mismo proceso o mediante otro. En
efecto, la institución jurídica procesal de la cosa juzgada exige que una decisión plasmada en sentencia
tenga el carácter de inmutable, vinculante y definitiva. (Cas. N ° i2 0 0 2 -2015-La Libertad)
La cosa juzgada posee dos efectos especiales, Monroy Cabra11 precisa que el efecto procesal de la
cosa juzgada impide a los jueces revisar procesos que han sido decididos. De otro lado, el efec
to m aterial se refleja en la definitividad de declaración de certeza de la sentencia, haciéndola
indiscutible en nuevos procesos.
Los fundamentos de la existencia de la cosa juzgada son: i) Certeza jurídica: la cosa juzgada
pretende satisfacer la necesidad de certeza de las situaciones, que toda sociedad requiere;
mientras que la necesidad de justicia se pretende satisfacer a través de los recursos judiciales.
ii) Estabilidad de los derechos: con la cosa juzgada se pretende asegurar la estabilidad y certi
dumbre de los derechos que las sentencias reconocen o declaran. Permite la inm utabilidad de
los derechos adquiridos en virtud de las sentencias, iii) Separación de poderes: la cosa juzgada
reconoce el principio de separación de poderes, al im pedirá los órganos de los demás poderes
(ejecutivoy legislativo) alterar o modificar los resultados del ejercicio de la función jurisdiccio
nal, reiniciando un proceso ya terminado.
8.1. Clases
Cosa juzgada formal, aquella que implica la imposibilidad que una determinada decisión
sea recurrida. En decir, una resolución judicial que goza de esta clase de cosa juzgada no
puede ser objeto de más recursos. Sus efectos se producen exclusivamente en el proceso
en que se ha dictado la sentencia. Tenemos entonces que la cosa juzgada formal es la
inm utabilidad de la sentencia por la preclusión de los recursos, siendo el presupuesto
necesario de la cosa juzgada material.
Cosa juzgada material, es aquella que implica la inacatabilidad de un resultado procesal
mediante el inicio de un nuevo juicio, al cerrarse toda posibilidad de que se emita una
decisión que se contradiga o se oponga a lo antes dictado. Sus efectos se producen en el
proceso en que se dictó la sentencia y en otros futuros, por lo que se considera estable y
permanente porque es eficaz dentro y fuera del respectivo proceso. Es decirque lasenten-
cia judicial surgida de un proceso anterior impone que se tenga en cuenta su contenido
en todo proceso futuro entre las mismas partes y sobre el mismo objeto, teniendo fuerza
vinculante.
8.2. Efectos
Son las consecuencias jurídicas que surgen de la cosa juzgada, que se traducen en la posibi
lidad de exigir el cumplimiento de lo resuelto (acción de cosa juzgada) o en evitar un nuevo
juicio sobre la materia (excepción de cosa juzgada).
