La acción de cosa juzgada es el efecto que permite el cumplim iento coactivo de un derecho re
conocido o declarado en juicio. Requiere de una sentencia, favorable al que pretende ejercerla,
firme o que cause ejecutoriay que imponga una obligación actualmente exigióle.
Su titu la r es la persona a cuyo favor se ha reconocido o declarado un derecho, incluyendo a
sus sucesores, y se ejerce contra el litigante perdedor, para reclamar lo obtenido en el juicio.
En general, es prescriptible y el procedimiento para exigir su cum plim iento dependerá de si
se trata de una sentencia emanada de un tribunal nacional o de uno extranjero.
La excepción de cosa juzgada, es el efecto también conocido como non bis in Ídem, en virtud del
cual no puede volver a discutirse entre las mismas personas, una misma materia e invocando
idénticas razones. Es decir, permite hacer valer los atributos de inm odificabiIidad e ininmpu-
ganibilidad que posee una sentencia firm e frente al inicio de un nuevo juicio.
Su titu lar es el litigante que se ha beneficiado por el resultado del juicio y por todos aquéllos a
los que, según la ley, aprovecha la decisión. Puede ser invocada por cualquiera de las partes en
el juicio, independiente de la calidad que hayan tenido en éste, es decir haya sido demandante
o demandado. Por lo general, esta excepción debe ser alegada en el juicio posterior, porque
es renunciable expresa o tácitamente y, habitualmente, sólo favorece a las partes que han in
tervenido en el respectivo litigio y a sus herederos. Además, es imprescriptible, pues puede
alegarse en cualquiertiempo.
La doctrina clásica señala que, para que sea procedente la excepción de cosa juzgada es preci
so que, en ambos juicios, concurran tres requisitos comunes:
Identidad de persona (eaedem personae):debe tratarse del mismo demandante y deman
dado, jurídicamente hablando. Para fijar este requisito Eduardo Couture señalaba que
hay que considerar tres principios: identidad jurídica (la identidad de carácter legal y no
física), sucesión (a los causahabientes de una persona) y representación (la posibilidad
de actuación a nombre de otro). Por ello, las personas que actúan en el litigio pueden ser
físicamente distintasy existir identidad legal (por ejemplo, entre un heredero del deman
dante ya fallecidoy el demandado) o, porel contrario ser físicamente idénticasy no existir
tal identidad (por ejemplo, entre el demandante y el ex-representante de una persona
jurídica antes demandada).
Identidad de la cosa pedida (eadem res): el objeto o beneficio jurídico que se solicita (no el
objeto material) debe ser el mismo. Osea, lo que se reclama.
Identidad de la causa de pedir (eadem causa petendí): el hechojurídico o material que sirve
de fundamento al derecho reclamado debe ser el mismo. Es decir, el por qué se reclama.
