En conclusión, la cosa juzgada constitucional es aquella decisión jurisdiccional de fondo que
no solamente es dictada por el Tribunal Constitucional en los procesos constitucionales que
conoce,sino por cualquierórgano jurisdiccional en cualquiertipo de proceso, siempre y cuan
