10. TEORÍA GENERAL DE LA IMPUGNACIÓN
Los medios impugnatorios son mecanismos procesales establecidos legalmente que permi
ten a los sujetos legitimados procesalmente peticionara un Juez o a su superior reexamine un
acto procesal o todo un proceso que le ha causado un perjuicio, a fin de lograr que la materia
cuestionada sea parcial o totalmente anulada o revocada.
Constituyen pues mecanismos de revisión de resoluciones judiciales o de los procesos mismos,
y a través de ellos, tal como señala Binder12, se cumple con el principio de control, que constituye
un principio esencial no sólo del proceso mismo sino incluso del sistema de justicia en general.
La impugnación tiene un fin inmediato, como lo es el beneficio de la parte o sujeto que la
ejercita y otro mediato, que sirve de marco al anterior, consistente en la prevalencia del valor
justiciay la correcta imposición del derechoy que interesa al orden general.
10.1. Principios
Principio de legalidad.- Sólo pueden interponerse los recursos expresamente previstos
en la ley.
