Principio de legitimación.- Nadie puede impugnar sin interés protegióle por el derecho. Ha
brá que teneren cuenta sin embargo, que es posible impugnar la decisión que resuelve sobre
la existencia de dicho interés, es decir acerca de la admisibilidad de la legitimación invocada.
Principio de temporalidad.- Así como no puede concebirse una serie ilim itada de im
pugnaciones, tampoco cabe aceptar el ejercicio intemporal de las mismas. Así y como
principio, debe concretarse en los plazos marcados por la ley, como ocurre en materia
recursiva o incidental; de lo contrario, se producirá la caducidad o el decaimiento del de
recho de recurrir.
Principio de agotamiento de la impugnación.- Se da cuando intentada una vía de cues-
tionamiento y frustrada por deserción, desistimiento, declaración de inadm isibilidad o
de improcedencia, queda cerrada la viabilidad de un nuevo intento, ello no significa la
imposibilidad de practicar otra vía, en caso de que así lo autorizara la ley, o de tom ar ca
minos diversos si variaran los elementos a computar en sistemas como el de la revisión,
en los que tales variantes pudieran ser tenidas en cuenta.
Principio de limitación.- Importa que el tribunal revisor, sea otro distinto del que dictó
el pronunciamiento, no puede abarcar en su tarea otro campo que el señalado para la
impugnación al tiempo de plantearla (por ejemplo apelar por las condenaciones acce
sorias y no por las principales) o al de fundarla, si se tratare de un recurso, No obstante,
si la ley exigiera fundamentación siendo bastante con la deducción del intento, la alzada
adquiere plenitud de jurisdicción de alcance absoluto pudiendo revisar todo el ámbito
tratado por el tribunal a-quo, salvo el principio de prohibición de re fo m a tio m peius o los
ceñimientos que hubiese impuesto el impugnante al recurrir.
Principio de prohibición de re fo m a tio in peías- Según Pérez Pinzón, esta proh i bición “sig
nifica que cuando el procesado - o su defensa- apela la sentencia de primera instancia,
interpone casación o revisión, el juez de segunda instancia, el de casación y el de revisión
no pueden empeorar la situación que le ha sido deducida en el fallo materia de la impug
nación o de acción. El principio rige cuando el procesado es impugnante o actor único. De
tal manera que si otras partes, (...), impugnan o incoan la acción en contra del sindicado,
si opera la re fo m a tio in peius.
La prohibición tiene amplia vigencia legislativa en el ámbito del proceso civil y plena apli
cación en el proceso penal.
Así, si otros sujetos procesales (...), impugnan o incoan la acción en pro del procesado,
tampoco se puede desmejorar su posición inicial. Porsu parte Roxin sostiene que con este
principio “se pretende lograr que nadie se abstenga de interponer un recurso por el temor
de ser penado de un modo más severo en la instancia siguiente. Si la fiscalía pretende
conseguir una pena más elevada siempre tendrá que interponer, para ello, un recurso en
perjuicio del acusado.
