Según Monroy Gálvez, los recursos ordinarios son aquellos que se conceden bastando ar
gumentar que la resolución impugnada ha sido expedida con vicio o error. Sin embargo, hay
otros recursos respecto de los cuales la legislación aplicable exige cierto número y tipo de
requisitos de admisibilidad y, sobre todo, de procedencia, que determinan que su concesión
sea una situación excepcional, éstos son los extraordinarios. Ejemplos clásicos de cada uno
serían, sin duda, la apelación para los ordinarios y la casación para los extraordinarios. Son
propios cuando van a ser resueltos por el órgano jurisdiccional superior a aquél que expidió
la resolución impugnada, tienen la calidad de recursos impropios aquéllos que -contrariando
el ciclo normal de un medio impugnatorio que exige un nuevo examen del acto procesal por
un juez distinto a aquél que participó en el acto-son resueltos por el mismo juez que expidió
la resolución impugnada.
