Tema 7: Teoría general del proceso
10.3. Requisitos generales de adm isibilidad de los medios impugnatorios:
1. Su interposición se realiza ante el órgano jurisdiccional que cometió el vicio o error, salvo
disposición en contrario, como en la queja.
2 . Los medios impugnatorios se interponen dentro del plazo señalado en la ley procesal.
3 . Adicionalmente, se requiere el cumplimiento de ciertas formalidades, como el abono de
la tasa judicial.
De no satisfacer alguno de los requisitos formales, el medio im pugnatorio es declarado
inadm isible; se advierte que a diferencia de la etapa postulatoria, no es viable la sub-
sanación, salvo que ésta se realice dentro del plazo de su interposición. Es un criterio
interpretativo.
10.4. Requisitos generales de procedibilidad de los medios impugnatorios:
1. Fundamentación. El agraviado debe explicar con claridad y precisión en qué consiste el
vicio o error que lo motiva. El juez no puede sustituirse al impugnante en su fundam enta
ción; prima el principio de iniciativa de parte.
2. Descripción del agravio. El impugnante debe precisar el acto procesal que lo causa agra
vio; si lo impugna total o parcialmente.
3. Adecuación. El impugnante debe adecuar el medio que utiliza al acto procesal que im
pugna. V. gr„ no podrá apelar un decreto.
De no satisfacer alguno de los requisitos de fondo, el medio impugnatorio es declarado im
procedente.
Está prohibido a una parte interponer dos recursos contra una misma resolución (Art. 360 CPC).
Las partes pueden convenir en la renuncia a recurrir contra las resoluciones que pongan fin
al proceso; esta renuncia será admisible siempre que el derecho que sustenta la pretensión
discutida sea renunciabley no afecte el orden público, las buenas costumbres o norma impe
rativa (Art. 361 CPC).
