1. PRINCIPIOS ¥ GARANTÍAS DE LA FUNCIÓN JURISDICCIONAL ¥ FISCAL
1.1. Principios y garantías de la función jurisdiccional
Conforme al artículo 139 de nuestra Carta Magna.
- La unidad y exclusividad de la función jurisdiccional - Solo se explica la presencia de la
jurisdicción m ilitar como un fuero privativo, en el que sólo estaría incurso el personal po
licial)/ militar, con las excepciones, constitucionalmente previstas a los civiles que pueden
serobjeto del juzgamiento privativo militar.
- La independencia en el ejercicio de la función jurisdiccional.- El principio de indepen
dencia judicial exige que el legislador adopte las medidas necesarias y oportunas a fm
de que el órgano y sus miembros administren justicia con estricta sujeción al Derecho y
a la Constitución, sin que sea posible la injerencia de extraños (otros poderes públicos o
sociales, e incluso órganos del mismo ente judicial) a la hora de delim itare interpretar el
sector del ordenamiento jurídico que ha de aplicarse encada caso.
- La publicidad en los procesos.-Salvo disposición contraria de la ley. No debe haber justi
cia secreta, ni procedimientos ocultos, ni fallos sin antecedentes, ello no quiere decir que
todo el proceso debe ser necesariamente público y que toda persona pueda conocer en
cualquier momento los expedientes.
- Principio de las dos instancias.- Este principio consagra la posibilidad que las resolucio
nes judiciales puedan ser objetos de revisión por una instancia superior.
- El principio de no dejar de administrar justicia por vacío o deficiencia de la ley - No
siempre la ley puede contener las diversas manifestaciones de la vida humana. Corres
ponde al magistrado supliresas deficiencias para administrar justicia. Loque no se puede
hacer en el campo penal. Esta atribución se desenvuelve en el área civil y también en lo
que corresponde a derecho humanos.
- El principio de inaplicabilidad por analogía de la ley penal y de las normas que restrin
jan derechos - Tiene su base en la frase de Feuerbach "Nullum crimen, Nullum poena sine
lege”que quiere decir: no hay delito, no hay pena sin ley.
- El Juicio previo - Puede ser penado sin juicio previo fundado en ley anterior al hecho del
proceso.
- Principio de favorabilidad - Es un derecho del justiciable para que el juez interprete la
norma a su favor, en aquellos casos en los que una nueva ley favorezca al reo, a pesar de
