-- 168 of 1506 --

haberse iniciado el proceso en función de una ley anterior que estaba vigente al momen
to de someterse la infracción.
- La inadmisibilidad de la persecución múitíple (ne bis in ídem).- Significa que la persona
no puede ser procesada o castigada de nuevo por la misma jurisdicción de un mismo país
a causa de una i nfracción penal por la que ya haya sido absuelto o condenado en virtud de
sentencia firme.
- La obligación del Poder Ejecutivo de prestar la colaboración.
- Principio de la prohibición de ejercer función judicial por quien no ha sido nombrado le
galmente.
- El principio de la función preventiva de defensa social del proceso penal.- Consiste en
que en el proceso penal debe ser concebido no solamente como instrumento para la in
vestigación de los ilícitos penales y la aplicaciones consecuente de penas o medidas de
seguridad sino también como instrumento para la tutela de la libertad, la vida, el honor y
los demás derechos fundamentales de la persona humana, e igualmente para la educa
ción y readaptación social de los delincuentes.
1.2. Principios de la función fiscal
La labor del Ministerio Público (M.P) se encuentra sujeta al cumplim iento de determinados
principios, que sus miembros deben aplicaren el desarrollo de sus funciones. Estos Principios
son, entre otros:
- Principio de Legalidad.- Enuncia que el M.P está obligado a iniciary sostener la persecu
ción penal del delito sin que pueda suspenderla, interrumpirla o hacerla cesar a su mero
arbitrio.
- Principio de Objetividad.- Según Ore guardia, “por el Principio de Objetividad los fiscales
tienen la obligación de investigary agotar el examen de todas las hipótesis penales, tanto
para la persecución como para la defensa. Es decir, sin perjudicar ni favorecer a ninguno
de los que intervienen en el proceso, dado que su actuación debe ser desinteresada o des
apasionada, debiendo atenerse únicamente a la realidad objetiva, que les permita, en
ciertos casos, incluso no acusar.”
Opina NEYRA FLORES, siguiendo a DUCE Mauricio que, este principio tendría 3 alcances
concretos:
1. - El M.R debe corroborar las hipótesis fácticas de exclusión o atenuación de responsa
bilidad pausiblesy serias, argumentadas por la defensa.
2. - Significa un deber de lealtad del M.R para con la defensa.
3 - Significa un deber de actuar de buena fe, por parte del M.R, no solo al inicio de la in
vestigación, sino durante todo el procedimiento; lo cual implica también disponer las
diligencias concretas que deben llevarse a cabo en atención al principio de Objetividad.
Y finalmente recalca: El Fiscal debe indagar no solo las circunstancias que permitan com
probar la imputación, sino también las que sirvan para eximir o atenuar la responsabili
dad del imputado.
