m .n T Sistem a de justicia
- Principio de eficiencia,- Se impone a los fiscales y funcionarios del M.P la obligación de
eficiencia en dos ámbitos: a) En la administración de los recursos y bienes públicos, y b)
En el cumplim iento o desempeño de las funciones.
junto a la exigencia de eficiencia, y como una manifestación de la misma, se establece la
obligación de propender a la unidady coordinación de las acciones, evitando la duplica
ción o interferencia de funciones.
- Principio de Oportunidad.- Permite que el fiscal este autorizado para no iniciarel ejerci
cio de la persecución penal cuando existan motivos de utilidad social por razones políti
co-criminal.
- Principio de responsabilidad.- Los fiscales del M.P tienen responsabilidad civil, discipli-
nariay penal por los actos realizados en el ejercicio de sus funciones.
Existe responsabilidad que nace de la realización de ilícitos civiles y penales, en este ú lti
mo caso de carácter criminal o administrativo.
- Principio de oficialidad.- Expresa la idea de persecución publica de los delitos que deben
ser perseguidos de oficio por el Estado. El Estado tiene la atribución privativa del ejercicio
de la acción penal pública, para el esclarecimientoy sanción de los delitos, sin necesidad
de esperar la denuncia de la víctima o de un tercero.
- Principios de transparencia y probidad.- El principio de transparencia fue analizado
como presupuesto indispensable para el control ciudadano de la actividad del M.P Per
mite verificar el modo en que se ejerce la persecución penal pública y sus criterios polí
tico-criminales de actuación y se constituye en elemento central para la protección de la
probidad administrativa.
Sin embargo, se podrá denegar la entrega de documentos o antecedentes requeridos en
virtud de diversas causales como: i) Cuando la reserva o secreto se encuentran estableci
dos en disposiciones legales o reglamentarias, ii) Cuando la divulgación o entrega de los
documentos o antecedentes requeridos afecte los derechos o intereses de terceras per
sonas. iii) Cuando exista oposición deducida por terceros a quienes se refiera o afecten la
información contenida en los documentos requeridos, iv) Cuando la publicidad impida el
cumplim iento de las funciones del organismo, v) Cuando la publicidad afecte la seguri
dad de la Nación o el interés nacional.
2. ORGANIZACIÓN Y PRINCIPALES FUNCIONES DEL PODER JUDICIAL Y MINISTERIO
PÚBLICO
2.1. Poder Judicial
2.1.1. Funciones
El Poder judicial es, de acuerdo a la Constitución y las leyes, la institución encargada de adm i
nistrar justicia a través desús órganos jerárquicos que son los juzgados de Paz no Letrados, los
juzgados de Paz Letrados, las Cortes Superioresy la Corte Suprema de justicia de la República.
El funcionamiento del Poder judicial se rige por la Ley Orgánica del Poder judicial que estable
ce su estructura orgánicay precisa sus funciones.
