Esta ley define los derechos y deberes de los magistrados, quienes son los encargados de ad
ministrar justicia; de los justiciables, que son aquellos que están siendo juzgados o quienes
están solicitando justicia; y de los auxiliares jurisdiccionales que son las personas encargadas
de brindar apoyo a la labor de los integrantes de la magistratura.
La Ley Orgánica del Poder Judicial vigente, tiene su origen en el Decreto Supremo N° 017-93-
JUS promulgado el 28.05.1993 y publicado el 02.06.1993. Consta de 304 Artículos, 1 Disposi
ción Complementaria Únicay 33 Disposiciones FinalesyTransitorias.
2.2. M inisterio Público
2.2.1. Funciones:
Según el art.i de la Ley Orgánica del Ministerio Público, Decreto Legislativo N° 52 del 19.03.1981,
el Ministerio Público es el organismo autónomo del Estado que tiene como funciones princi
pales:
- La defensa de la legalidad, los derechos ciudadanos y los intereses públicos; la represen
tación de la sociedad en juicio, para los efectos de defender la familia, a los menores e
incapaces y el interés social, así como para velar por la moral pública, la persecución del
delitoy la reparación civil.
También velará por la prevención del delito dentro de las limitaciones que resultan de
la presente ley y por la independencia de los órganos judiciales y la recta administración
de justiciay las demás que le señalan la constitución Política del Perúy el ordenamiento
jurídico de la Nación.
3. PRINCIPIOS DE INDEPENDENCIA E IMPARCIALIDAD
La independencia en el ejercicio de la función jurisdiccional corresponde a los jueces, la cual
no está subordinada a ninguna instancia de poder. Según el Tribunal Constitucional: "La in
dependencia judicial debe ser entendida como aquella capacidad autodeterminativa para
proceder a la declaración del derecho, juzgando y haciendo ejecutar lo juzgado, dentro de los
marcos que fijan la Constitución y la Ley”. (STC Exp. N° 0004-2006-PI/TC).
El principio de imparcialidad garantiza la imparcialidad de los órganos que imparten justicia
evitando que los jueces se encuentren comprometidos con las partes o sometidos a presión
por órganos de poder o por otras circunstancias.
La contaminación del juez en la investigación de los procesos sumarios, vulnerad principio de
imparcialidad al concentrarse la función de investigary sentenciar.
"El derecho a ser juzgado por un juez imparcial constituye un elemento del derecho al debido
proceso...” (STC Exp. N° 03020-2009-PHC/TC)
Manifestaciones de la imparcialidad:
a) Imparcialidad subjetiva: La imparcialidad subjetiva refiere a que el juez no debe tener
ningún tipo de interés con el resultado a que pueda llegar el proceso para alguna de las
partes, como puede ser que una de las partes sea un fam iliar suyo, o que sea su acreedor,
