TaíjM 8: Sistem a de justicia
o tenga algún tipo de enemistad, etc. Ya que esto podría generar peligro de parcialidad en
el juez.
b) Imparcialidad objetiva: La imparcialidad objetiva está referida a que el sistema judicial
debe brindar las condiciones necesarias para evitar que el juez caiga en el vicio de la par
cialidad, es decir que las normas que regulan su actuación deben de buscar que el juez no
tenga prejuicios o favorezca alguna parte sobre otraen base al contacto que ha tenido con
la causa.
4. LOS MODELOS DE JUEZ
La función del Juez en una sociedad democrática ha evolucionada a la parqueel sistema polí
tico democrático, generando nuevos contenidos. Así tenemos:
- Jueces según las concepciones del Estado Liberal revolucionario
Para John Locke el Poder legislativo se convierte en el primer poderdel Estado, porque es
el que está facultado para dictar las leyes que son necesarias para garantizar, a los hom
bres, el disfrute de sus propiedades en paz. Es el poder que debe preservar a la sociedad,
por ello se convierte en el poder supremo del Estado. La ley se legitima en base al poder
concedido, por la mayoría, a los elegidos como integrantes del poder legislativo.
La autoridad legislativa no puede gobernar mediante decretos extemporáneos y arbitra
rios, sino que debe administrar justicia, decidiendo sobre los derechos de los súbditos,
guiándose por las leyes preestablecidas y sirviéndose de jueces autorizados. No se puede
gobernarsin leyes establecidas, porque ello puede propiciar un poder arbitrarioy absolu
to, colocando al hombre en una situación peora la del estado de naturaleza.
En el pensamiento de Locke no se describe la existencia de la función de decidir las con
troversias como un poder del Estado, ni como una función independiente del Ejecutivo.
Como veremos líneas abajo, con Montesquieu, le corresponde a él, el considerar la fun
ción jurisdiccional como independiente, autónoma, de las otras funciones del Estado.
Para Montesquieu el ideal político que defiende es el de la consecución de la máxima
libertad aunada a la necesaria autoridad política. Rechaza abiertamente las formas de
gobierno despóticas. Pero, para garantizarla al máximo considera que es imprescindible
la separación de poderes. Muy influenciado por Locke, desarrolla la concepción liberal de
éste, y además de considerar la necesidad de separar el poder ejecutivo del poder legis
lativo, piensa que también es preciso separar el poder judicial. Esta separación de los tres
poderes ha sido asumiday aplicada por todos los gobiernos democráticos posteriores.
- Jueces en el Estado de Derecho Legalista
Los jueces sólo tienen una legitimidad de “técnica”, y esta vinculación a la ley, configuran
la base de un modelo de juez que le es propio al Estado de Derecho legal. Se trata del juez
neutral, sin ideología, aséptico, apolítico. Es la boca que pronuncia las palabras de la ley.
Y así, garantizar la certeza y previsibilidad de las decisiones judiciales y la igualdad en la
aplicación de la ley, se convierten en sus objetivos existenciales. Hablar de discrecionali-
dad en estas circunstancias era herético.
