UBILEX
Jueces en el Estado Constitucional de Derecho
El Estado Constitucional es un estadio más de la idea de Estado de Derecho; o mejor, su
culminación, si el Estado Legislativo de Derecho había supuesto la sumisión del juez a
la ley, el Estado Constitucional de Derecho supone que éste y también el legislador vie
nen sometidos a derecho, en este caso, a la Constitución. Es en este contexto donde las
decisiones justas ya no se agotan en la correspondencia con el texto legal, sino -p rin c i
palmente- con la correspondencia con los principios constitucionales. Es entonces que
la vinculación del juez al sistema jurídico se extiende a algo más abstracto e impreciso,
como son los principios, siendo éstos el límite de clausura del sistema.
- Jueces en el Common Law anglosajón
Se configuró la independencia judicial luego de arduas e históricas batallas. A la actuali
dad, la expresión de dicha independencia está dada en la inamovilidad y no responsabili
dad del juez,y a la li bertad para tomar determi naciones cotejándolas con los precedentes
judiciales. Los jueces, una vez elegidos, no pueden ser removidos, salvo por resolución de
ambas Cámaras del Parlamento, lo que constituye un verdadero juicio político. Por otro
lado, no son responsables por las decisiones que adopten en los procesos en los que in
tervienen. En el caso de los Estados Unidos de Norteamérica, estas garantías que tienen
los jueces están constitucionalizadas. Si bien, son aspectos institucionales que brindan
un marco para la actuación de los jueces, son aspectos importantes porque garantizan la
actuación independiente de los jueces norteamericanos.
Entre las características destacadas a la función judicial, se señala las siguientes: (i) servir
de árbitro, porque tiene lugar -y es condición indispensable cuando existe un litigio; (ii)
pronunciarse sobre casos particularesy no sobre principios generales, porque cuando un
juez decide una cuestión particular destruye un principio general; (iii) no poder actuar
más que cuando se acude a él, esto es, cuando se le somete una causa; porque la función
judicial carece de acción, es decir, es necesario ponerla en movimiento para que actué.
- Jueces de Europa Continental
Se estableció la carrera judicial, apareciendo la figura del juez funcionario. El Juez no es
un profesional experimentado y prestigioso que, como culminación de su carrera, es lla
mado a la judicatura, sino un abogado que aspira a hacer carrera a través de los distintos
escalones de la función. En este sistema, que también es el que impera en Latinoamérica,
los problemas centrales en torno al tema de la independencia judicial son: el ingreso a la
judicatura, la inamovilidad en el cargo, la responsabilidad por sus actos, entre otros.
- Juez en el Estado de Derecho Moderno-Estado Constitucional
El Estado de Derecho moderno es el Estado Constitucional, donde el juzgador cobra un
papel relevante, porque interviene en el proceso de producción de la norma al resolver el
caso concreto, interpretándola con discrecionalidad e independencia, validándola consti
tucionalmente, para brindarsoluciones razonablesyjustas.
Su independencia e imparcialidad se traduce en la exigencia de racionalidad de las deci
siones, y ello está vinculado a la argumentación jurídica. Una decisión razonable es una
