decisión que contiene argumentos que la justifican, donde encontraremos razones ex
presadas con logicidad.
5. PERFIL DEL JUEZ ¥ FISCAL
Perfil requerido para ejercer adecuadamente la magistratura en el Perú (BASES PARA LA RE
CULACIÓN DE LA CARRERA JUDICIAL Y FISCAL. Lima: Justicia Viva, 2004, p. 39):
i) Sólida formación jurídica, que incluya la capacidad para interpretar normas creativamen
te;
ii) Capacidad para razonar el orden jurídico a través de casos concretos;
iii) Aptitud para identificar los conflictos sociales bajo juzgamiento;
iv) Visión crítica del funcionamiento actual del sistema de justicia;
v) Condiciones para ejercer la función con la independencia propia de una institucional¡dad
democrática; y,
vi) Trayectoria personal éticamente irreprochable.
6. LA CELERIDAD Y ECONOMÍA PROCESAL
Principio de Celeridad Procesal: La celeridad procesal aparece como un principio dirigido a la
actividad procesal, sea del órgano jurisdiccional como del órgano fiscal, a fin de que las d ili
gencias judiciales se realicen con la prontitud debida, dejando de lado cualquier posibilidad
que implique demora en el desarrollo y continuidad del procedimiento. “El principio de celeridad
procesal se expresa a través de diversas instituciones del proceso, por ejemplo, la perentoriedad e im pro-
rrogabilidad de los plazos. ',
